window.CODEMAP = {
"00_math_toolkit.py:D04Rng": {"file": "00_math_toolkit.py", "start": 2250, "end": 2292, "src": "class D04Rng:\n    \"\"\"The random stream of Num.rng(seed) in lib/num.js: mulberry32 uniforms, Box-Muller normals.\n\n    uniforms(n) and normals(n) return the next n draws in the order that n calls of\n    uniform() or normal() make in JavaScript, including the spare second normal of a\n    Box-Muller pair.\n    \"\"\"\n\n    def __init__(self, seed=1):\n        self.seed = int(seed) & 0xFFFFFFFF\n        self.k = 0              # uniforms drawn so far\n        self.spare = None       # the unused sine half of the last Box-Muller pair\n\n    def uniforms(self, n):\n        k = np.arange(self.k + 1, self.k + n + 1, dtype=np.uint64)\n        self.k += n\n        a = (np.uint64(self.seed) + k * _C32) & _M32            # the counter\n        t = ((a ^ (a >> np.uint64(15))) * (a | np.uint64(1))) & _M32\n        t ^= (t + ((t ^ (t >> np.uint64(7))) * (t | np.uint64(61)))) & _M32\n        return ((t ^ (t >> np.uint64(14))) & _M32).astype(float) / 4294967296.0\n\n    def uniform(self, lo=0.0, hi=1.0):\n        return lo + (hi - lo) * float(self.uniforms(1)[0])\n\n    def normals(self, n):\n        out = []\n        if n > 0 and self.spare is not None:\n            out.append(self.spare)\n            self.spare = None\n        m = n - len(out)\n        if m > 0:\n            pairs = (m + 1) // 2\n            u = self.uniforms(2 * pairs)\n            u1, u2 = 1.0 - u[0::2], u[1::2]          # u1 in (0, 1], so log(u1) is finite\n            r = np.sqrt(-2.0 * np.log(u1))\n            z = np.empty(2 * pairs)\n            z[0::2] = r * np.cos(2 * np.pi * u2)\n            z[1::2] = r * np.sin(2 * np.pi * u2)\n            if m % 2:\n                self.spare = float(z[-1])\n                z = z[:-1]\n            out.extend(z.tolist())\n        return np.array(out, dtype=float)\n", "doc": "The random stream of Num.rng(seed) in lib/num.js: mulberry32 uniforms, Box-Muller normals.\n\nuniforms(n) and normals(n) return the next n draws in the order that n calls of\nuniform() or normal() make in JavaScript, including the spare second normal of a\nBox-Muller pair.", "marimo": true},
"00_math_toolkit.py:_d02_sign": {"file": "00_math_toolkit.py", "start": 620, "end": 627, "src": "def _d02_sign(v):\n    \"\"\"Flip v so its entry of largest magnitude is positive (first one on a tie).\"\"\"\n    v = np.asarray(v, dtype=float)\n    k = 0\n    for i in range(len(v)):\n        if abs(v[i]) > abs(v[k]) + 1e-12:\n            k = i\n    return -v if v[k] < 0 else v\n", "doc": "Flip v so its entry of largest magnitude is positive (first one on a tie).", "marimo": true},
"00_math_toolkit.py:d01_classify_2x2": {"file": "00_math_toolkit.py", "start": 315, "end": 323, "src": "def d01_classify_2x2(A, b):\n    \"\"\"'one' (with x), 'none', or 'infinite' (with a solution x and a null direction) for A x = b.\"\"\"\n    A, b = np.asarray(A, dtype=float), np.asarray(b, dtype=float)\n    rA, rAb = d01_rank(A), d01_rank(np.column_stack([A, b]))\n    if rA == 2:\n        return {\"status\": \"one\", \"x\": np.linalg.solve(A, b).tolist(), \"rankA\": rA, \"rankAb\": rAb}\n    if rA == rAb:\n        return {\"status\": \"infinite\", \"x\": (np.linalg.pinv(A) @ b).tolist(), \"rankA\": rA, \"rankAb\": rAb}\n    return {\"status\": \"none\", \"x\": None, \"rankA\": rA, \"rankAb\": rAb}\n", "doc": "'one' (with x), 'none', or 'infinite' (with a solution x and a null direction) for A x = b.", "marimo": true},
"00_math_toolkit.py:d01_compose": {"file": "00_math_toolkit.py", "start": 213, "end": 218, "src": "def d01_compose(B, A):\n    \"\"\"The matrix of 'first A, then B': (BA)[i][j] = row i of B . column j of A.\"\"\"\n    B, A = np.asarray(B, dtype=float), np.asarray(A, dtype=float)\n    if B.shape[1] != A.shape[0]:\n        raise ValueError(f\"shapes {B.shape} and {A.shape} do not compose\")\n    return (B @ A).tolist()\n", "doc": "The matrix of 'first A, then B': (BA)[i][j] = row i of B . column j of A.", "marimo": true},
"00_math_toolkit.py:d01_consistency": {"file": "00_math_toolkit.py", "start": 373, "end": 377, "src": "def d01_consistency(A, b):\n    \"\"\"rank A, rank [A | b], and whether A x = b has a solution (ranks equal).\"\"\"\n    A, b = np.asarray(A, dtype=float), np.asarray(b, dtype=float)\n    rA, rAb = d01_rank(A), d01_rank(np.column_stack([A, b]))\n    return {\"rankA\": rA, \"rankAb\": rAb, \"consistent\": rA == rAb}\n", "doc": "rank A, rank [A | b], and whether A x = b has a solution (ranks equal).", "marimo": true},
"00_math_toolkit.py:d01_coords": {"file": "00_math_toolkit.py", "start": 79, "end": 90, "src": "def d01_coords(u, w, x):\n    \"\"\"Coordinates (c1, c2) of x in the basis (u, w) of the plane: c1 u + c2 w = x.\n\n    Solves the 2x2 system [u w] c = x by Cramer's rule; None when u and w are parallel.\n    \"\"\"\n    u, w, x = (np.asarray(t, dtype=float) for t in (u, w, x))\n    det = u[0] * w[1] - u[1] * w[0]\n    if abs(det) <= 1e-12 * max(1.0, np.abs(np.r_[u, w]).max() ** 2):\n        return None\n    c1 = (x[0] * w[1] - x[1] * w[0]) / det\n    c2 = (u[0] * x[1] - u[1] * x[0]) / det\n    return [float(c1), float(c2)]\n", "doc": "Coordinates (c1, c2) of x in the basis (u, w) of the plane: c1 u + c2 w = x.\n\nSolves the 2x2 system [u w] c = x by Cramer's rule; None when u and w are parallel.", "marimo": true},
"00_math_toolkit.py:d01_det2": {"file": "00_math_toolkit.py", "start": 200, "end": 203, "src": "def d01_det2(A):\n    \"\"\"ad - bc for A = [[a, b], [c, d]]: the signed area of the image of the unit square.\"\"\"\n    (a, b), (c, d) = np.asarray(A, dtype=float)\n    return float(a * d - b * c)\n", "doc": "ad - bc for A = [[a, b], [c, d]]: the signed area of the image of the unit square.", "marimo": true},
"00_math_toolkit.py:d01_dot_angle": {"file": "00_math_toolkit.py", "start": 101, "end": 109, "src": "def d01_dot_angle(a, b):\n    \"\"\"Dot product, lengths, cosine and angle (degrees) of two vectors (slide dot-product).\"\"\"\n    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)\n    dot = float(a @ b)\n    na, nb = float(np.linalg.norm(a)), float(np.linalg.norm(b))\n    if na == 0.0 or nb == 0.0:\n        return {\"dot\": dot, \"norm_a\": na, \"norm_b\": nb, \"cos\": None, \"deg\": None}\n    c = max(-1.0, min(1.0, dot / (na * nb)))\n    return {\"dot\": dot, \"norm_a\": na, \"norm_b\": nb, \"cos\": c, \"deg\": float(np.degrees(np.arccos(c)))}\n", "doc": "Dot product, lengths, cosine and angle (degrees) of two vectors (slide dot-product).", "marimo": true},
"00_math_toolkit.py:d01_four_subspaces": {"file": "00_math_toolkit.py", "start": 394, "end": 411, "src": "def d01_four_subspaces(A):\n    \"\"\"Bases and dimensions of Col(A), Row(A), Null(A) and Null(A^T) read off the RREF.\n\n    Col: the pivot columns of A itself. Row: the nonzero rows of the RREF. Null: the special\n    solutions. These bases are not orthonormal; deck 02 builds orthonormal ones.\n    \"\"\"\n    A = np.asarray(A, dtype=float)\n    m, n = A.shape\n    rr = d01_rref_steps(A)\n    r = rr[\"rank\"]\n    return {\n        \"rank\": r, \"pivots\": rr[\"pivots\"],\n        \"col\": [A[:, j].tolist() for j in rr[\"pivots\"]],\n        \"row\": rr[\"R\"][:r],\n        \"null\": d01_null_basis(A),\n        \"left_null\": d01_null_basis(A.T),\n        \"dims\": {\"col\": r, \"row\": r, \"null\": n - r, \"left_null\": m - r},\n    }\n", "doc": "Bases and dimensions of Col(A), Row(A), Null(A) and Null(A^T) read off the RREF.\n\nCol: the pivot columns of A itself. Row: the nonzero rows of the RREF. Null: the special\nsolutions. These bases are not orthonormal; deck 02 builds orthonormal ones.", "marimo": true},
"00_math_toolkit.py:d01_goal_dims": {"file": "00_math_toolkit.py", "start": 465, "end": 468, "src": "def d01_goal_dims(G):\n    \"\"\"Dimension n - rank(G) of the set of velocities v with G v = b_G (when consistent).\"\"\"\n    G = np.atleast_2d(np.asarray(G, dtype=float))\n    return int(G.shape[1] - d01_rank(G))\n", "doc": "Dimension n - rank(G) of the set of velocities v with G v = b_G (when consistent).", "marimo": true},
"00_math_toolkit.py:d01_independence_det": {"file": "00_math_toolkit.py", "start": 92, "end": 99, "src": "def d01_independence_det(h):\n    \"\"\"det and rank of [v1 v2 v3] with v1 = (1,0,1), v2 = (0,1,1), v3 = (1,1,2+h).\n\n    The determinant equals h, so the three vectors are dependent exactly when h = 0\n    (then v1 + v2 - v3 = 0). Slide linear-independence.\n    \"\"\"\n    V = np.array([[1.0, 0.0, 1.0], [0.0, 1.0, 1.0], [1.0, 1.0, 2.0 + h]]).T\n    return {\"det\": float(np.linalg.det(V)), \"rank\": int(np.linalg.matrix_rank(V))}\n", "doc": "det and rank of [v1 v2 v3] with v1 = (1,0,1), v2 = (0,1,1), v3 = (1,1,2+h).\n\nThe determinant equals h, so the three vectors are dependent exactly when h = 0\n(then v1 + v2 - v3 = 0). Slide linear-independence.", "marimo": true},
"00_math_toolkit.py:d01_inv2": {"file": "00_math_toolkit.py", "start": 205, "end": 211, "src": "def d01_inv2(A):\n    \"\"\"(1/(ad - bc)) [[d, -b], [-c, a]], or None when ad - bc = 0 (slide identity-and-inverse).\"\"\"\n    (a, b), (c, d) = np.asarray(A, dtype=float)\n    det = a * d - b * c\n    if det == 0.0:\n        return None\n    return (np.array([[d, -b], [-c, a]]) / det).tolist()\n", "doc": "(1/(ad - bc)) [[d, -b], [-c, a]], or None when ad - bc = 0 (slide identity-and-inverse).", "marimo": true},
"00_math_toolkit.py:d01_min_norm_solution": {"file": "00_math_toolkit.py", "start": 442, "end": 449, "src": "def d01_min_norm_solution(A, b):\n    \"\"\"The shortest solution pinv(A) b of A x = b (the least-squares one if A x = b has none).\n\n    For A23 x = (2, 1) it is (1, 0, 1), the point t = (b1 + b2)/3 = 1 of the line\n    (2, 1, 0) + t(-1, -1, 1) (slide solution-set). Deck 02 builds the pseudoinverse.\n    \"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    return (np.linalg.pinv(A) @ np.asarray(b, dtype=float) + 0.0).tolist()\n", "doc": "The shortest solution pinv(A) b of A x = b (the least-squares one if A x = b has none).\n\nFor A23 x = (2, 1) it is (1, 0, 1), the point t = (b1 + b2)/3 = 1 of the line\n(2, 1, 0) + t(-1, -1, 1) (slide solution-set). Deck 02 builds the pseudoinverse.", "marimo": true},
"00_math_toolkit.py:d01_nonsquare_maps": {"file": "00_math_toolkit.py", "start": 235, "end": 251, "src": "def d01_nonsquare_maps(t=0.0, s=(1.0, 0.5)):\n    \"\"\"The 2x3 map A23 and the 3x2 map B32 = A23^T (slides wide-matrix-flattens, tall-matrix-embeds).\n\n    x(t) = (2, 1, 0) + t (-1, -1, 1) maps to (2, 1) for every t; the unit cube maps onto a\n    hexagon; B32 s = (s1, s2, s1 + s2) lies on the plane z = x + y, which misses (0, 0, 1).\n    \"\"\"\n    x = np.array([2.0, 1.0, 0.0]) + t * np.array([-1.0, -1.0, 1.0])\n    cube = [np.array([i, j, k], dtype=float) for i in (0, 1) for j in (0, 1) for k in (0, 1)]\n    image = sorted({tuple((D01_A23 @ v).tolist()) for v in cube})\n    B32 = D01_A23.T\n    return {\n        \"x\": x.tolist(), \"Ax\": (D01_A23 @ x).tolist(), \"cube_image\": image,\n        \"Bs\": (B32 @ np.asarray(s, dtype=float)).tolist(),\n        \"rank_A23\": int(np.linalg.matrix_rank(D01_A23)), \"rank_B32\": int(np.linalg.matrix_rank(B32)),\n        # (0, 0, 1) is off the plane z = x + y: its z - x - y is 1, not 0.\n        \"e3_offset\": 1.0 - 0.0 - 0.0,\n    }\n", "doc": "The 2x3 map A23 and the 3x2 map B32 = A23^T (slides wide-matrix-flattens, tall-matrix-embeds).\n\nx(t) = (2, 1, 0) + t (-1, -1, 1) maps to (2, 1) for every t; the unit cube maps onto a\nhexagon; B32 s = (s1, s2, s1 + s2) lies on the plane z = x + y, which misses (0, 0, 1).", "marimo": true},
"00_math_toolkit.py:d01_null_basis": {"file": "00_math_toolkit.py", "start": 379, "end": 392, "src": "def d01_null_basis(A):\n    \"\"\"Special solutions of A x = 0 from the RREF: one per free column (free entry 1, others 0).\"\"\"\n    A = np.asarray(A, dtype=float)\n    n = A.shape[1]\n    rr = d01_rref_steps(A)\n    R, piv = np.array(rr[\"R\"]), rr[\"pivots\"]\n    out = []\n    for f in (j for j in range(n) if j not in piv):\n        x = np.zeros(n)\n        x[f] = 1.0\n        for i, p in enumerate(piv):\n            x[p] = -R[i, f]\n        out.append((x + 0.0).tolist())  # + 0.0 turns -0.0 into 0.0\n    return out\n", "doc": "Special solutions of A x = 0 from the RREF: one per free column (free entry 1, others 0).", "marimo": true},
"00_math_toolkit.py:d01_parallelogram_area": {"file": "00_math_toolkit.py", "start": 225, "end": 233, "src": "def d01_parallelogram_area(a, c, b, d):\n    \"\"\"Area of the parallelogram on columns (a, c) and (b, d) by cutting its bounding box.\n\n    Box (a + b)(c + d) minus two triangles of area ac/2, two of area bd/2 and two\n    rectangles bc. Valid for 0 <= b <= a and 0 <= c <= d (slide determinant-derivation).\n    \"\"\"\n    box = (a + b) * (c + d)\n    area = box - a * c - b * d - 2 * b * c\n    return {\"box\": box, \"ac\": a * c, \"bd\": b * d, \"2bc\": 2 * b * c, \"area\": area, \"det\": a * d - b * c}\n", "doc": "Area of the parallelogram on columns (a, c) and (b, d) by cutting its bounding box.\n\nBox (a + b)(c + d) minus two triangles of area ac/2, two of area bd/2 and two\nrectangles bc. Valid for 0 <= b <= a and 0 <= c <= d (slide determinant-derivation).", "marimo": true},
"00_math_toolkit.py:d01_pnorm": {"file": "00_math_toolkit.py", "start": 111, "end": 121, "src": "def d01_pnorm(x, p):\n    \"\"\"The p-norm (sum |x_i|^p)^(1/p) for p >= 1; p = inf gives max |x_i|.\"\"\"\n    x = np.abs(np.asarray(x, dtype=float))\n    if p == np.inf:\n        return float(x.max())\n    if p < 1:\n        raise ValueError(\"the p-norm is a norm only for p >= 1\")\n    m = x.max()\n    if m == 0.0:\n        return 0.0\n    return float(m * np.sum((x / m) ** p) ** (1.0 / p))\n", "doc": "The p-norm (sum |x_i|^p)^(1/p) for p >= 1; p = inf gives max |x_i|.", "marimo": true},
"00_math_toolkit.py:d01_pnorms": {"file": "00_math_toolkit.py", "start": 123, "end": 125, "src": "def d01_pnorms(x):\n    \"\"\"The 1-, 2- and infinity-norms of x (slides norms and unit-balls).\"\"\"\n    return [d01_pnorm(x, 1), d01_pnorm(x, 2), d01_pnorm(x, np.inf)]\n", "doc": "The 1-, 2- and infinity-norms of x (slides norms and unit-balls).", "marimo": true},
"00_math_toolkit.py:d01_rank": {"file": "00_math_toolkit.py", "start": 310, "end": 313, "src": "def d01_rank(A):\n    \"\"\"Numerical rank with numpy's default tolerance (the same as Num.rank).\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    return int(np.linalg.matrix_rank(A)) if A.size else 0\n", "doc": "Numerical rank with numpy's default tolerance (the same as Num.rank).", "marimo": true},
"00_math_toolkit.py:d01_rank_nullity_table": {"file": "00_math_toolkit.py", "start": 425, "end": 440, "src": "def d01_rank_nullity_table():\n    \"\"\"(name, m, n, rank, dim Null) for the matrices of the rank-nullity slide.\"\"\"\n    mats = {\n        \"A23 (flattens)\": [[1, 0, 1], [0, 1, 1]],\n        \"M (columns v1, v2, v1 + v2)\": [[1, 0, 1], [0, 1, 1], [1, 1, 2]],\n        \"A34\": [[1, 2, 0, 1], [2, 4, 1, 4], [3, 6, 1, 5]],\n        \"B32 = A23^T (embeds)\": [[1, 0], [0, 1], [1, 1]],\n        \"I3\": np.eye(3).tolist(),\n        \"table E\": [[1, 1, 1, 1], [0.5, 0.5, -0.5, -0.5], [0.5, -0.5, -0.5, 0.5]],\n    }\n    rows = []\n    for name, X in mats.items():\n        X = np.asarray(X, dtype=float)\n        r = d01_rank(X)\n        rows.append((name, X.shape[0], X.shape[1], r, X.shape[1] - r))\n    return rows\n", "doc": "(name, m, n, rank, dim Null) for the matrices of the rank-nullity slide.", "marimo": true},
"00_math_toolkit.py:d01_rref_steps": {"file": "00_math_toolkit.py", "start": 325, "end": 371, "src": "def d01_rref_steps(A, tol=None):\n    \"\"\"Gauss-Jordan elimination with a log of every row operation.\n\n    The rule of Num.rref(A) in lib/num.js ('first' pivots): for each column, take the first\n    row at or below the current one with a nonzero entry, swap it up, scale it to make the\n    pivot 1, and subtract multiples of it from every other row. Entries with |x| <= tol\n    (default 1e-10 max|a_ij|) are set to 0. Each step is (op, i, j, k, text): 'swap' rows\n    i, j; 'scale' R_i <- k R_i; 'add' R_i <- R_i + k R_j (rows 0-based, text 1-based).\n    \"\"\"\n    M = np.array(A, dtype=float)\n    m, n = M.shape\n    tol = 1e-10 * np.abs(M).max() if tol is None else tol\n    steps, pivots = [], []\n\n    def clean():\n        M[np.abs(M) <= tol] = 0.0\n\n    clean()\n    r = 0\n    for c in range(n):\n        if r >= m:\n            break\n        rows = [i for i in range(r, m) if abs(M[i, c]) > tol]\n        if not rows:\n            continue\n        p = rows[0]\n        if p != r:\n            M[[r, p]] = M[[p, r]]\n            steps.append((\"swap\", r, p, 0.0, f\"R{r + 1} <-> R{p + 1}\", M.copy()))\n        piv = M[r, c]\n        if piv != 1.0:\n            M[r] = M[r] / piv\n            M[r, c] = 1.0\n            clean()\n            steps.append((\"scale\", r, r, 1.0 / piv, f\"R{r + 1} <- ({1.0 / piv:g}) R{r + 1}\", M.copy()))\n        for i in range(m):\n            if i == r or M[i, c] == 0.0:\n                continue\n            f = M[i, c]\n            M[i] = M[i] - f * M[r]\n            M[i, c] = 0.0\n            clean()\n            steps.append((\"add\", i, r, -f, f\"R{i + 1} <- R{i + 1} + ({-f:g}) R{r + 1}\", M.copy()))\n        pivots.append(c)\n        r += 1\n    return {\"R\": M.tolist(), \"pivots\": pivots, \"rank\": len(pivots),\n            \"steps\": [s[:5] for s in steps], \"matrices\": [s[5].tolist() for s in steps]}\n", "doc": "Gauss-Jordan elimination with a log of every row operation.\n\nThe rule of Num.rref(A) in lib/num.js ('first' pivots): for each column, take the first\nrow at or below the current one with a nonzero entry, swap it up, scale it to make the\npivot 1, and subtract multiples of it from every other row. Entries with |x| <= tol\n(default 1e-10 max|a_ij|) are set to 0. Each step is (op, i, j, k, text): 'swap' rows\ni, j; 'scale' R_i <- k R_i; 'add' R_i <- R_i + k R_j (rows 0-based, text 1-based).", "marimo": true},
"00_math_toolkit.py:d01_solution_set": {"file": "00_math_toolkit.py", "start": 413, "end": 423, "src": "def d01_solution_set(A, b):\n    \"\"\"Particular solution (free variables 0) and null-space basis of A x = b; None if inconsistent.\"\"\"\n    A, b = np.asarray(A, dtype=float), np.asarray(b, dtype=float)\n    n = A.shape[1]\n    rr = d01_rref_steps(np.column_stack([A, b]))\n    if n in rr[\"pivots\"]:\n        return {\"consistent\": False, \"particular\": None, \"null\": d01_null_basis(A)}\n    x = np.zeros(n)\n    for i, p in enumerate(rr[\"pivots\"]):\n        x[p] = rr[\"R\"][i][n]\n    return {\"consistent\": True, \"particular\": x.tolist(), \"null\": d01_null_basis(A)}\n", "doc": "Particular solution (free variables 0) and null-space basis of A x = b; None if inconsistent.", "marimo": true},
"00_math_toolkit.py:d01_stacked_ranks": {"file": "00_math_toolkit.py", "start": 470, "end": 481, "src": "def d01_stacked_ranks(N, G, bG):\n    \"\"\"Ranks of N, [N; G] and [N G | 0 b_G], consistency, dim Sol(N & G), and the minimum\n    number of velocity commands rank([N; G]) - rank(N) (Hou & Mason 2019, eq. 8).\"\"\"\n    N, G = np.atleast_2d(np.asarray(N, dtype=float)), np.atleast_2d(np.asarray(G, dtype=float))\n    bG = np.atleast_1d(np.asarray(bG, dtype=float))\n    n = N.shape[1]\n    NG = np.vstack([N, G])\n    aug = np.column_stack([NG, np.r_[np.zeros(N.shape[0]), bG]])\n    rN, rNG, rAug = d01_rank(N), d01_rank(NG), d01_rank(aug)\n    cons = rNG == rAug\n    return {\"rankN\": rN, \"rankNG\": rNG, \"rankAug\": rAug, \"consistent\": cons,\n            \"dimSol\": n - rNG if cons else None, \"nav\": rNG - rN}\n", "doc": "Ranks of N, [N; G] and [N G | 0 b_G], consistency, dim Sol(N & G), and the minimum\nnumber of velocity commands rank([N; G]) - rank(N) (Hou & Mason 2019, eq. 8).", "marimo": true},
"00_math_toolkit.py:d01_table_legs": {"file": "00_math_toolkit.py", "start": 451, "end": 463, "src": "def d01_table_legs(W=100.0, t=0.0, half=0.5):\n    \"\"\"Leg forces of a square table with legs at (+-half, +-half) carrying W at its centre.\n\n    Legs 1-4 at (h, h), (-h, h), (-h, -h), (h, -h). Rows of E: vertical force, moment about\n    the x axis (y_i f_i), moment about the y axis (x_i f_i). E f = (W, 0, 0) has the\n    solutions f = (W/4)(1, 1, 1, 1) + t (1, -1, 1, -1); all legs push when |t| <= W/4.\n    \"\"\"\n    h = half\n    E = np.array([[1, 1, 1, 1], [h, h, -h, -h], [h, -h, -h, h]], dtype=float)\n    f = W / 4 * np.ones(4) + t * np.array([1.0, -1.0, 1.0, -1.0])\n    return {\"E\": E.tolist(), \"rank\": d01_rank(E), \"f\": f.tolist(),\n            \"residual\": (E @ f - np.array([W, 0.0, 0.0])).tolist(),\n            \"pushing\": bool(np.all(f >= 0)), \"t_range\": [-W / 4, W / 4]}\n", "doc": "Leg forces of a square table with legs at (+-half, +-half) carrying W at its centre.\n\nLegs 1-4 at (h, h), (-h, h), (-h, -h), (h, -h). Rows of E: vertical force, moment about\nthe x axis (y_i f_i), moment about the y axis (x_i f_i). E f = (W, 0, 0) has the\nsolutions f = (W/4)(1, 1, 1, 1) + t (1, -1, 1, -1); all legs push when |t| <= W/4.", "marimo": true},
"00_math_toolkit.py:d01_transpose_check": {"file": "00_math_toolkit.py", "start": 220, "end": 223, "src": "def d01_transpose_check(A, x, y):\n    \"\"\"(A x) . y and x . (A^T y), which are equal for every A, x, y (slide transpose).\"\"\"\n    A, x, y = (np.asarray(t, dtype=float) for t in (A, x, y))\n    return [float((A @ x) @ y), float(x @ (A.T @ y))]\n", "doc": "(A x) . y and x . (A^T y), which are equal for every A, x, y (slide transpose).", "marimo": true},
"00_math_toolkit.py:d01_vector_length": {"file": "00_math_toolkit.py", "start": 74, "end": 77, "src": "def d01_vector_length(v):\n    \"\"\"Euclidean length sqrt(v1^2 + ... + vn^2) of a vector (slide vectors-arrows-lists).\"\"\"\n    v = np.asarray(v, dtype=float)\n    return float(np.sqrt(np.sum(v * v)))\n", "doc": "Euclidean length sqrt(v1^2 + ... + vn^2) of a vector (slide vectors-arrows-lists).", "marimo": true},
"00_math_toolkit.py:d02_cholesky_2x2_steps": {"file": "00_math_toolkit.py", "start": 934, "end": 961, "src": "def d02_cholesky_2x2_steps(A, b=None):\n    \"\"\"Cholesky A = L L^T of a symmetric 2x2 matrix entry by entry (slides cholesky,\n    cholesky-exists), and the two triangular solves when b is given.\n\n    L11 = sqrt(a11), L21 = a21 / L11, L22 = sqrt(a22 - L21^2). The factorization fails\n    (ok = False) when a11 <= 0 or a22 - L21^2 <= 0, which happens exactly when A is not\n    positive definite.\n    \"\"\"\n    A = np.asarray(A, dtype=float)\n    out = {\"L11\": None, \"L21\": None, \"L22sq\": None, \"L22\": None, \"ok\": False, \"L\": None,\n           \"w\": None, \"z\": None}\n    if A[0, 0] <= 0:\n        return out\n    L11 = float(np.sqrt(A[0, 0]))\n    L21 = float(A[1, 0] / L11)\n    L22sq = float(A[1, 1] - L21 * L21)\n    out.update(L11=L11, L21=L21, L22sq=L22sq)\n    if L22sq <= 1e-14 * max(1.0, abs(A[1, 1])):\n        return out\n    L22 = float(np.sqrt(L22sq))\n    out.update(L22=L22, ok=True, L=[[L11, 0.0], [L21, L22]])\n    if b is not None:\n        w1 = b[0] / L11\n        w2 = (b[1] - L21 * w1) / L22\n        z2 = w2 / L22\n        z1 = (w1 - L21 * z2) / L11\n        out.update(w=[float(w1), float(w2)], z=[float(z1), float(z2)])\n    return out\n", "doc": "Cholesky A = L L^T of a symmetric 2x2 matrix entry by entry (slides cholesky,\ncholesky-exists), and the two triangular solves when b is given.\n\nL11 = sqrt(a11), L21 = a21 / L11, L22 = sqrt(a22 - L21^2). The factorization fails\n(ok = False) when a11 <= 0 or a22 - L21^2 <= 0, which happens exactly when A is not\npositive definite.", "marimo": true},
"00_math_toolkit.py:d02_column_space_projection": {"file": "00_math_toolkit.py", "start": 1289, "end": 1299, "src": "def d02_column_space_projection(A, b):\n    \"\"\"Least squares as projection (slide ls-projection-3d): xhat from the normal equations,\n    p = A xhat, e = b - p, A^T e = 0, and the projector P = A (A^T A)^-1 A^T.\"\"\"\n    A = np.asarray(A, dtype=float)\n    b = np.asarray(b, dtype=float)\n    xhat = np.linalg.solve(A.T @ A, A.T @ b)\n    p = A @ xhat\n    return {\"AtA\": (A.T @ A).tolist(), \"Atb\": (A.T @ b).tolist(), \"xhat\": xhat.tolist(),\n            \"p\": p.tolist(), \"e\": (b - p).tolist(), \"Ate\": (A.T @ (b - p)).tolist(),\n            \"dist\": float(np.linalg.norm(b - p)),\n            \"P\": (A @ np.linalg.solve(A.T @ A, A.T)).tolist()}\n", "doc": "Least squares as projection (slide ls-projection-3d): xhat from the normal equations,\np = A xhat, e = b - p, A^T e = 0, and the projector P = A (A^T A)^-1 A^T.", "marimo": true},
"00_math_toolkit.py:d02_complement_split": {"file": "00_math_toolkit.py", "start": 729, "end": 741, "src": "def d02_complement_split(A, v):\n    \"\"\"Split v into its row-space and null-space parts (slide orthogonal-complement).\n\n    v_null is the projection of v onto NULL(A), v_row = v - v_null; coef solves\n    A^T coef = v_row, so v_row = sum_i coef_i (row i of A).\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    v = np.asarray(v, dtype=float)\n    N = d02_nullspace(A)\n    v_null = N.T @ (N @ v)\n    v_row = v - v_null\n    coef = np.linalg.lstsq(A.T, v_row, rcond=None)[0]\n    return {\"null\": N.tolist(), \"rows_dot_null\": (A @ N.T).ravel().tolist(),\n            \"v_null\": v_null.tolist(), \"v_row\": v_row.tolist(), \"coef\": coef.tolist()}\n", "doc": "Split v into its row-space and null-space parts (slide orthogonal-complement).\n\nv_null is the projection of v onto NULL(A), v_row = v - v_null; coef solves\nA^T coef = v_row, so v_row = sum_i coef_i (row i of A).", "marimo": true},
"00_math_toolkit.py:d02_cond": {"file": "00_math_toolkit.py", "start": 629, "end": 637, "src": "def d02_cond(A):\n    \"\"\"sigma_max / sigma_min, with inf when a singular value is below the numpy rank tolerance\n    (as lib/num.js cond(); numpy.linalg.cond would report about 1e16 instead).\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    s = np.linalg.svd(A, compute_uv=False)\n    tol = max(A.shape) * np.finfo(float).eps * (s[0] if s.size else 0.0)\n    if s.size == 0 or s[-1] <= tol:\n        return float(\"inf\")\n    return float(s[0] / s[-1])\n", "doc": "sigma_max / sigma_min, with inf when a singular value is below the numpy rank tolerance\n(as lib/num.js cond(); numpy.linalg.cond would report about 1e16 instead).", "marimo": true},
"00_math_toolkit.py:d02_crashing_index": {"file": "00_math_toolkit.py", "start": 1135, "end": 1146, "src": "def d02_crashing_index(J, C):\n    \"\"\"Hou & Mason 2021 eq. 9: cond([J_hat; C_hat]) with J_hat an orthonormal basis of the rows\n    of J and C_hat the rows of C scaled to unit length (slide row-normalization). Also the raw\n    cond([J; C]) for comparison.\"\"\"\n    J = np.atleast_2d(np.asarray(J, dtype=float))\n    C = np.atleast_2d(np.asarray(C, dtype=float))\n    _u, s, vt = np.linalg.svd(J)\n    tol = max(J.shape) * np.finfo(float).eps * s[0]\n    Jh = vt[: int(np.sum(s > tol))]\n    Ch = C / np.linalg.norm(C, axis=1, keepdims=True)\n    return {\"raw\": d02_cond(np.vstack([J, C])), \"index\": d02_cond(np.vstack([Jh, Ch])),\n            \"rows_J_hat\": int(Jh.shape[0])}\n", "doc": "Hou & Mason 2021 eq. 9: cond([J_hat; C_hat]) with J_hat an orthonormal basis of the rows\nof J and C_hat the rows of C scaled to unit length (slide row-normalization). Also the raw\ncond([J; C]) for comparison.", "marimo": true},
"00_math_toolkit.py:d02_definiteness_table": {"file": "00_math_toolkit.py", "start": 900, "end": 909, "src": "def d02_definiteness_table():\n    \"\"\"The three example matrices of slide positive-definite with their eigenvalues.\"\"\"\n    rows = []\n    for M in ([[2, 1], [1, 2]], [[1, 1], [1, 1]], [[1, 2], [2, 1]]):\n        q = d02_quadratic_form_axes(M)\n        rows.append({\"A\": M, \"values\": q[\"values\"], \"kind\": q[\"kind\"],\n                     \"det\": float(np.linalg.det(np.array(M, dtype=float)))})\n    z = np.array([1.0, -1.0])\n    return {\"rows\": rows, \"saddle_z\": z.tolist(),\n            \"saddle_value\": float(z @ np.array([[1.0, 2.0], [2.0, 1.0]]) @ z)}\n", "doc": "The three example matrices of slide positive-definite with their eigenvalues.", "marimo": true},
"00_math_toolkit.py:d02_drawer_conditioning": {"file": "00_math_toolkit.py", "start": 1108, "end": 1133, "src": "def d02_drawer_conditioning(theta_deg, eps_deg=0.0, b=1.0):\n    \"\"\"The drawer of slides drawer-setup and drawer-live.\n\n    Velocity v = (v_x, v_y) of the drawer (and of the hand holding its handle). The modeled\n    rail runs along x, so the constraint is n^T v = 0 with n = (0, 1). The hand commands\n    c^T v = b with c = (cos theta, sin theta), theta measured from the rail. The true rail is\n    turned by eps: n_true = (-sin eps, cos eps). Returns the condition number of the modeled\n    system [n; c], the modeled speed b / cos(theta), the velocity that solves the true system\n    (b / cos(theta - eps) along the true rail) and whether the true system has a solution.\n    \"\"\"\n    th, ep = np.radians(theta_deg), np.radians(eps_deg)\n    c = np.array([np.cos(th), np.sin(th)])\n    A_model = np.array([[0.0, 1.0], c])\n    A_true = np.array([[-np.sin(ep), np.cos(ep)], c])\n    out = {\"cond\": d02_cond(A_model), \"cond_true\": d02_cond(A_true),\n           \"cond_formula\": float(np.tan(np.radians(45.0 + theta_deg / 2))),\n           \"speed_model\": float(b / np.cos(th)) if abs(np.cos(th)) > 1e-12 else None,\n           \"T\": [[float(np.sin(th)), float(-np.cos(th))], [float(np.cos(th)), float(np.sin(th))]]}\n    ct = np.cos(th - ep)\n    if abs(ct) < 1e-12:\n        out.update(feasible=False, v_true=None, speed_true=None, ratio=None)\n    else:\n        v = np.linalg.solve(A_true, np.array([0.0, b]))\n        out.update(feasible=True, v_true=v.tolist(), speed_true=float(b / ct),\n                   ratio=float(np.cos(th) / ct) if out[\"speed_model\"] is not None else None)\n    return out\n", "doc": "The drawer of slides drawer-setup and drawer-live.\n\nVelocity v = (v_x, v_y) of the drawer (and of the hand holding its handle). The modeled\nrail runs along x, so the constraint is n^T v = 0 with n = (0, 1). The hand commands\nc^T v = b with c = (cos theta, sin theta), theta measured from the rail. The true rail is\nturned by eps: n_true = (-sin eps, cos eps). Returns the condition number of the modeled\nsystem [n; c], the modeled speed b / cos(theta), the velocity that solves the true system\n(b / cos(theta - eps) along the true rail) and whether the true system has a solution.", "marimo": true},
"00_math_toolkit.py:d02_eigen_2x2": {"file": "00_math_toolkit.py", "start": 840, "end": 867, "src": "def d02_eigen_2x2(A):\n    \"\"\"Eigenvalues of a 2x2 matrix from lambda^2 - tr(A) lambda + det(A) = 0 (slide eigen-2x2).\n\n    Real case: values in descending order and unit eigenvectors (largest entry positive).\n    Complex case: values None and complex = [real part, |imaginary part|].\n    \"\"\"\n    A = np.asarray(A, dtype=float)\n    tr = A[0, 0] + A[1, 1]\n    det = A[0, 0] * A[1, 1] - A[0, 1] * A[1, 0]\n    disc = tr * tr / 4 - det\n    out = {\"tr\": float(tr), \"det\": float(det), \"disc\": float(disc)}\n    if disc < -1e-14 * max(1.0, tr * tr):\n        out.update(real=False, values=None, vectors=None, complex=[tr / 2, float(np.sqrt(-disc))])\n        return out\n    s = np.sqrt(max(disc, 0.0))\n    vals = [tr / 2 + s, tr / 2 - s]\n    vecs = []\n    for lam in vals:\n        M = A - lam * np.eye(2)\n        r = M[0] if np.linalg.norm(M[0]) >= np.linalg.norm(M[1]) else M[1]\n        if np.linalg.norm(r) < 1e-12 * max(1.0, np.abs(A).max()):\n            v = np.array([1.0, 0.0]) if not vecs else np.array([0.0, 1.0])  # A = lam I\n        else:\n            v = np.array([-r[1], r[0]]) / np.linalg.norm(r)\n        k = 0 if abs(v[0]) >= abs(v[1]) - 1e-12 else 1\n        vecs.append((v if v[k] > 0 else -v).tolist())\n    out.update(real=True, values=[float(v) for v in vals], vectors=vecs, complex=None)\n    return out\n", "doc": "Eigenvalues of a 2x2 matrix from lambda^2 - tr(A) lambda + det(A) = 0 (slide eigen-2x2).\n\nReal case: values in descending order and unit eigenvectors (largest entry positive).\nComplex case: values None and complex = [real part, |imaginary part|].", "marimo": true},
"00_math_toolkit.py:d02_fragile_vs_infeasible": {"file": "00_math_toolkit.py", "start": 1148, "end": 1167, "src": "def d02_fragile_vs_infeasible(db=0.1):\n    \"\"\"The four panels of slide fragile-vs-infeasible, all built by d02_nearly_parallel_rows:\n    rows 90 deg apart, 2 deg apart, and parallel (0 deg), with b_2 moved by db; the fourth\n    panel is the parallel pair with db = 0. For each: ranks of A and [A | b], cond, the\n    least-squares solution (minimum norm), its residual |A z - b|, and how far z* = (1, 1) moved.\n    \"\"\"\n    out = []\n    for name, phi, d in ((\"well conditioned\", 90.0, db), (\"ill conditioned\", 2.0, db),\n                         (\"parallel, inconsistent\", 0.0, db), (\"parallel, consistent\", 0.0, 0.0)):\n        r = d02_nearly_parallel_rows(phi, d)\n        A, b = np.array(r[\"A\"]), np.array(r[\"b\"])\n        rA = int(np.linalg.matrix_rank(A))\n        rAb = int(np.linalg.matrix_rank(np.column_stack([A, b])))\n        z = np.linalg.pinv(A) @ b\n        out.append({\"name\": name, \"phi\": phi, \"db\": d, \"rank_A\": rA, \"rank_Ab\": rAb,\n                    \"cond\": d02_cond(A), \"z\": z.tolist(),\n                    \"residual\": float(np.linalg.norm(A @ z - b)),\n                    \"shift\": float(np.linalg.norm(z - 1.0)),\n                    \"solutions\": \"one\" if rA == 2 else (\"none\" if rAb > rA else \"a line\")})\n    return out\n", "doc": "The four panels of slide fragile-vs-infeasible, all built by d02_nearly_parallel_rows:\nrows 90 deg apart, 2 deg apart, and parallel (0 deg), with b_2 moved by db; the fourth\npanel is the parallel pair with db = 0. For each: ranks of A and [A | b], cond, the\nleast-squares solution (minimum norm), its residual |A z - b|, and how far z* = (1, 1) moved.", "marimo": true},
"00_math_toolkit.py:d02_goal_inclusion_toy": {"file": "00_math_toolkit.py", "start": 754, "end": 774, "src": "def d02_goal_inclusion_toy(b_goal=0.1):\n    \"\"\"Hou & Mason 2021 eq. 11-13 on a box on a rail pushed by a hand (slide rank-test).\n\n    v = (v_box, v_hx, v_hy). Contact: the hand touches the box's left face, so\n    v_box - v_hx = 0 (J); the hand may slide up and down the face. Goal: v_box = b_goal (G).\n    Two candidate velocity commands: hand x velocity (C1) or hand y velocity (C2).\n    \"\"\"\n    J = np.array([[1.0, -1.0, 0.0]])\n    G = np.array([[1.0, 0.0, 0.0]])\n    rank = np.linalg.matrix_rank\n    out = {\"rank_J\": int(rank(J)), \"rank_JG\": int(rank(np.vstack([J, G])))}\n    out[\"n_av_min\"] = out[\"rank_JG\"] - out[\"rank_J\"]\n    # One special solution of J v = 0, G v = b_goal (minimum norm, Hou 2021 eq. 28).\n    v_star = np.linalg.pinv(np.vstack([J, G])) @ np.array([0.0, b_goal])\n    out[\"v_star\"] = v_star.tolist()\n    for name, C in [(\"C1\", np.array([[0.0, 1.0, 0.0]])), (\"C2\", np.array([[0.0, 0.0, 1.0]]))]:\n        rJC = int(rank(np.vstack([J, C])))\n        rJCG = int(rank(np.vstack([J, C, G])))\n        out[name] = {\"rank_JC\": rJC, \"rank_JCG\": rJCG, \"included\": rJC == rJCG,\n                     \"b_C\": float((C @ v_star)[0])}\n    return out\n", "doc": "Hou & Mason 2021 eq. 11-13 on a box on a rail pushed by a hand (slide rank-test).\n\nv = (v_box, v_hx, v_hy). Contact: the hand touches the box's left face, so\nv_box - v_hx = 0 (J); the hand may slide up and down the face. Goal: v_box = b_goal (G).\nTwo candidate velocity commands: hand x velocity (C1) or hand y velocity (C2).", "marimo": true},
"00_math_toolkit.py:d02_gram_schmidt_qr": {"file": "00_math_toolkit.py", "start": 702, "end": 722, "src": "def d02_gram_schmidt_qr(vectors):\n    \"\"\"Classical Gram-Schmidt on a list of independent vectors (slide gram-schmidt).\n\n    Returns Q (orthonormal vectors as rows), R (upper triangular, R[i][j] = q_i . a_j for\n    i < j, R[j][j] = |w_j|), and w (the residual of each a_j after subtracting its\n    projections on q_1 .. q_{j-1}). Then a_j = sum_i R[i][j] q_i, i.e. A = Q^T R with the\n    a_j as the columns of A.\n    \"\"\"\n    V = [np.asarray(v, dtype=float) for v in vectors]\n    k = len(V)\n    Q, W = [], []\n    R = np.zeros((k, k))\n    for j, a in enumerate(V):\n        w = a.copy()\n        for i, q in enumerate(Q):\n            R[i, j] = q @ a\n            w = w - R[i, j] * q\n        R[j, j] = np.linalg.norm(w)\n        W.append(w)\n        Q.append(w / R[j, j])\n    return {\"Q\": np.array(Q).tolist(), \"R\": R.tolist(), \"w\": np.array(W).tolist()}\n", "doc": "Classical Gram-Schmidt on a list of independent vectors (slide gram-schmidt).\n\nReturns Q (orthonormal vectors as rows), R (upper triangular, R[i][j] = q_i . a_j for\ni < j, R[j][j] = |w_j|), and w (the residual of each a_j after subtracting its\nprojections on q_1 .. q_{j-1}). Then a_j = sum_i R[i][j] q_i, i.e. A = Q^T R with the\na_j as the columns of A.", "marimo": true},
"00_math_toolkit.py:d02_inclusion_rank_test": {"file": "00_math_toolkit.py", "start": 743, "end": 752, "src": "def d02_inclusion_rank_test(A, B):\n    \"\"\"NULL(A) inside NULL(B) iff ROW(B) inside ROW(A) iff rank [A; B] = rank A\n    (slides null-inclusion and rank-test; Hou & Mason 2021 eq. 11-13).\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    B = np.atleast_2d(np.asarray(B, dtype=float))\n    rA = int(np.linalg.matrix_rank(A))\n    rAB = int(np.linalg.matrix_rank(np.vstack([A, B])))\n    N = d02_nullspace(A)\n    return {\"rank_A\": rA, \"rank_AB\": rAB, \"included\": rAB == rA,\n            \"B_null\": (B @ N.T).tolist()}\n", "doc": "NULL(A) inside NULL(B) iff ROW(B) inside ROW(A) iff rank [A; B] = rank A\n(slides null-inclusion and rank-test; Hou & Mason 2021 eq. 11-13).", "marimo": true},
"00_math_toolkit.py:d02_line_fit_normal_equations": {"file": "00_math_toolkit.py", "start": 1277, "end": 1287, "src": "def d02_line_fit_normal_equations(t, y):\n    \"\"\"Least-squares line y = c + d t through the points (t_i, y_i) (slide line-fit), by the\n    normal equations A^T A x = A^T y with A = [1, t].\"\"\"\n    t = np.asarray(t, dtype=float)\n    y = np.asarray(y, dtype=float)\n    A = np.column_stack([np.ones_like(t), t])\n    AtA, Aty = A.T @ A, A.T @ y\n    x = np.linalg.solve(AtA, Aty)\n    e = y - A @ x\n    return {\"AtA\": AtA.tolist(), \"Aty\": Aty.tolist(), \"c\": float(x[0]), \"d\": float(x[1]),\n            \"residuals\": e.tolist(), \"sse\": float(e @ e), \"Ate\": (A.T @ e).tolist()}\n", "doc": "Least-squares line y = c + d t through the points (t_i, y_i) (slide line-fit), by the\nnormal equations A^T A x = A^T y with A = [1, t].", "marimo": true},
"00_math_toolkit.py:d02_min_norm_solution": {"file": "00_math_toolkit.py", "start": 1301, "end": 1308, "src": "def d02_min_norm_solution(A, b):\n    \"\"\"Minimum-norm solution x+ = A^T (A A^T)^-1 b of a wide system with independent rows\n    (slide min-norm), checked against the pseudoinverse.\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    b = np.asarray(b, dtype=float)\n    x = A.T @ np.linalg.solve(A @ A.T, b)\n    return {\"x\": x.tolist(), \"norm\": float(np.linalg.norm(x)),\n            \"pinv_x\": (np.linalg.pinv(A) @ b).tolist(), \"null\": d02_nullspace(A).tolist()}\n", "doc": "Minimum-norm solution x+ = A^T (A A^T)^-1 b of a wide system with independent rows\n(slide min-norm), checked against the pseudoinverse.", "marimo": true},
"00_math_toolkit.py:d02_nearly_parallel_example": {"file": "00_math_toolkit.py", "start": 1080, "end": 1091, "src": "def d02_nearly_parallel_example():\n    \"\"\"x + y = 2, x + 1.01 y = 2.01 and the same with 2.02 (slide nearly-parallel-rows).\"\"\"\n    A = np.array([[1.0, 1.0], [1.0, 1.01]])\n    b1, b2 = np.array([2.0, 2.01]), np.array([2.0, 2.02])\n    z1, z2 = np.linalg.solve(A, b1), np.linalg.solve(A, b2)\n    rel_db = np.linalg.norm(b2 - b1) / np.linalg.norm(b1)\n    rel_dz = np.linalg.norm(z2 - z1) / np.linalg.norm(z1)\n    cosang = A[0] @ A[1] / (np.linalg.norm(A[0]) * np.linalg.norm(A[1]))\n    return {\"z1\": z1.tolist(), \"z2\": z2.tolist(), \"cond\": d02_cond(A),\n            \"S\": np.linalg.svd(A, compute_uv=False).tolist(),\n            \"rel_db\": float(rel_db), \"rel_dz\": float(rel_dz), \"amplification\": float(rel_dz / rel_db),\n            \"angle_deg\": float(np.degrees(np.arccos(min(1.0, cosang))))}\n", "doc": "x + y = 2, x + 1.01 y = 2.01 and the same with 2.02 (slide nearly-parallel-rows).", "marimo": true},
"00_math_toolkit.py:d02_nearly_parallel_rows": {"file": "00_math_toolkit.py", "start": 1093, "end": 1106, "src": "def d02_nearly_parallel_rows(phi_deg, db):\n    \"\"\"Two unit rows phi_deg apart, the first at 45 degrees, with right-hand side chosen so\n    that z* = (1, 1) solves the system; then b_2 is changed by db (slide nearly-parallel-rows,\n    live figure). cond = cot(phi / 2).\"\"\"\n    a1, a2 = np.radians(45.0), np.radians(45.0 + phi_deg)\n    A = np.array([[np.cos(a1), np.sin(a1)], [np.cos(a2), np.sin(a2)]])\n    zs = np.array([1.0, 1.0])\n    b = A @ zs + np.array([0.0, db])\n    det = A[0, 0] * A[1, 1] - A[0, 1] * A[1, 0]\n    if abs(det) < 1e-12:\n        return {\"A\": A.tolist(), \"b\": b.tolist(), \"cond\": float(\"inf\"), \"z\": None, \"shift\": None}\n    z = np.linalg.solve(A, b)\n    return {\"A\": A.tolist(), \"b\": b.tolist(), \"cond\": d02_cond(A), \"z\": z.tolist(),\n            \"shift\": float(np.linalg.norm(z - zs))}\n", "doc": "Two unit rows phi_deg apart, the first at 45 degrees, with right-hand side chosen so\nthat z* = (1, 1) solves the system; then b_2 is changed by db (slide nearly-parallel-rows,\nlive figure). cond = cot(phi / 2).", "marimo": true},
"00_math_toolkit.py:d02_nullspace": {"file": "00_math_toolkit.py", "start": 647, "end": 653, "src": "def d02_nullspace(A):\n    \"\"\"Orthonormal basis of NULL(A) as rows (Hou & Mason's Null(A)), signs fixed.\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    _u, s, vt = np.linalg.svd(A)\n    tol = max(A.shape) * np.finfo(float).eps * (s[0] if s.size else 0.0)\n    r = int(np.sum(s > tol))\n    return np.array([_d02_sign(v) for v in vt[r:]]).reshape(A.shape[1] - r, A.shape[1])\n", "doc": "Orthonormal basis of NULL(A) as rows (Hou & Mason's Null(A)), signs fixed.", "marimo": true},
"00_math_toolkit.py:d02_orthonormal_coordinates": {"file": "00_math_toolkit.py", "start": 679, "end": 685, "src": "def d02_orthonormal_coordinates(x, Q):\n    \"\"\"Coordinates c_i = q_i . x of x in the orthonormal basis given by the rows of Q\n    (slide orthonormal-basis), and the reconstruction sum_i c_i q_i.\"\"\"\n    Q = np.atleast_2d(np.asarray(Q, dtype=float))\n    x = np.asarray(x, dtype=float)\n    c = Q @ x\n    return {\"c\": c.tolist(), \"recon\": (Q.T @ c).tolist(), \"QQt\": (Q @ Q.T).tolist()}\n", "doc": "Coordinates c_i = q_i . x of x in the orthonormal basis given by the rows of Q\n(slide orthonormal-basis), and the reconstruction sum_i c_i q_i.", "marimo": true},
"00_math_toolkit.py:d02_projection_onto_line": {"file": "00_math_toolkit.py", "start": 660, "end": 677, "src": "def d02_projection_onto_line(a, b):\n    \"\"\"Projection of b onto the line through 0 and a (slides projection-line, -derivation).\n\n    xhat = a.b / a.a, p = xhat a, e = b - p (perpendicular to a), P = a a^T / a^T a.\n    \"\"\"\n    a = np.asarray(a, dtype=float)\n    b = np.asarray(b, dtype=float)\n    xhat = float(a @ b / (a @ a))\n    p = xhat * a\n    e = b - p\n    return {\n        \"xhat\": xhat,\n        \"p\": p.tolist(),\n        \"e\": e.tolist(),\n        \"e_dot_a\": float(e @ a),\n        \"dist\": float(np.linalg.norm(e)),\n        \"P\": (np.outer(a, a) / (a @ a)).tolist(),\n    }\n", "doc": "Projection of b onto the line through 0 and a (slides projection-line, -derivation).\n\nxhat = a.b / a.a, p = xhat a, e = b - p (perpendicular to a), P = a a^T / a^T a.", "marimo": true},
"00_math_toolkit.py:d02_projection_onto_plane": {"file": "00_math_toolkit.py", "start": 687, "end": 695, "src": "def d02_projection_onto_plane(b, Q):\n    \"\"\"Projection of b onto the span of the orthonormal rows of Q (slide projection-subspace):\n    coordinates Q b, point p = Q^T Q b, error e = b - p, projector P = Q^T Q.\"\"\"\n    Q = np.atleast_2d(np.asarray(Q, dtype=float))\n    b = np.asarray(b, dtype=float)\n    c = Q @ b\n    p = Q.T @ c\n    return {\"coords\": c.tolist(), \"p\": p.tolist(), \"e\": (b - p).tolist(),\n            \"dist\": float(np.linalg.norm(b - p)), \"P\": (Q.T @ Q).tolist()}\n", "doc": "Projection of b onto the span of the orthonormal rows of Q (slide projection-subspace):\ncoordinates Q b, point p = Q^T Q b, error e = b - p, projector P = Q^T Q.", "marimo": true},
"00_math_toolkit.py:d02_pseudoinverse_rank_one": {"file": "00_math_toolkit.py", "start": 1331, "end": 1340, "src": "def d02_pseudoinverse_rank_one(A=((1, 2), (2, 4)), b=(1, 1), mus=(1.0, 0.1, 0.01, 0.001)):\n    \"\"\"Pseudoinverse of a rank-one matrix from its SVD, and Tikhonov-regularized solutions\n    (A^T A + mu I)^-1 A^T b approaching A+ b (slide pseudoinverse).\"\"\"\n    A = np.asarray(A, dtype=float)\n    b = np.asarray(b, dtype=float)\n    P = np.linalg.pinv(A)\n    x = P @ b\n    tik = [np.linalg.solve(A.T @ A + mu * np.eye(A.shape[1]), A.T @ b).tolist() for mu in mus]\n    return {\"S\": np.linalg.svd(A, compute_uv=False).tolist(), \"pinv\": P.tolist(), \"x\": x.tolist(),\n            \"Ax\": (A @ x).tolist(), \"tikhonov\": tik, \"mus\": list(mus)}\n", "doc": "Pseudoinverse of a rank-one matrix from its SVD, and Tikhonov-regularized solutions\n(A^T A + mu I)^-1 A^T b approaching A+ b (slide pseudoinverse).", "marimo": true},
"00_math_toolkit.py:d02_quadratic_form_axes": {"file": "00_math_toolkit.py", "start": 876, "end": 898, "src": "def d02_quadratic_form_axes(A, c=1.0):\n    \"\"\"Shape of J(z) = 1/2 z^T A z for symmetric 2x2 A (slides quadratic-forms, -derivation).\n\n    In eigenvector coordinates y = V^T z, J = 1/2 (l1 y1^2 + l2 y2^2); the level set J = c\n    has semi-axis sqrt(2c / l_i) along v_i for every positive l_i.\n    \"\"\"\n    A = np.asarray(A, dtype=float)\n    e = d02_eigen_2x2(A)\n    l1, l2 = e[\"values\"]\n    tol = 1e-9 * max(1.0, abs(l1), abs(l2))\n    if l2 > tol:\n        kind = \"bowl\"\n    elif l1 < -tol:\n        kind = \"cap\"\n    elif l1 > tol and l2 < -tol:\n        kind = \"saddle\"\n    elif abs(l1) <= tol and abs(l2) <= tol:\n        kind = \"flat\"\n    else:\n        kind = \"valley\" if l1 > tol else \"ridge\"\n    axes = [float(np.sqrt(2 * c / l)) if l > tol else None for l in (l1, l2)]\n    return {\"values\": [l1, l2], \"vectors\": e[\"vectors\"], \"kind\": kind, \"semi_axes\": axes,\n            \"kappa\": float(l1 / l2) if l2 > tol else None}\n", "doc": "Shape of J(z) = 1/2 z^T A z for symmetric 2x2 A (slides quadratic-forms, -derivation).\n\nIn eigenvector coordinates y = V^T z, J = 1/2 (l1 y1^2 + l2 y2^2); the level set J = c\nhas semi-axis sqrt(2c / l_i) along v_i for every positive l_i.", "marimo": true},
"00_math_toolkit.py:d02_quadratic_from_eigen": {"file": "00_math_toolkit.py", "start": 869, "end": 874, "src": "def d02_quadratic_from_eigen(l1, l2, theta_deg):\n    \"\"\"The symmetric A = V diag(l1, l2) V^T whose first eigenvector is at theta_deg\n    (the sliders of slide quadratic-forms).\"\"\"\n    t = np.radians(theta_deg)\n    V = np.array([[np.cos(t), -np.sin(t)], [np.sin(t), np.cos(t)]])\n    return (V @ np.diag([l1, l2]) @ V.T).tolist()\n", "doc": "The symmetric A = V diag(l1, l2) V^T whose first eigenvector is at theta_deg\n(the sliders of slide quadratic-forms).", "marimo": true},
"00_math_toolkit.py:d02_rowspace": {"file": "00_math_toolkit.py", "start": 639, "end": 645, "src": "def d02_rowspace(A):\n    \"\"\"Orthonormal basis of ROW(A) as rows (Hou & Mason's Row(A)), signs fixed.\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    _u, s, vt = np.linalg.svd(A)\n    tol = max(A.shape) * np.finfo(float).eps * (s[0] if s.size else 0.0)\n    r = int(np.sum(s > tol))\n    return np.array([_d02_sign(v) for v in vt[:r]]).reshape(r, A.shape[1])\n", "doc": "Orthonormal basis of ROW(A) as rows (Hou & Mason's Row(A)), signs fixed.", "marimo": true},
"00_math_toolkit.py:d02_schur_block_solve": {"file": "00_math_toolkit.py", "start": 1353, "end": 1364, "src": "def d02_schur_block_solve(K, rhs, n1):\n    \"\"\"Solve K [x; u] = rhs by block elimination (slide schur-complement), where x holds the\n    first n1 unknowns: S = A - B C^-1 B^T, S x = f - B C^-1 g, u = C^-1 (g - B^T x).\"\"\"\n    K = np.asarray(K, dtype=float)\n    rhs = np.asarray(rhs, dtype=float)\n    A, B, C = K[:n1, :n1], K[:n1, n1:], K[n1:, n1:]\n    f, g = rhs[:n1], rhs[n1:]\n    S = A - B @ np.linalg.solve(C, B.T)\n    x = np.linalg.solve(S, f - B @ np.linalg.solve(C, g))\n    u = np.linalg.solve(C, g - B.T @ x)\n    return {\"S\": S.tolist(), \"x\": x.tolist(), \"u\": u.tolist(),\n            \"check\": (K @ np.concatenate([x, u]) - rhs).tolist()}\n", "doc": "Solve K [x; u] = rhs by block elimination (slide schur-complement), where x holds the\nfirst n1 unknowns: S = A - B C^-1 B^T, S x = f - B C^-1 g, u = C^-1 (g - B^T x).", "marimo": true},
"00_math_toolkit.py:d02_schur_minimize_out": {"file": "00_math_toolkit.py", "start": 1366, "end": 1379, "src": "def d02_schur_minimize_out(a, b, c):\n    \"\"\"Minimize f(x, u) = 1/2 (a x^2 + 2 b x u + c u^2) over u (slide schur-minimization).\n\n    With c > 0 the minimizer is u*(x) = -(b / c) x and f(x, u*) = 1/2 s x^2 with the Schur\n    complement s = a - b^2 / c. The matrix [[a, b], [b, c]] is positive definite exactly when\n    c > 0 and s > 0.\n    \"\"\"\n    K = np.array([[a, b], [b, c]], dtype=float)\n    eig = np.linalg.eigvalsh(K)\n    if c <= 0:\n        return {\"s\": None, \"gain\": None, \"eigs\": sorted(eig.tolist(), reverse=True), \"pd\": False, \"c_pos\": False}\n    s = a - b * b / c\n    return {\"s\": float(s), \"gain\": float(-b / c), \"eigs\": sorted(eig.tolist(), reverse=True),\n            \"pd\": bool(s > 0), \"c_pos\": True}\n", "doc": "Minimize f(x, u) = 1/2 (a x^2 + 2 b x u + c u^2) over u (slide schur-minimization).\n\nWith c > 0 the minimizer is u*(x) = -(b / c) x and f(x, u*) = 1/2 s x^2 with the Schur\ncomplement s = a - b^2 / c. The matrix [[a, b], [b, c]] is positive definite exactly when\nc > 0 and s > 0.", "marimo": true},
"00_math_toolkit.py:d02_svd_circle_ellipse": {"file": "00_math_toolkit.py", "start": 1032, "end": 1058, "src": "def d02_svd_circle_ellipse(A):\n    \"\"\"SVD of a 2x2 matrix for slide svd-picture.\n\n    sigma_1 = sqrt(largest eigenvalue of A^T A), sigma_2 = |det A| / sigma_1 (exact zero for\n    a singular A). v_i: unit eigenvectors of A^T A (largest entry positive). u_1 = A v_1 /\n    sigma_1 and u_2 = s * (u_1 turned 90 degrees) with s = sign(det A * det V), so that\n    A = U diag(sigma) V^T also when sigma_2 = 0. cond = sigma_1 / sigma_2 (inf when singular).\n    \"\"\"\n    A = np.asarray(A, dtype=float)\n    w, V = np.linalg.eigh(A.T @ A)\n    V = V[:, ::-1]\n    vs = []\n    for i in range(2):\n        v = V[:, i]\n        k = 0 if abs(v[0]) >= abs(v[1]) - 1e-12 else 1\n        vs.append(v if v[k] > 0 else -v)\n    det = A[0, 0] * A[1, 1] - A[0, 1] * A[1, 0]\n    s1 = float(np.sqrt(max(w[1], 0.0)))\n    s2 = abs(det) / s1 if s1 > 0 else 0.0\n    u1 = A @ vs[0] / s1 if s1 > 0 else np.array([1.0, 0.0])\n    detV = vs[0][0] * vs[1][1] - vs[0][1] * vs[1][0]\n    sgn = -1.0 if det * detV < 0 else 1.0\n    u2 = sgn * np.array([-u1[1], u1[0]])\n    cond = s1 / s2 if s2 > 0 else float(\"inf\")\n    return {\"S\": [s1, float(s2)], \"U\": np.column_stack([u1, u2]).tolist(),\n            \"V\": np.column_stack(vs).tolist(), \"cond\": float(cond), \"det\": float(det),\n            \"AtA_eigs\": [float(w[1]), float(w[0])]}\n", "doc": "SVD of a 2x2 matrix for slide svd-picture.\n\nsigma_1 = sqrt(largest eigenvalue of A^T A), sigma_2 = |det A| / sigma_1 (exact zero for\na singular A). v_i: unit eigenvectors of A^T A (largest entry positive). u_1 = A v_1 /\nsigma_1 and u_2 = s * (u_1 turned 90 degrees) with s = sign(det A * det V), so that\nA = U diag(sigma) V^T also when sigma_2 = 0. cond = sigma_1 / sigma_2 (inf when singular).", "marimo": true},
"00_math_toolkit.py:d02_svd_subspaces": {"file": "00_math_toolkit.py", "start": 1060, "end": 1073, "src": "def d02_svd_subspaces(A):\n    \"\"\"Singular values, rank, and orthonormal row-space and null-space bases (rows) from the\n    SVD (slide svd-statement).\"\"\"\n    A = np.atleast_2d(np.asarray(A, dtype=float))\n    _u, s, vt = np.linalg.svd(A)\n    tol = max(A.shape) * np.finfo(float).eps * s[0]\n    r = int(np.sum(s > tol))\n\n    def fix(v):\n        k = int(np.argmax(np.abs(v) > np.abs(v).max() - 1e-12))\n        return v if v[k] > 0 else -v\n\n    return {\"S\": s.tolist(), \"rank\": r, \"row\": [fix(v).tolist() for v in vt[:r]],\n            \"null\": [fix(v).tolist() for v in vt[r:]], \"AAt_eigs\": sorted(np.linalg.eigvalsh(A @ A.T).tolist(), reverse=True)}\n", "doc": "Singular values, rank, and orthonormal row-space and null-space bases (rows) from the\nSVD (slide svd-statement).", "marimo": true},
"00_math_toolkit.py:d02_table_delassus": {"file": "00_math_toolkit.py", "start": 916, "end": 932, "src": "def d02_table_delassus(legs=((1, 1), (-1, 1), (-1, -1), (1, -1)), masses=(1.0, 1.0, 1.0)):\n    \"\"\"Gram matrices of a four-legged table (slide gram-psd).\n\n    The table top moves with v = (v_z, omega_x, omega_y); leg i at (x_i, y_i) has normal\n    velocity v_z + omega_x y_i - omega_y x_i, so row i of the contact Jacobian is\n    [1, y_i, -x_i]. M = diag(masses). G = J M^-1 J^T is the Delassus matrix.\n    \"\"\"\n    legs = np.asarray(legs, dtype=float)\n    J = np.column_stack([np.ones(len(legs)), legs[:, 1], -legs[:, 0]])\n    Minv = np.diag(1.0 / np.asarray(masses, dtype=float))\n    G = J @ Minv @ J.T\n    w, V = np.linalg.eigh(G)\n    n = V[:, 0] / np.abs(V[:, 0]).max()\n    n = n if n[np.argmax(np.abs(n) > 1 - 1e-9)] > 0 else -n\n    return {\"J\": J.tolist(), \"JtJ\": (J.T @ J).tolist(), \"G_eigs\": sorted(w.tolist(), reverse=True),\n            \"rank_G\": int(np.linalg.matrix_rank(G)), \"null\": n.tolist(),\n            \"G_null\": (G @ n).tolist()}\n", "doc": "Gram matrices of a four-legged table (slide gram-psd).\n\nThe table top moves with v = (v_z, omega_x, omega_y); leg i at (x_i, y_i) has normal\nvelocity v_z + omega_x y_i - omega_y x_i, so row i of the contact Jacobian is\n[1, y_i, -x_i]. M = diag(masses). G = J M^-1 J^T is the Delassus matrix.", "marimo": true},
"00_math_toolkit.py:d02_table_force_distribution": {"file": "00_math_toolkit.py", "start": 1310, "end": 1329, "src": "def d02_table_force_distribution(W=100.0, com=(0.2, 0.1), legs=((1, 1), (-1, 1), (-1, -1), (1, -1)), t=0.0):\n    \"\"\"Leg forces of a table on four legs (slide table-forces).\n\n    Equilibrium M f = rhs: sum f_i = W, sum f_i x_i = W x_c, sum f_i y_i = W y_c. Three\n    equations, four unknowns. f+ = M^T (M M^T)^-1 rhs is the minimum-norm distribution\n    (Hou & Mason 2019 eq. 21); every other one is f+ + t n with n the null vector scaled so\n    its largest entry is 1. t_range is the interval of t with every f_i >= 0.\n    \"\"\"\n    legs = np.asarray(legs, dtype=float)\n    M = np.vstack([np.ones(len(legs)), legs[:, 0], legs[:, 1]])\n    rhs = W * np.array([1.0, com[0], com[1]])\n    fp = M.T @ np.linalg.solve(M @ M.T, rhs)\n    n = d02_nullspace(M)[0]\n    n = n / np.abs(n).max()\n    f = fp + t * n\n    lo = max([-fp[i] / n[i] for i in range(len(n)) if n[i] > 1e-12] + [-np.inf])\n    hi = min([-fp[i] / n[i] for i in range(len(n)) if n[i] < -1e-12] + [np.inf])\n    return {\"MMt\": (M @ M.T).tolist(), \"f_plus\": fp.tolist(), \"norm_plus\": float(np.linalg.norm(fp)),\n            \"null\": n.tolist(), \"f\": f.tolist(), \"norm\": float(np.linalg.norm(f)),\n            \"residual\": (M @ f - rhs).tolist(), \"t_range\": [float(lo), float(hi)]}\n", "doc": "Leg forces of a table on four legs (slide table-forces).\n\nEquilibrium M f = rhs: sum f_i = W, sum f_i x_i = W x_c, sum f_i y_i = W y_c. Three\nequations, four unknowns. f+ = M^T (M M^T)^-1 rhs is the minimum-norm distribution\n(Hou & Mason 2019 eq. 21); every other one is f+ + t n with n the null vector scaled so\nits largest entry is 1. t_range is the interval of t with every f_i >= 0.", "marimo": true},
"00_math_toolkit.py:d03_arm_distance_gradient": {"file": "00_math_toolkit.py", "start": 1925, "end": 1933, "src": "def d03_arm_distance_gradient(theta, target, l=(1.0, 1.0)):\n    \"\"\"w(theta) = (1/2) |p(theta) - p*|^2 has gradient J^T (p - p*) by the chain rule, a product\n    of the 1 x 2 Jacobian (p - p*)^T and the 2 x 2 arm Jacobian (slide chain-rule-jacobians).\"\"\"\n    tg = np.asarray(target, dtype=float)\n    e = np.array(d03_arm_fk(theta, l)) - tg\n    J = np.array(d03_arm_jacobian(theta, l)[\"J\"])\n    w = lambda th: 0.5 * float(np.sum((np.array(d03_arm_fk(th, l)) - tg) ** 2))\n    return {\"p\": (e + tg).tolist(), \"e\": e.tolist(), \"w\": float(0.5 * e @ e), \"grad\": (J.T @ e).tolist(),\n            \"fd\": d03_fd_gradient(w, theta).tolist()}\n", "doc": "w(theta) = (1/2) |p(theta) - p*|^2 has gradient J^T (p - p*) by the chain rule, a product\nof the 1 x 2 Jacobian (p - p*)^T and the 2 x 2 arm Jacobian (slide chain-rule-jacobians).", "marimo": true},
"00_math_toolkit.py:d03_arm_first_order": {"file": "00_math_toolkit.py", "start": 1918, "end": 1923, "src": "def d03_arm_first_order(theta, dtheta, l=(1.0, 1.0)):\n    \"\"\"True tip displacement p(theta + dtheta) - p(theta) next to the prediction J dtheta.\"\"\"\n    p0 = np.array(d03_arm_fk(theta, l))\n    p1 = np.array(d03_arm_fk(np.add(theta, dtheta), l))\n    J = np.array(d03_arm_jacobian(theta, l)[\"J\"])\n    return {\"true\": (p1 - p0).tolist(), \"lin\": (J @ np.asarray(dtheta, dtype=float)).tolist()}\n", "doc": "True tip displacement p(theta + dtheta) - p(theta) next to the prediction J dtheta.", "marimo": true},
"00_math_toolkit.py:d03_arm_fk": {"file": "00_math_toolkit.py", "start": 1904, "end": 1907, "src": "def d03_arm_fk(theta, l=(1.0, 1.0)):\n    \"\"\"Fingertip of a planar two-link arm, joint angles theta (rad), link lengths l (m).\"\"\"\n    t1, t2 = float(theta[0]), float(theta[1])\n    return [l[0] * np.cos(t1) + l[1] * np.cos(t1 + t2), l[0] * np.sin(t1) + l[1] * np.sin(t1 + t2)]\n", "doc": "Fingertip of a planar two-link arm, joint angles theta (rad), link lengths l (m).", "marimo": true},
"00_math_toolkit.py:d03_arm_jacobian": {"file": "00_math_toolkit.py", "start": 1909, "end": 1916, "src": "def d03_arm_jacobian(theta, l=(1.0, 1.0)):\n    \"\"\"2 x 2 Jacobian dp/dtheta of the two-link arm and its determinant l1 l2 sin(theta2)\n    (slides jacobian-matrix, arm-jacobian).\"\"\"\n    t1, t2 = float(theta[0]), float(theta[1])\n    s1, c1 = np.sin(t1), np.cos(t1)\n    s12, c12 = np.sin(t1 + t2), np.cos(t1 + t2)\n    J = [[-l[0] * s1 - l[1] * s12, -l[1] * s12], [l[0] * c1 + l[1] * c12, l[1] * c12]]\n    return {\"J\": J, \"det\": float(J[0][0] * J[1][1] - J[0][1] * J[1][0])}\n", "doc": "2 x 2 Jacobian dp/dtheta of the two-link arm and its determinant l1 l2 sin(theta2)\n(slides jacobian-matrix, arm-jacobian).", "marimo": true},
"00_math_toolkit.py:d03_bead_constraint": {"file": "00_math_toolkit.py", "start": 1974, "end": 1979, "src": "def d03_bead_constraint(q, qdot):\n    \"\"\"Bead on the unit circle: Phi = x^2 + y^2 - 1, J_Phi = [2x, 2y], and J_Phi qdot\n    (slide constraint-time-derivative).\"\"\"\n    x, y = float(q[0]), float(q[1])\n    J = [2 * x, 2 * y]\n    return {\"Phi\": x * x + y * y - 1.0, \"J\": J, \"Jqdot\": J[0] * float(qdot[0]) + J[1] * float(qdot[1])}\n", "doc": "Bead on the unit circle: Phi = x^2 + y^2 - 1, J_Phi = [2x, 2y], and J_Phi qdot\n(slide constraint-time-derivative).", "marimo": true},
"00_math_toolkit.py:d03_directional_derivative": {"file": "00_math_toolkit.py", "start": 1684, "end": 1695, "src": "def d03_directional_derivative(z, phi_deg):\n    \"\"\"grad J . d for the unit vector d = (cos phi, sin phi), next to the difference quotient\n    (J(z + t d) - J(z - t d)) / (2 t), t = 1e-6 (slide directional-derivative).\"\"\"\n    phi = np.radians(phi_deg)\n    d = np.array([np.cos(phi), np.sin(phi)])\n    g = np.array(d03_valley_grad(z))\n    t = 1e-6\n    z = np.asarray(z, dtype=float)\n    fd = (d03_valley(z + t * d) - d03_valley(z - t * d)) / (2 * t)\n    ng = float(np.linalg.norm(g))\n    return {\"d\": d.tolist(), \"D\": float(g @ d), \"fd\": float(fd), \"norm_grad\": ng,\n            \"cos\": float(g @ d / ng) if ng > 0 else None}\n", "doc": "grad J . d for the unit vector d = (cos phi, sin phi), next to the difference quotient\n(J(z + t d) - J(z - t d)) / (2 t), t = 1e-6 (slide directional-derivative).", "marimo": true},
"00_math_toolkit.py:d03_fd_central": {"file": "00_math_toolkit.py", "start": 2104, "end": 2106, "src": "def d03_fd_central(z0, h):\n    \"\"\"Central difference (J(z0 + h) - J(z0 - h)) / (2 h) of the quartic.\"\"\"\n    return (d03_quartic(z0 + h) - d03_quartic(z0 - h)) / (2.0 * h)\n", "doc": "Central difference (J(z0 + h) - J(z0 - h)) / (2 h) of the quartic.", "marimo": true},
"00_math_toolkit.py:d03_fd_error_curve": {"file": "00_math_toolkit.py", "start": 2119, "end": 2125, "src": "def d03_fd_error_curve(z0=1.0, hs=None):\n    \"\"\"|FD - J'(z0)| for forward and central differences over the step sizes (slide\n    finite-difference-error-curve): truncation error falls with h, roundoff grows like 1/h.\"\"\"\n    hs = d03_fd_steps() if hs is None else list(hs)\n    d = d03_quartic_derivs(z0)[1]\n    return {\"h\": hs, \"forward\": [abs(d03_fd_forward(z0, h) - d) for h in hs],\n            \"central\": [abs(d03_fd_central(z0, h) - d) for h in hs]}\n", "doc": "|FD - J'(z0)| for forward and central differences over the step sizes (slide\nfinite-difference-error-curve): truncation error falls with h, roundoff grows like 1/h.", "marimo": true},
"00_math_toolkit.py:d03_fd_forward": {"file": "00_math_toolkit.py", "start": 2100, "end": 2102, "src": "def d03_fd_forward(z0, h):\n    \"\"\"Forward difference (J(z0 + h) - J(z0)) / h of the quartic.\"\"\"\n    return (d03_quartic(z0 + h) - d03_quartic(z0)) / h\n", "doc": "Forward difference (J(z0 + h) - J(z0)) / h of the quartic.", "marimo": true},
"00_math_toolkit.py:d03_fd_gradient": {"file": "00_math_toolkit.py", "start": 1750, "end": 1758, "src": "def d03_fd_gradient(f, x, h=1e-6):\n    \"\"\"Central-difference gradient of a scalar function f at x, one coordinate at a time.\"\"\"\n    x = np.asarray(x, dtype=float)\n    g = np.zeros_like(x)\n    for k in range(len(x)):\n        e = np.zeros_like(x)\n        e[k] = h\n        g[k] = (f(x + e) - f(x - e)) / (2 * h)\n    return g\n", "doc": "Central-difference gradient of a scalar function f at x, one coordinate at a time.", "marimo": true},
"00_math_toolkit.py:d03_fd_jacobian": {"file": "00_math_toolkit.py", "start": 2127, "end": 2140, "src": "def d03_fd_jacobian(f, x, h=1e-6, central=False):\n    \"\"\"Finite-difference Jacobian of a vector function f at x; column j perturbs x_j.\n    Forward differences cost n + 1 evaluations of f, central differences 2 n.\"\"\"\n    x = np.asarray(x, dtype=float)\n    f0 = np.asarray(f(x), dtype=float)\n    cols = []\n    for j in range(len(x)):\n        e = np.zeros_like(x)\n        e[j] = h\n        if central:\n            cols.append((np.asarray(f(x + e), dtype=float) - np.asarray(f(x - e), dtype=float)) / (2 * h))\n        else:\n            cols.append((np.asarray(f(x + e), dtype=float) - f0) / h)\n    return np.array(cols).T\n", "doc": "Finite-difference Jacobian of a vector function f at x; column j perturbs x_j.\nForward differences cost n + 1 evaluations of f, central differences 2 n.", "marimo": true},
"00_math_toolkit.py:d03_fd_pendulum_AB": {"file": "00_math_toolkit.py", "start": 2142, "end": 2150, "src": "def d03_fd_pendulum_AB(xbar, ubar=0.0, h=0.01, eps=1e-6):\n    \"\"\"A and B of the pendulum step by forward differences with step eps (3 perturbed steps plus\n    the nominal one), next to the analytic Jacobians (slide finite-difference-jacobians).\"\"\"\n    xu = np.r_[np.asarray(xbar, dtype=float), float(ubar)]\n    JF = d03_fd_jacobian(lambda v: d03_pendulum_step(v[:2], v[2], h), xu, eps)\n    an = d03_pendulum_AB(xbar, ubar, h)\n    exact = np.hstack([np.array(an[\"A\"]), np.array(an[\"B\"])])\n    return {\"A_fd\": JF[:, :2].tolist(), \"B_fd\": JF[:, 2:].tolist(), \"A\": an[\"A\"], \"B\": an[\"B\"],\n            \"max_err\": float(np.max(np.abs(JF - exact)))}\n", "doc": "A and B of the pendulum step by forward differences with step eps (3 perturbed steps plus\nthe nominal one), next to the analytic Jacobians (slide finite-difference-jacobians).", "marimo": true},
"00_math_toolkit.py:d03_fd_steps": {"file": "00_math_toolkit.py", "start": 2108, "end": 2117, "src": "def d03_fd_steps():\n    \"\"\"Step sizes m x 10^-e, m in 7, 5, 3, 2, 1.5, 1 and e = 0..15 (1 down to 1e-15), parsed from\n    decimal strings so that Python and JavaScript use the same doubles.\"\"\"\n    hs = []\n    for e in range(0, 16):\n        for m in (\"7\", \"5\", \"3\", \"2\", \"1.5\", \"1\"):\n            h = float(m + \"e-\" + str(e))\n            if h <= 1.0:\n                hs.append(h)\n    return hs\n", "doc": "Step sizes m x 10^-e, m in 7, 5, 3, 2, 1.5, 1 and e = 0..15 (1 down to 1e-15), parsed from\ndecimal strings so that Python and JavaScript use the same doubles.", "marimo": true},
"00_math_toolkit.py:d03_grad_least_squares": {"file": "00_math_toolkit.py", "start": 1774, "end": 1783, "src": "def d03_grad_least_squares(A, b, x):\n    \"\"\"f(x) = (1/2) |A x - b|^2: residual r = A x - b, gradient A^T r, Hessian A^T A, and the\n    minimizer from the normal equations A^T A x = A^T b (slide gradient-least-squares).\"\"\"\n    A = np.asarray(A, dtype=float)\n    b = np.asarray(b, dtype=float)\n    x = np.asarray(x, dtype=float)\n    r = A @ x - b\n    return {\"f\": float(0.5 * r @ r), \"r\": r.tolist(), \"grad\": (A.T @ r).tolist(), \"hess\": (A.T @ A).tolist(),\n            \"AtB\": (A.T @ b).tolist(), \"xstar\": np.linalg.solve(A.T @ A, A.T @ b).tolist(),\n            \"fd\": d03_fd_gradient(lambda y: 0.5 * (A @ y - b) @ (A @ y - b), x).tolist()}\n", "doc": "f(x) = (1/2) |A x - b|^2: residual r = A x - b, gradient A^T r, Hessian A^T A, and the\nminimizer from the normal equations A^T A x = A^T b (slide gradient-least-squares).", "marimo": true},
"00_math_toolkit.py:d03_grad_linear": {"file": "00_math_toolkit.py", "start": 1760, "end": 1764, "src": "def d03_grad_linear(b, x):\n    \"\"\"f(x) = b^T x has gradient b; central differences check it (slide gradient-linear-quadratic-forms).\"\"\"\n    b = np.asarray(b, dtype=float)\n    return {\"f\": float(b @ np.asarray(x, dtype=float)), \"grad\": b.tolist(),\n            \"fd\": d03_fd_gradient(lambda y: b @ y, x).tolist()}\n", "doc": "f(x) = b^T x has gradient b; central differences check it (slide gradient-linear-quadratic-forms).", "marimo": true},
"00_math_toolkit.py:d03_grad_quadratic": {"file": "00_math_toolkit.py", "start": 1766, "end": 1772, "src": "def d03_grad_quadratic(A, x):\n    \"\"\"f(x) = x^T A x has gradient (A + A^T) x (2 A x for symmetric A) and Hessian A + A^T\n    (slide gradient-linear-quadratic-forms).\"\"\"\n    A = np.asarray(A, dtype=float)\n    x = np.asarray(x, dtype=float)\n    return {\"f\": float(x @ A @ x), \"grad\": ((A + A.T) @ x).tolist(), \"hess\": (A + A.T).tolist(),\n            \"fd\": d03_fd_gradient(lambda y: y @ A @ y, x).tolist()}\n", "doc": "f(x) = x^T A x has gradient (A + A^T) x (2 A x for symmetric A) and Hessian A + A^T\n(slide gradient-linear-quadratic-forms).", "marimo": true},
"00_math_toolkit.py:d03_hessian_eigen": {"file": "00_math_toolkit.py", "start": 1728, "end": 1738, "src": "def d03_hessian_eigen(z):\n    \"\"\"Eigenvalues (descending) and unit eigenvectors (largest entry positive) of the valley Hessian:\n    the largest and smallest curvature d^T H d over unit d and their directions.\"\"\"\n    w, V = np.linalg.eigh(np.array(d03_valley_hess(z)))\n    vecs = []\n    for k in (1, 0):\n        v = V[:, k]\n        if v[np.argmax(np.abs(v))] < 0:\n            v = -v\n        vecs.append(v.tolist())\n    return {\"values\": [float(w[1]), float(w[0])], \"vectors\": vecs}\n", "doc": "Eigenvalues (descending) and unit eigenvectors (largest entry positive) of the valley Hessian:\nthe largest and smallest curvature d^T H d over unit d and their directions.", "marimo": true},
"00_math_toolkit.py:d03_inflection_points": {"file": "00_math_toolkit.py", "start": 1508, "end": 1511, "src": "def d03_inflection_points():\n    \"\"\"Zeros of J''(z) = 12 z^2 - 8: z = -sqrt(2/3) and +sqrt(2/3).\"\"\"\n    r = float(np.sqrt(2.0 / 3.0))\n    return [-r, r]\n", "doc": "Zeros of J''(z) = 12 z^2 - 8: z = -sqrt(2/3) and +sqrt(2/3).", "marimo": true},
"00_math_toolkit.py:d03_level_tangent": {"file": "00_math_toolkit.py", "start": 1706, "end": 1715, "src": "def d03_level_tangent(z):\n    \"\"\"Unit tangent of the level curve through z (grad J turned by +90 deg), grad J . tangent (= 0),\n    and J at z +- 1e-3 tangent, which differs from J(z) only at second order\n    (slide gradient-perpendicular-level-set).\"\"\"\n    g = np.array(d03_valley_grad(z))\n    t = np.array([-g[1], g[0]]) / np.linalg.norm(g)\n    z = np.asarray(z, dtype=float)\n    s = 1e-3\n    return {\"tangent\": t.tolist(), \"dot\": float(g @ t), \"J\": d03_valley(z),\n            \"J_plus\": d03_valley(z + s * t), \"J_minus\": d03_valley(z - s * t)}\n", "doc": "Unit tangent of the level curve through z (grad J turned by +90 deg), grad J . tangent (= 0),\nand J at z +- 1e-3 tangent, which differs from J(z) only at second order\n(slide gradient-perpendicular-level-set).", "marimo": true},
"00_math_toolkit.py:d03_partial_slices": {"file": "00_math_toolkit.py", "start": 1675, "end": 1682, "src": "def d03_partial_slices(z):\n    \"\"\"J, the two partial derivatives, and their central-difference checks at z (slide\n    partial-derivatives). dJ/dz1 is the slope of the slice t -> J(t, z2) at t = z1.\"\"\"\n    h = 1e-6\n    z1, z2 = float(z[0]), float(z[1])\n    fd1 = (d03_valley([z1 + h, z2]) - d03_valley([z1 - h, z2])) / (2 * h)\n    fd2 = (d03_valley([z1, z2 + h]) - d03_valley([z1, z2 - h])) / (2 * h)\n    return {\"J\": d03_valley(z), \"grad\": d03_valley_grad(z), \"fd\": [fd1, fd2]}\n", "doc": "J, the two partial derivatives, and their central-difference checks at z (slide\npartial-derivatives). dJ/dz1 is the slope of the slice t -> J(t, z2) at t = z1.", "marimo": true},
"00_math_toolkit.py:d03_pendulum_AB": {"file": "00_math_toolkit.py", "start": 1945, "end": 1955, "src": "def d03_pendulum_AB(xbar, ubar=0.0, h=0.01, p=D03_PEND):\n    \"\"\"A = df/dx and B = df/du of the step at (xbar, ubar) (slide linearizing-dynamics).\n\n    With k = (g/l) cos(theta) and b = 1 / (m l^2): A = [[1 - h^2 k, h], [-h k, 1]],\n    B = [[h^2 b], [h b]], det A = 1.\n    \"\"\"\n    k = (p[\"g\"] / p[\"l\"]) * np.cos(float(xbar[0]))\n    b = 1.0 / (p[\"m\"] * p[\"l\"] * p[\"l\"])\n    A = [[1.0 - h * h * k, h], [-h * k, 1.0]]\n    B = [[h * h * b], [h * b]]\n    return {\"A\": A, \"B\": B, \"det\": float(A[0][0] * A[1][1] - A[0][1] * A[1][0])}\n", "doc": "A = df/dx and B = df/du of the step at (xbar, ubar) (slide linearizing-dynamics).\n\nWith k = (g/l) cos(theta) and b = 1 / (m l^2): A = [[1 - h^2 k, h], [-h k, 1]],\nB = [[h^2 b], [h b]], det A = 1.", "marimo": true},
"00_math_toolkit.py:d03_pendulum_rollouts": {"file": "00_math_toolkit.py", "start": 1957, "end": 1972, "src": "def d03_pendulum_rollouts(dtheta0_deg, theta_bar_deg=0.0, T=2.0, h=0.01):\n    \"\"\"Nonlinear rollout from rest at theta_bar + dtheta0 with u = 0, next to the linearized\n    prediction xbar + A^k dx0 about the equilibrium (theta_bar, 0) (slide linearization-live).\n    theta in degrees at every step, and the largest gap between the two.\"\"\"\n    tb = np.radians(theta_bar_deg)\n    A = np.array(d03_pendulum_AB([tb, 0.0], 0.0, h)[\"A\"])\n    x = [tb + np.radians(dtheta0_deg), 0.0]\n    dx = np.array([np.radians(dtheta0_deg), 0.0])\n    th_nl, th_lin = [float(np.degrees(x[0]))], [float(np.degrees(tb + dx[0]))]\n    for _ in range(int(round(T / h))):\n        x = d03_pendulum_step(x, 0.0, h)\n        dx = A @ dx\n        th_nl.append(float(np.degrees(x[0])))\n        th_lin.append(float(np.degrees(tb + dx[0])))\n    gap = max(abs(a - b) for a, b in zip(th_nl, th_lin))\n    return {\"theta_nl\": th_nl, \"theta_lin\": th_lin, \"max_gap_deg\": float(gap)}\n", "doc": "Nonlinear rollout from rest at theta_bar + dtheta0 with u = 0, next to the linearized\nprediction xbar + A^k dx0 about the equilibrium (theta_bar, 0) (slide linearization-live).\ntheta in degrees at every step, and the largest gap between the two.", "marimo": true},
"00_math_toolkit.py:d03_pendulum_step": {"file": "00_math_toolkit.py", "start": 1937, "end": 1943, "src": "def d03_pendulum_step(x, u, h=0.01, p=D03_PEND):\n    \"\"\"One semi-implicit Euler step of the pendulum, x = (theta, omega), torque u:\n    a = -(g/l) sin(theta) + u / (m l^2); omega' = omega + h a; theta' = theta + h omega'.\"\"\"\n    th, om = float(x[0]), float(x[1])\n    a = -(p[\"g\"] / p[\"l\"]) * np.sin(th) + float(u) / (p[\"m\"] * p[\"l\"] * p[\"l\"])\n    om1 = om + h * a\n    return [th + h * om1, om1]\n", "doc": "One semi-implicit Euler step of the pendulum, x = (theta, omega), torque u:\na = -(g/l) sin(theta) + u / (m l^2); omega' = omega + h a; theta' = theta + h omega'.", "marimo": true},
"00_math_toolkit.py:d03_pivot_constraint": {"file": "00_math_toolkit.py", "start": 1983, "end": 1989, "src": "def d03_pivot_constraint(q, block=D03_BLOCK, p0=(0.0, 0.0)):\n    \"\"\"Phi(q) = (x, y) + R(theta) c - p0 for q = (x, y, theta) and the lower-left corner\n    c = (-a, -b) in the block frame (slide pivoting-block-constraint).\"\"\"\n    x, y, th = (float(v) for v in q)\n    c = np.array([-block[\"a\"], -block[\"b\"]])\n    R = np.array([[np.cos(th), -np.sin(th)], [np.sin(th), np.cos(th)]])\n    return (np.array([x, y]) + R @ c - np.asarray(p0, dtype=float)).tolist()\n", "doc": "Phi(q) = (x, y) + R(theta) c - p0 for q = (x, y, theta) and the lower-left corner\nc = (-a, -b) in the block frame (slide pivoting-block-constraint).", "marimo": true},
"00_math_toolkit.py:d03_pivot_jacobian": {"file": "00_math_toolkit.py", "start": 1991, "end": 1997, "src": "def d03_pivot_jacobian(theta, block=D03_BLOCK):\n    \"\"\"J_Phi = [I | R'(theta) c] (2 x 3) of the pivot constraint, and the null vector with\n    thetadot = 1: the only motions that keep the corner still are rotations about it.\"\"\"\n    th = float(theta)\n    c = np.array([-block[\"a\"], -block[\"b\"]])\n    col = np.array([[-np.sin(th), -np.cos(th)], [np.cos(th), -np.sin(th)]]) @ c\n    return {\"J\": [[1.0, 0.0, float(col[0])], [0.0, 1.0, float(col[1])]], \"null\": [-float(col[0]), -float(col[1]), 1.0]}\n", "doc": "J_Phi = [I | R'(theta) c] (2 x 3) of the pivot constraint, and the null vector with\nthetadot = 1: the only motions that keep the corner still are rotations about it.", "marimo": true},
"00_math_toolkit.py:d03_pivot_pose": {"file": "00_math_toolkit.py", "start": 2003, "end": 2009, "src": "def d03_pivot_pose(theta, block=D03_BLOCK):\n    \"\"\"The configuration (x, y, theta) with Phi = 0 at angle theta: centre = -R(theta) c.\"\"\"\n    th = float(theta)\n    c = np.array([-block[\"a\"], -block[\"b\"]])\n    R = np.array([[np.cos(th), -np.sin(th)], [np.sin(th), np.cos(th)]])\n    ctr = -(R @ c)\n    return [float(ctr[0]), float(ctr[1]), th]\n", "doc": "The configuration (x, y, theta) with Phi = 0 at angle theta: centre = -R(theta) c.", "marimo": true},
"00_math_toolkit.py:d03_pivot_residual": {"file": "00_math_toolkit.py", "start": 1999, "end": 2001, "src": "def d03_pivot_residual(theta, qdot, block=D03_BLOCK):\n    \"\"\"J_Phi(theta) qdot, the velocity of the corner, for qdot = (xdot, ydot, thetadot).\"\"\"\n    return (np.array(d03_pivot_jacobian(theta, block)[\"J\"]) @ np.asarray(qdot, dtype=float)).tolist()\n", "doc": "J_Phi(theta) qdot, the velocity of the corner, for qdot = (xdot, ydot, thetadot).", "marimo": true},
"00_math_toolkit.py:d03_quartic": {"file": "00_math_toolkit.py", "start": 1469, "end": 1472, "src": "def d03_quartic(z):\n    \"\"\"The running quartic J(z) = z^4 - 4 z^2 + z + 4, with multiplications only.\"\"\"\n    z = float(z)\n    return z * z * z * z - 4.0 * z * z + z + 4.0\n", "doc": "The running quartic J(z) = z^4 - 4 z^2 + z + 4, with multiplications only.", "marimo": true},
"00_math_toolkit.py:d03_quartic_derivs": {"file": "00_math_toolkit.py", "start": 1474, "end": 1477, "src": "def d03_quartic_derivs(z):\n    \"\"\"[J, J', J'', J''', J''''] of the quartic at z (slide sum-rule-and-the-quartic).\"\"\"\n    z = float(z)\n    return [d03_quartic(z), 4.0 * z * z * z - 8.0 * z + 1.0, 12.0 * z * z - 8.0, 24.0 * z, 24.0]\n", "doc": "[J, J', J'', J''', J''''] of the quartic at z (slide sum-rule-and-the-quartic).", "marimo": true},
"00_math_toolkit.py:d03_rotation_derivative": {"file": "00_math_toolkit.py", "start": 1554, "end": 1560, "src": "def d03_rotation_derivative(theta):\n    \"\"\"dR/dtheta of the planar rotation R(theta), entry by entry, and R(theta) S with the quarter\n    turn S = [[0, -1], [1, 0]]; the two are equal (slide sine-cosine-derivatives).\"\"\"\n    c, s = np.cos(theta), np.sin(theta)\n    dR = np.array([[-s, -c], [c, -s]])\n    RS = np.array([[c, -s], [s, c]]) @ np.array([[0.0, -1.0], [1.0, 0.0]])\n    return {\"dR\": dR.tolist(), \"RS\": RS.tolist()}\n", "doc": "dR/dtheta of the planar rotation R(theta), entry by entry, and R(theta) S with the quarter\nturn S = [[0, -1], [1, 0]]; the two are equal (slide sine-cosine-derivatives).", "marimo": true},
"00_math_toolkit.py:d03_secant_slope": {"file": "00_math_toolkit.py", "start": 1479, "end": 1481, "src": "def d03_secant_slope(z0, h):\n    \"\"\"Slope (J(z0 + h) - J(z0)) / h of the secant through z0 and z0 + h (slide secant-and-tangent).\"\"\"\n    return (d03_quartic(z0 + h) - d03_quartic(z0)) / h\n", "doc": "Slope (J(z0 + h) - J(z0)) / h of the secant through z0 and z0 + h (slide secant-and-tangent).", "marimo": true},
"00_math_toolkit.py:d03_secant_table": {"file": "00_math_toolkit.py", "start": 1483, "end": 1489, "src": "def d03_secant_table(z0=1.0, hs=(0.5, 0.1, 0.01, 0.001)):\n    \"\"\"Secant slopes at z0 for shrinking h, and their distance from J'(z0) (slide derivative-as-limit).\n\n    For the quartic at z0 = 1 the error is exactly 2h + 4h^2 + h^3.\n    \"\"\"\n    d = d03_quartic_derivs(z0)[1]\n    return [{\"h\": h, \"slope\": d03_secant_slope(z0, h), \"error\": d03_secant_slope(z0, h) - d} for h in hs]\n", "doc": "Secant slopes at z0 for shrinking h, and their distance from J'(z0) (slide derivative-as-limit).\n\nFor the quartic at z0 = 1 the error is exactly 2h + 4h^2 + h^3.", "marimo": true},
"00_math_toolkit.py:d03_sincos_check": {"file": "00_math_toolkit.py", "start": 1547, "end": 1552, "src": "def d03_sincos_check(theta, h=1e-5):\n    \"\"\"Central-difference slopes of cos and sin at theta next to -sin(theta) and cos(theta)\n    (slide sine-cosine-derivatives); theta in radians.\"\"\"\n    dc = (np.cos(theta + h) - np.cos(theta - h)) / (2 * h)\n    ds = (np.sin(theta + h) - np.sin(theta - h)) / (2 * h)\n    return {\"dcos_fd\": float(dc), \"minus_sin\": float(-np.sin(theta)), \"dsin_fd\": float(ds), \"cos\": float(np.cos(theta))}\n", "doc": "Central-difference slopes of cos and sin at theta next to -sin(theta) and cos(theta)\n(slide sine-cosine-derivatives); theta in radians.", "marimo": true},
"00_math_toolkit.py:d03_slice_curvature": {"file": "00_math_toolkit.py", "start": 1717, "end": 1726, "src": "def d03_slice_curvature(z, phi_deg):\n    \"\"\"Along z + t d, d = (cos phi, sin phi): g(t) = J(z + t d) has g'(0) = grad J . d and\n    g''(0) = d^T H d; a central second difference checks g''(0) (slide curvature-along-a-line).\"\"\"\n    phi = np.radians(phi_deg)\n    d = np.array([np.cos(phi), np.sin(phi)])\n    z = np.asarray(z, dtype=float)\n    H = np.array(d03_valley_hess(z))\n    t = 1e-4\n    fd2 = (d03_valley(z + t * d) - 2 * d03_valley(z) + d03_valley(z - t * d)) / (t * t)\n    return {\"g1\": float(np.array(d03_valley_grad(z)) @ d), \"g2\": float(d @ H @ d), \"fd2\": float(fd2)}\n", "doc": "Along z + t d, d = (cos phi, sin phi): g(t) = J(z + t d) has g'(0) = grad J . d and\ng''(0) = d^T H d; a central second difference checks g''(0) (slide curvature-along-a-line).", "marimo": true},
"00_math_toolkit.py:d03_stationary_points": {"file": "00_math_toolkit.py", "start": 1491, "end": 1506, "src": "def d03_stationary_points():\n    \"\"\"The three roots of J'(z) = 4 z^3 - 8 z + 1 with J and J'' there (slide second-derivative-curvature).\n\n    Newton's method on J' from -1.5, 0 and 1.5.\n    \"\"\"\n    out = []\n    for z in (-1.5, 0.0, 1.5):\n        for _ in range(60):\n            d = d03_quartic_derivs(z)\n            step = d[1] / d[2]\n            z -= step\n            if abs(step) < 1e-15:\n                break\n        d = d03_quartic_derivs(z)\n        out.append({\"z\": z, \"J\": d[0], \"d2J\": d[2]})\n    return out\n", "doc": "The three roots of J'(z) = 4 z^3 - 8 z + 1 with J and J'' there (slide second-derivative-curvature).\n\nNewton's method on J' from -1.5, 0 and 1.5.", "marimo": true},
"00_math_toolkit.py:d03_steepest_directions": {"file": "00_math_toolkit.py", "start": 1697, "end": 1704, "src": "def d03_steepest_directions(z):\n    \"\"\"Angles (deg) of steepest ascent grad J / |grad J|, steepest descent, and the two level-set\n    directions (grad J . d = 0), and the steepest rate |grad J| (slide steepest-ascent).\"\"\"\n    g = np.array(d03_valley_grad(z))\n    a = float(np.degrees(np.arctan2(g[1], g[0])))\n    wrap = lambda x: (x + 180.0) % 360.0 - 180.0\n    return {\"ascent\": a, \"descent\": wrap(a + 180.0), \"level\": sorted([wrap(a + 90.0), wrap(a - 90.0)]),\n            \"rate\": float(np.linalg.norm(g))}\n", "doc": "Angles (deg) of steepest ascent grad J / |grad J|, steepest descent, and the two level-set\ndirections (grad J . d = 0), and the steepest rate |grad J| (slide steepest-ascent).", "marimo": true},
"00_math_toolkit.py:d03_taylor_coeffs": {"file": "00_math_toolkit.py", "start": 1513, "end": 1520, "src": "def d03_taylor_coeffs(z0):\n    \"\"\"c_k = J^(k)(z0) / k!, k = 0..4, of the quartic's Taylor polynomial at z0 (slide taylor-polynomials).\n\n    The degree-4 polynomial equals J exactly: at z0 = 1, J(1 + d) = 2 - 3d + 2d^2 + 4d^3 + d^4.\n    \"\"\"\n    d = d03_quartic_derivs(z0)\n    fact = [1.0, 1.0, 2.0, 6.0, 24.0]\n    return [d[k] / fact[k] for k in range(5)]\n", "doc": "c_k = J^(k)(z0) / k!, k = 0..4, of the quartic's Taylor polynomial at z0 (slide taylor-polynomials).\n\nThe degree-4 polynomial equals J exactly: at z0 = 1, J(1 + d) = 2 - 3d + 2d^2 + 4d^3 + d^4.", "marimo": true},
"00_math_toolkit.py:d03_taylor_error_table": {"file": "00_math_toolkit.py", "start": 1534, "end": 1545, "src": "def d03_taylor_error_table(z0=1.0, deltas=(0.2, 0.1, 0.05, 0.025)):\n    \"\"\"Errors of the linear and quadratic models for halving steps, with the ratios of successive\n    errors, which approach 4 and 8 (slide taylor-error-order).\"\"\"\n    rows = []\n    for d in deltas:\n        J = d03_quartic(z0 + d)\n        lin, quad = d03_taylor_poly(z0, d, 1), d03_taylor_poly(z0, d, 2)\n        rows.append({\"delta\": d, \"J\": J, \"lin\": lin, \"quad\": quad, \"err_lin\": J - lin, \"err_quad\": J - quad})\n    for a, b in zip(rows, rows[1:]):\n        b[\"ratio_lin\"] = a[\"err_lin\"] / b[\"err_lin\"]\n        b[\"ratio_quad\"] = a[\"err_quad\"] / b[\"err_quad\"]\n    return rows\n", "doc": "Errors of the linear and quadratic models for halving steps, with the ratios of successive\nerrors, which approach 4 and 8 (slide taylor-error-order).", "marimo": true},
"00_math_toolkit.py:d03_taylor_poly": {"file": "00_math_toolkit.py", "start": 1522, "end": 1532, "src": "def d03_taylor_poly(z0, delta, degree):\n    \"\"\"Value at z0 + delta of the degree-n Taylor polynomial of the quartic around z0.\n\n    Degree 1 is the tangent line (linear model), degree 2 the quadratic model (slide taylor-models-live).\n    \"\"\"\n    c = d03_taylor_coeffs(z0)\n    s, p = 0.0, 1.0\n    for k in range(int(degree) + 1):\n        s += c[k] * p\n        p *= delta\n    return s\n", "doc": "Value at z0 + delta of the degree-n Taylor polynomial of the quartic around z0.\n\nDegree 1 is the tangent line (linear model), degree 2 the quadratic model (slide taylor-models-live).", "marimo": true},
"00_math_toolkit.py:d03_valley": {"file": "00_math_toolkit.py", "start": 1651, "end": 1655, "src": "def d03_valley(z):\n    \"\"\"J(z1, z2) = z1^4 - 4 z1^2 + z1 + 4 + 2 (z2 - z1)^2 (slides contour-plots onward).\"\"\"\n    z1, z2 = float(z[0]), float(z[1])\n    e = z2 - z1\n    return z1 * z1 * z1 * z1 - 4.0 * z1 * z1 + z1 + 4.0 + 2.0 * e * e\n", "doc": "J(z1, z2) = z1^4 - 4 z1^2 + z1 + 4 + 2 (z2 - z1)^2 (slides contour-plots onward).", "marimo": true},
"00_math_toolkit.py:d03_valley_grad": {"file": "00_math_toolkit.py", "start": 1657, "end": 1660, "src": "def d03_valley_grad(z):\n    \"\"\"Gradient (4 z1^3 - 8 z1 + 1 - 4 (z2 - z1), 4 (z2 - z1)) of the valley function.\"\"\"\n    z1, z2 = float(z[0]), float(z[1])\n    return [4.0 * z1 * z1 * z1 - 8.0 * z1 + 1.0 - 4.0 * (z2 - z1), 4.0 * (z2 - z1)]\n", "doc": "Gradient (4 z1^3 - 8 z1 + 1 - 4 (z2 - z1), 4 (z2 - z1)) of the valley function.", "marimo": true},
"00_math_toolkit.py:d03_valley_hess": {"file": "00_math_toolkit.py", "start": 1662, "end": 1665, "src": "def d03_valley_hess(z):\n    \"\"\"Hessian [[12 z1^2 - 4, -4], [-4, 4]] of the valley function (slide hessian-matrix).\"\"\"\n    z1 = float(z[0])\n    return [[12.0 * z1 * z1 - 4.0, -4.0], [-4.0, 4.0]]\n", "doc": "Hessian [[12 z1^2 - 4, -4], [-4, 4]] of the valley function (slide hessian-matrix).", "marimo": true},
"00_math_toolkit.py:d03_valley_models": {"file": "00_math_toolkit.py", "start": 1740, "end": 1748, "src": "def d03_valley_models(z0, delta):\n    \"\"\"J(z0 + delta) next to the linear model J + grad J . delta and the quadratic model\n    (+ delta^T H delta / 2) (slides multivariable-taylor, quadratic-model-contours).\"\"\"\n    z0 = np.asarray(z0, dtype=float)\n    delta = np.asarray(delta, dtype=float)\n    g = np.array(d03_valley_grad(z0))\n    H = np.array(d03_valley_hess(z0))\n    lin = d03_valley(z0) + g @ delta\n    return {\"J\": d03_valley(z0 + delta), \"lin\": float(lin), \"quad\": float(lin + 0.5 * delta @ H @ delta)}\n", "doc": "J(z0 + delta) next to the linear model J + grad J . delta and the quadratic model\n(+ delta^T H delta / 2) (slides multivariable-taylor, quadratic-model-contours).", "marimo": true},
"00_math_toolkit.py:d03_valley_stationary": {"file": "00_math_toolkit.py", "start": 1667, "end": 1673, "src": "def d03_valley_stationary():\n    \"\"\"Stationary points (r, r), r a root of the quartic's J', with J and the Hessian eigenvalues.\"\"\"\n    out = []\n    for p in d03_stationary_points():\n        ev = np.linalg.eigvalsh(np.array(d03_valley_hess([p[\"z\"], p[\"z\"]])))\n        out.append({\"z\": [p[\"z\"], p[\"z\"]], \"J\": d03_valley([p[\"z\"], p[\"z\"]]), \"eig\": [float(ev[1]), float(ev[0])]})\n    return out\n", "doc": "Stationary points (r, r), r a root of the quartic's J', with J and the Hessian eigenvalues.", "marimo": true},
"00_math_toolkit.py:d04_at_least_one": {"file": "00_math_toolkit.py", "start": 2359, "end": 2361, "src": "def d04_at_least_one(p, k):\n    \"\"\"P(at least one success in k independent trials of probability p) = 1 - (1 - p)^k.\"\"\"\n    return 1.0 - (1.0 - p) ** k\n", "doc": "P(at least one success in k independent trials of probability p) = 1 - (1 - p)^k.", "marimo": true},
"00_math_toolkit.py:d04_box_muller": {"file": "00_math_toolkit.py", "start": 2298, "end": 2306, "src": "def d04_box_muller(u1, u2):\n    \"\"\"Box-Muller: uniforms u1 in (0, 1], u2 in [0, 1) -> two independent standard normals.\n\n    r = sqrt(-2 ln u1) is the radius, theta = 2 pi u2 the angle (slide box-muller).\n    \"\"\"\n    r = _math.sqrt(-2.0 * _math.log(u1))\n    th = 2.0 * _math.pi * u2\n    return {\"r\": r, \"theta\": th, \"deg\": _math.degrees(th),\n            \"z1\": r * _math.cos(th), \"z2\": r * _math.sin(th)}\n", "doc": "Box-Muller: uniforms u1 in (0, 1], u2 in [0, 1) -> two independent standard normals.\n\nr = sqrt(-2 ln u1) is the radius, theta = 2 pi u2 the angle (slide box-muller).", "marimo": true},
"00_math_toolkit.py:d04_cem_cost": {"file": "00_math_toolkit.py", "start": 2763, "end": 2773, "src": "def d04_cem_cost(z):\n    \"\"\"Two-basin cost of slide elite-refit-live: min(q_A, 1 + 0.3 |z - b|^2).\n\n    q_A = (u / 1.2)^2 + (v / 0.3)^2 in coordinates (u, v) along and across a valley through\n    a = (1.4, 0.9) at 35 degrees; J(a) = 0. The wide bowl around b = (-1.4, -0.9) has J(b) = 1.\n    \"\"\"\n    Z = np.atleast_2d(np.asarray(z, float))\n    d = Z - _A\n    u = _math.cos(_PHI) * d[:, 0] + _math.sin(_PHI) * d[:, 1]\n    v = -_math.sin(_PHI) * d[:, 0] + _math.cos(_PHI) * d[:, 1]\n    return np.minimum((u / 1.2) ** 2 + (v / 0.3) ** 2, 1.0 + 0.3 * ((Z - _B) ** 2).sum(axis=1))\n", "doc": "Two-basin cost of slide elite-refit-live: min(q_A, 1 + 0.3 |z - b|^2).\n\nq_A = (u / 1.2)^2 + (v / 0.3)^2 in coordinates (u, v) along and across a valley through\na = (1.4, 0.9) at 35 degrees; J(a) = 0. The wide bowl around b = (-1.4, -0.9) has J(b) = 1.", "marimo": true},
"00_math_toolkit.py:d04_cem_run": {"file": "00_math_toolkit.py", "start": 2775, "end": 2793, "src": "def d04_cem_run(m0=(0.0, 2.0), s0=1.5, frac=0.2, n=40, iters=10, seed=1):\n    \"\"\"Repeated elite refitting: sample N(m, Sigma), keep the best floor(frac n), refit m and Sigma.\n\n    Each iteration draws n points x = m + L eps (L = chol(Sigma + 1e-12 I), eps from\n    Num.rng(seed)), then sets m, Sigma to the elite mean and covariance (1/K). Returns one\n    record per iteration with the distribution it sampled from and the best cost it saw.\n    \"\"\"\n    R = D04Rng(seed)\n    m, S = np.array(m0, float), s0 * s0 * np.eye(2)\n    hist = []\n    for _ in range(iters):\n        L = np.linalg.cholesky(S + 1e-12 * np.eye(2))\n        Z = m + R.normals(2 * n).reshape(n, 2) @ L.T\n        J = d04_cem_cost(Z)\n        fit = d04_elite_fit(Z, J, frac)\n        hist.append({\"mean\": m.tolist(), \"cov\": S.tolist(), \"best\": float(J.min()), \"elites\": fit[\"idx\"]})\n        m, S = np.array(fit[\"mean\"]), np.array(fit[\"cov\"])\n    hist.append({\"mean\": m.tolist(), \"cov\": S.tolist(), \"best\": float(d04_cem_cost(m)[0]), \"elites\": []})\n    return hist\n", "doc": "Repeated elite refitting: sample N(m, Sigma), keep the best floor(frac n), refit m and Sigma.\n\nEach iteration draws n points x = m + L eps (L = chol(Sigma + 1e-12 I), eps from\nNum.rng(seed)), then sets m, Sigma to the elite mean and covariance (1/K). Returns one\nrecord per iteration with the distribution it sampled from and the best cost it saw.", "marimo": true},
"00_math_toolkit.py:d04_chol2": {"file": "00_math_toolkit.py", "start": 2554, "end": 2564, "src": "def d04_chol2(Sigma):\n    \"\"\"Cholesky factor L = [[l11, 0], [l21, l22]] of a 2x2 covariance, or None when not positive definite.\"\"\"\n    S = np.asarray(Sigma, float)\n    if S[0, 0] <= 0:\n        return None\n    l11 = _math.sqrt(S[0, 0])\n    l21 = S[1, 0] / l11\n    r = S[1, 1] - l21 * l21\n    if r <= 0:\n        return None\n    return [[l11, 0.0], [l21, _math.sqrt(r)]]\n", "doc": "Cholesky factor L = [[l11, 0], [l21, l22]] of a 2x2 covariance, or None when not positive definite.", "marimo": true},
"00_math_toolkit.py:d04_cov_ellipse": {"file": "00_math_toolkit.py", "start": 2518, "end": 2529, "src": "def d04_cov_ellipse(Sigma):\n    \"\"\"Principal variances s1^2 >= s2^2, their square roots, and the angle (deg) of the major axis.\n\n    Sigma = V diag(s1^2, s2^2) V^T; the first eigenvector is signed so that its largest entry\n    is positive, and the angle is reported in (-90, 90].\n    \"\"\"\n    w, V = np.linalg.eigh(np.asarray(Sigma, float))\n    w, V = w[::-1], V[:, ::-1]\n    v = V[:, 0] if V[np.argmax(np.abs(V[:, 0])), 0] > 0 else -V[:, 0]\n    ang = _math.degrees(_math.atan2(v[1], v[0]))\n    ang = ang + 180 if ang <= -90 else ang - 180 if ang > 90 else ang\n    return {\"var\": w.tolist(), \"std\": np.sqrt(np.maximum(w, 0)).tolist(), \"angle\": ang, \"v1\": v.tolist()}\n", "doc": "Principal variances s1^2 >= s2^2, their square roots, and the angle (deg) of the major axis.\n\nSigma = V diag(s1^2, s2^2) V^T; the first eigenvector is signed so that its largest entry\nis positive, and the angle is reported in (-90, 90].", "marimo": true},
"00_math_toolkit.py:d04_cov_from_axes": {"file": "00_math_toolkit.py", "start": 2531, "end": 2535, "src": "def d04_cov_from_axes(s1, s2, phi_deg):\n    \"\"\"Sigma = V diag(s1^2, s2^2) V^T with V the rotation by phi (the covariance-ellipse sliders).\"\"\"\n    c, s = _math.cos(_math.radians(phi_deg)), _math.sin(_math.radians(phi_deg))\n    V = np.array([[c, -s], [s, c]])\n    return (V @ np.diag([s1 * s1, s2 * s2]) @ V.T).tolist()\n", "doc": "Sigma = V diag(s1^2, s2^2) V^T with V the rotation by phi (the covariance-ellipse sliders).", "marimo": true},
"00_math_toolkit.py:d04_diagonal_fraction": {"file": "00_math_toolkit.py", "start": 2832, "end": 2835, "src": "def d04_diagonal_fraction(ang, half_deg=15.0):\n    \"\"\"Fraction of angles within half_deg of a diagonal (45, 135, 225 or 315 degrees).\"\"\"\n    a = np.degrees(np.asarray(ang, float)) % 90.0\n    return float(np.mean(np.abs(a - 45.0) <= half_deg))\n", "doc": "Fraction of angles within half_deg of a diagonal (45, 135, 225 or 315 degrees).", "marimo": true},
"00_math_toolkit.py:d04_die_rolls": {"file": "00_math_toolkit.py", "start": 2363, "end": 2366, "src": "def d04_die_rolls(n, seed, dice=1):\n    \"\"\"n rolls from Num.rng(seed), each the sum of `dice` dice; one die is 1 + floor(6 u).\"\"\"\n    u = D04Rng(seed).uniforms(n * dice).reshape(n, dice)\n    return (1 + np.floor(6 * u)).sum(axis=1).astype(int)\n", "doc": "n rolls from Num.rng(seed), each the sum of `dice` dice; one die is 1 + floor(6 u).", "marimo": true},
"00_math_toolkit.py:d04_directional_variance": {"file": "00_math_toolkit.py", "start": 2507, "end": 2510, "src": "def d04_directional_variance(Sigma, theta_deg):\n    \"\"\"a^T Sigma a for the unit vector a at angle theta: the variance of a^T x.\"\"\"\n    a = np.array([_math.cos(_math.radians(theta_deg)), _math.sin(_math.radians(theta_deg))])\n    return float(a @ np.asarray(Sigma, float) @ a)\n", "doc": "a^T Sigma a for the unit vector a at angle theta: the variance of a^T x.", "marimo": true},
"00_math_toolkit.py:d04_directions": {"file": "00_math_toolkit.py", "start": 2826, "end": 2830, "src": "def d04_directions(n, seed, method):\n    \"\"\"Angles of n random unit vectors: 'gauss' normalizes N(0, I) draws, 'square' U[-1, 1]^2 draws.\"\"\"\n    R = D04Rng(seed)\n    P = R.normals(2 * n).reshape(n, 2) if method == \"gauss\" else (2 * R.uniforms(2 * n) - 1).reshape(n, 2)\n    return np.arctan2(P[:, 1], P[:, 0])\n", "doc": "Angles of n random unit vectors: 'gauss' normalizes N(0, I) draws, 'square' U[-1, 1]^2 draws.", "marimo": true},
"00_math_toolkit.py:d04_elite_fit": {"file": "00_math_toolkit.py", "start": 2742, "end": 2751, "src": "def d04_elite_fit(z, J, frac):\n    \"\"\"Mean and covariance (1/K) of the K = floor(frac N) samples with the lowest costs.\"\"\"\n    z = np.asarray(z, float)\n    z = z[:, None] if z.ndim == 1 else z\n    K = int(_math.floor(frac * len(J) + 1e-9))\n    idx = np.argsort(np.asarray(J, float), kind=\"stable\")[:K]\n    E = z[idx]\n    m = E.mean(axis=0)\n    D = E - m\n    return {\"K\": K, \"idx\": idx.tolist(), \"mean\": m.tolist(), \"cov\": (D.T @ D / K).tolist()}\n", "doc": "Mean and covariance (1/K) of the K = floor(frac N) samples with the lowest costs.", "marimo": true},
"00_math_toolkit.py:d04_ellipse_fractions": {"file": "00_math_toolkit.py", "start": 2541, "end": 2552, "src": "def d04_ellipse_fractions(s1, s2, phi_deg, n, seed, ks=(1, 2, 3)):\n    \"\"\"Fractions of n draws x = V diag(s1, s2) eps inside the k-sigma ellipses of their Sigma.\n\n    x^T Sigma^{-1} x = |eps|^2 for every draw, so the fractions do not depend on s1, s2, phi.\n    \"\"\"\n    c, s = _math.cos(_math.radians(phi_deg)), _math.sin(_math.radians(phi_deg))\n    A = np.array([[c, -s], [s, c]]) @ np.diag([s1, s2])\n    E = D04Rng(seed).normals(2 * n).reshape(n, 2)\n    X = E @ A.T\n    S = np.asarray(d04_cov_from_axes(s1, s2, phi_deg))\n    q = np.einsum(\"ij,jk,ik->i\", X, np.linalg.inv(S), X)\n    return [float(np.mean(q <= k * k)) for k in ks]\n", "doc": "Fractions of n draws x = V diag(s1, s2) eps inside the k-sigma ellipses of their Sigma.\n\nx^T Sigma^{-1} x = |eps|^2 for every draw, so the fractions do not depend on s1, s2, phi.", "marimo": true},
"00_math_toolkit.py:d04_ellipse_prob": {"file": "00_math_toolkit.py", "start": 2537, "end": 2539, "src": "def d04_ellipse_prob(k):\n    \"\"\"P(a 2D Gaussian draw lies inside its k-sigma ellipse) = 1 - exp(-k^2 / 2).\"\"\"\n    return 1.0 - _math.exp(-0.5 * k * k)\n", "doc": "P(a 2D Gaussian draw lies inside its k-sigma ellipse) = 1 - exp(-k^2 / 2).", "marimo": true},
"00_math_toolkit.py:d04_ess": {"file": "00_math_toolkit.py", "start": 2701, "end": 2704, "src": "def d04_ess(w):\n    \"\"\"Effective sample size 1 / sum w_i^2 of normalized weights.\"\"\"\n    w = np.asarray(w, float)\n    return float(1.0 / np.sum(w * w))\n", "doc": "Effective sample size 1 / sum w_i^2 of normalized weights.", "marimo": true},
"00_math_toolkit.py:d04_gauss_pdf": {"file": "00_math_toolkit.py", "start": 2436, "end": 2439, "src": "def d04_gauss_pdf(x, m=0.0, s=1.0):\n    \"\"\"Gaussian density exp(-(x - m)^2 / (2 s^2)) / (s sqrt(2 pi)) (slide gaussian-pdf).\"\"\"\n    x = np.asarray(x, float)\n    return np.exp(-0.5 * ((x - m) / s) ** 2) / (s * _math.sqrt(2 * _math.pi))\n", "doc": "Gaussian density exp(-(x - m)^2 / (2 s^2)) / (s sqrt(2 pi)) (slide gaussian-pdf).", "marimo": true},
"00_math_toolkit.py:d04_hou2021_test_count": {"file": "00_math_toolkit.py", "start": 2814, "end": 2824, "src": "def d04_hou2021_test_count():\n    \"\"\"Contact settings of Hou & Mason 2021, Table I, and the number of random test problems.\n\n    A row is (environment contacts, contact-mode choices, contacts-per-finger choices, finger\n    choices); each setting gets 1000 random sets of contact locations and normals.\n    \"\"\"\n    planar = [(1, 2, 2, 1), (2, 1, 2, 1)]\n    spatial = [(1, 2, 3, 3), (2, 3, 3, 3), (3, 3, 3, 3)]\n    n_pl = sum(m * c * f for _, m, c, f in planar)\n    n_3d = sum(m * c * f for _, m, c, f in spatial)\n    return {\"planar\": n_pl, \"spatial\": n_3d, \"problems\": 1000 * (n_pl + n_3d)}\n", "doc": "Contact settings of Hou & Mason 2021, Table I, and the number of random test problems.\n\nA row is (environment contacts, contact-mode choices, contacts-per-finger choices, finger\nchoices); each setting gets 1000 random sets of contact locations and normals.", "marimo": true},
"00_math_toolkit.py:d04_lambda_for_ess": {"file": "00_math_toolkit.py", "start": 2706, "end": 2715, "src": "def d04_lambda_for_ess(J, target, lo=1e-3, hi=1e3, iters=100):\n    \"\"\"Temperature at which N_eff = target, by bisection on log(lambda); N_eff grows with lambda.\"\"\"\n    a, b = _math.log(lo), _math.log(hi)\n    for _ in range(iters):\n        c = 0.5 * (a + b)\n        if d04_ess(d04_softmax_weights(J, _math.exp(c))) < target:\n            a = c\n        else:\n            b = c\n    return _math.exp(0.5 * (a + b))\n", "doc": "Temperature at which N_eff = target, by bisection on log(lambda); N_eff grows with lambda.", "marimo": true},
"00_math_toolkit.py:d04_max_two_dice_counts": {"file": "00_math_toolkit.py", "start": 2344, "end": 2350, "src": "def d04_max_two_dice_counts():\n    \"\"\"How many of the 36 outcomes give each value 1..6 of max(a, b) (slide mean).\"\"\"\n    c = {k: 0 for k in range(1, 7)}\n    for a in range(1, 7):\n        for b in range(1, 7):\n            c[max(a, b)] += 1\n    return c\n", "doc": "How many of the 36 outcomes give each value 1..6 of max(a, b) (slide mean).", "marimo": true},
"00_math_toolkit.py:d04_mc_pi": {"file": "00_math_toolkit.py", "start": 2586, "end": 2590, "src": "def d04_mc_pi(n, seed):\n    \"\"\"pi from n uniform points in the unit square: 4 x (fraction with u1^2 + u2^2 <= 1).\"\"\"\n    u = D04Rng(seed).uniforms(2 * n).reshape(n, 2)\n    inside = int(((u**2).sum(axis=1) <= 1.0).sum())\n    return {\"n\": n, \"inside\": inside, \"estimate\": 4.0 * inside / n}\n", "doc": "pi from n uniform points in the unit square: 4 x (fraction with u1^2 + u2^2 <= 1).", "marimo": true},
"00_math_toolkit.py:d04_mc_pi_rms": {"file": "00_math_toolkit.py", "start": 2592, "end": 2598, "src": "def d04_mc_pi_rms(ns, trials=200, seed0=1):\n    \"\"\"Root-mean-square error of the pi estimate over the seeds seed0 .. seed0 + trials - 1.\"\"\"\n    out = []\n    for n in ns:\n        e = [d04_mc_pi(n, seed0 + t)[\"estimate\"] - _math.pi for t in range(trials)]\n        out.append(float(_math.sqrt(np.mean(np.square(e)))))\n    return out\n", "doc": "Root-mean-square error of the pi estimate over the seeds seed0 .. seed0 + trials - 1.", "marimo": true},
"00_math_toolkit.py:d04_mvn_pdf": {"file": "00_math_toolkit.py", "start": 2572, "end": 2576, "src": "def d04_mvn_pdf(x, m, Sigma):\n    \"\"\"Density exp(-(x - m)^T Sigma^{-1} (x - m) / 2) / sqrt((2 pi)^n det Sigma).\"\"\"\n    x, m, S = np.asarray(x, float), np.asarray(m, float), np.asarray(Sigma, float)\n    d = x - m\n    return float(_math.exp(-0.5 * d @ np.linalg.solve(S, d)) / _math.sqrt((2 * _math.pi) ** len(m) * np.linalg.det(S)))\n", "doc": "Density exp(-(x - m)^T Sigma^{-1} (x - m) / 2) / sqrt((2 pi)^n det Sigma).", "marimo": true},
"00_math_toolkit.py:d04_mvn_samples": {"file": "00_math_toolkit.py", "start": 2566, "end": 2570, "src": "def d04_mvn_samples(m, Sigma, n, seed):\n    \"\"\"n draws x = m + L eps (eps two standard normals from Num.rng(seed), L L^T = Sigma).\"\"\"\n    L = np.array(d04_chol2(Sigma))\n    E = D04Rng(seed).normals(2 * n).reshape(n, 2)\n    return np.asarray(m, float) + E @ L.T\n", "doc": "n draws x = m + L eps (eps two standard normals from Num.rng(seed), L L^T = Sigma).", "marimo": true},
"00_math_toolkit.py:d04_normal_cdf": {"file": "00_math_toolkit.py", "start": 2441, "end": 2443, "src": "def d04_normal_cdf(x):\n    \"\"\"P(Z <= x) for a standard normal Z, via erfc so that both tails keep their digits.\"\"\"\n    return 0.5 * _math.erfc(-x / _math.sqrt(2.0))\n", "doc": "P(Z <= x) for a standard normal Z, via erfc so that both tails keep their digits.", "marimo": true},
"00_math_toolkit.py:d04_pmf_moments": {"file": "00_math_toolkit.py", "start": 2352, "end": 2357, "src": "def d04_pmf_moments(values, probs):\n    \"\"\"Mean, variance, standard deviation and E[X^2] of a discrete distribution.\"\"\"\n    x, p = np.asarray(values, float), np.asarray(probs, float)\n    m = float(p @ x)\n    v = float(p @ (x - m) ** 2)\n    return {\"mean\": m, \"var\": v, \"std\": float(np.sqrt(v)), \"EX2\": float(p @ x**2)}\n", "doc": "Mean, variance, standard deviation and E[X^2] of a discrete distribution.", "marimo": true},
"00_math_toolkit.py:d04_prob_within": {"file": "00_math_toolkit.py", "start": 2445, "end": 2447, "src": "def d04_prob_within(k):\n    \"\"\"P(|X - m| <= k sigma) for any Gaussian = erf(k / sqrt 2) (slide rule-68-95-997).\"\"\"\n    return _math.erf(k / _math.sqrt(2.0))\n", "doc": "P(|X - m| <= k sigma) for any Gaussian = erf(k / sqrt 2) (slide rule-68-95-997).", "marimo": true},
"00_math_toolkit.py:d04_projected_variance": {"file": "00_math_toolkit.py", "start": 2512, "end": 2516, "src": "def d04_projected_variance(Sigma, theta_deg, n, seed):\n    \"\"\"a^T Sigma a and the sample variance (1/N) of a^T x_i over n draws of N(0, Sigma).\"\"\"\n    X = d04_mvn_samples([0.0, 0.0], Sigma, n, seed)\n    a = np.array([_math.cos(_math.radians(theta_deg)), _math.sin(_math.radians(theta_deg))])\n    return {\"theory\": d04_directional_variance(Sigma, theta_deg), \"sample\": float(np.var(X @ a))}\n", "doc": "a^T Sigma a and the sample variance (1/N) of a^T x_i over n draws of N(0, Sigma).", "marimo": true},
"00_math_toolkit.py:d04_quartic": {"file": "00_math_toolkit.py", "start": 2795, "end": 2797, "src": "def d04_quartic(z):\n    \"\"\"The running quartic J(z) = z^4 - 4 z^2 + z + 4 of decks 05 and 04.\"\"\"\n    return z**4 - 4 * z**2 + z + 4\n", "doc": "The running quartic J(z) = z^4 - 4 z^2 + z + 4 of decks 05 and 04.", "marimo": true},
"00_math_toolkit.py:d04_quartic_stationary": {"file": "00_math_toolkit.py", "start": 2799, "end": 2802, "src": "def d04_quartic_stationary():\n    \"\"\"Roots of J'(z) = 4 z^3 - 8 z + 1 (ascending), with J and J'' = 12 z^2 - 8 there.\"\"\"\n    r = np.sort(np.roots([4.0, 0.0, -8.0, 1.0]).real)\n    return {\"z\": r.tolist(), \"J\": [float(d04_quartic(t)) for t in r], \"J2\": [float(12 * t * t - 8) for t in r]}\n", "doc": "Roots of J'(z) = 4 z^3 - 8 z + 1 (ascending), with J and J'' = 12 z^2 - 8 there.", "marimo": true},
"00_math_toolkit.py:d04_radius_tail": {"file": "00_math_toolkit.py", "start": 2308, "end": 2310, "src": "def d04_radius_tail(r):\n    \"\"\"P(|z| > r) for a 2D standard normal z: exp(-r^2 / 2) (slide box-muller-radius).\"\"\"\n    return _math.exp(-0.5 * r * r)\n", "doc": "P(|z| > r) for a 2D standard normal z: exp(-r^2 / 2) (slide box-muller-radius).", "marimo": true},
"00_math_toolkit.py:d04_radius_tail_samples": {"file": "00_math_toolkit.py", "start": 2312, "end": 2316, "src": "def d04_radius_tail_samples(n, seed, rs=(1.0, 2.0, 3.0)):\n    \"\"\"Fraction of n draws (z1, z2) from Num.rng(seed) with radius above each r.\"\"\"\n    z = D04Rng(seed).normals(2 * n).reshape(n, 2)\n    rad = np.hypot(z[:, 0], z[:, 1])\n    return [float(np.mean(rad > r)) for r in rs]\n", "doc": "Fraction of n draws (z1, z2) from Num.rng(seed) with radius above each r.", "marimo": true},
"00_math_toolkit.py:d04_restart_success": {"file": "00_math_toolkit.py", "start": 2804, "end": 2812, "src": "def d04_restart_success(k, lo=-2.0, hi=2.0, trials=1000, seed=1):\n    \"\"\"k random starts z0 ~ U[lo, hi]; rolling downhill from z0 reaches the global minimum\n    exactly when z0 lies left of the local maximum. Returns p for one start, 1 - (1 - p)^k, and\n    the fraction of `trials` runs (uniforms from Num.rng(seed)) with a start in that basin.\n    \"\"\"\n    zmax = d04_quartic_stationary()[\"z\"][1]\n    p = (zmax - lo) / (hi - lo)\n    z0 = lo + (hi - lo) * D04Rng(seed).uniforms(trials * k).reshape(trials, k)\n    return {\"zmax\": zmax, \"p\": p, \"theory\": 1 - (1 - p) ** k, \"empirical\": float(np.mean((z0 < zmax).any(axis=1)))}\n", "doc": "k random starts z0 ~ U[lo, hi]; rolling downhill from z0 reaches the global minimum\nexactly when z0 lies left of the local maximum. Returns p for one start, 1 - (1 - p)^k, and\nthe fraction of `trials` runs (uniforms from Num.rng(seed)) with a start in that basin.", "marimo": true},
"00_math_toolkit.py:d04_running_mean": {"file": "00_math_toolkit.py", "start": 2375, "end": 2378, "src": "def d04_running_mean(x):\n    \"\"\"Mean of the first N values, for N = 1, 2, ... (slide law-of-large-numbers).\"\"\"\n    x = np.asarray(x, float)\n    return np.cumsum(x) / np.arange(1, len(x) + 1)\n", "doc": "Mean of the first N values, for N = 1, 2, ... (slide law-of-large-numbers).", "marimo": true},
"00_math_toolkit.py:d04_sample_cov": {"file": "00_math_toolkit.py", "start": 2499, "end": 2505, "src": "def d04_sample_cov(points, unbiased=False):\n    \"\"\"Sample mean, covariance (1/N, or 1/(N - 1) when unbiased) and correlation of 2D points.\"\"\"\n    P = np.asarray(points, float)\n    m = P.mean(axis=0)\n    D = P - m\n    S = D.T @ D / (len(P) - 1 if unbiased else len(P))\n    return {\"mean\": m.tolist(), \"cov\": S.tolist(), \"corr\": float(S[0, 1] / _math.sqrt(S[0, 0] * S[1, 1]))}\n", "doc": "Sample mean, covariance (1/N, or 1/(N - 1) when unbiased) and correlation of 2D points.", "marimo": true},
"00_math_toolkit.py:d04_sample_stats": {"file": "00_math_toolkit.py", "start": 2368, "end": 2373, "src": "def d04_sample_stats(x):\n    \"\"\"Sample mean, variance with 1/N, and variance with 1/(N - 1) (slide histograms).\"\"\"\n    x = np.asarray(x, float)\n    n, m = len(x), float(x.mean())\n    ss = float(((x - m) ** 2).sum())\n    return {\"n\": n, \"mean\": m, \"var\": ss / n, \"var_unbiased\": ss / (n - 1) if n > 1 else float(\"nan\")}\n", "doc": "Sample mean, variance with 1/N, and variance with 1/(N - 1) (slide histograms).", "marimo": true},
"00_math_toolkit.py:d04_smoothed_step": {"file": "00_math_toolkit.py", "start": 2600, "end": 2602, "src": "def d04_smoothed_step(z, sigma):\n    \"\"\"E[J(z + sigma eps)] for the step J(y) = 1 if y < 0 else 0, which is Phi(-z / sigma).\"\"\"\n    return d04_normal_cdf(-z / sigma)\n", "doc": "E[J(z + sigma eps)] for the step J(y) = 1 if y < 0 else 0, which is Phi(-z / sigma).", "marimo": true},
"00_math_toolkit.py:d04_smoothed_step_mc": {"file": "00_math_toolkit.py", "start": 2604, "end": 2607, "src": "def d04_smoothed_step_mc(zs, sigma, n, seed):\n    \"\"\"Monte Carlo estimate of the smoothed step at each z, with the same n normals at every z.\"\"\"\n    e = D04Rng(seed).normals(n)\n    return [float(np.mean(z + sigma * e < 0)) for z in zs]\n", "doc": "Monte Carlo estimate of the smoothed step at each z, with the same n normals at every z.", "marimo": true},
"00_math_toolkit.py:d04_softmax_weights": {"file": "00_math_toolkit.py", "start": 2691, "end": 2699, "src": "def d04_softmax_weights(J, lam):\n    \"\"\"w_i = exp(-(J_i - min J) / lam) / sum_j exp(-(J_j - min J) / lam).\n\n    Subtracting min J multiplies every exp(-J_i / lam) by the same factor, so the weights do\n    not change, and the largest term is exp(0) = 1, so the sum cannot underflow to 0.\n    \"\"\"\n    J = np.asarray(J, float)\n    e = np.exp(-(J - J.min()) / lam)\n    return e / e.sum()\n", "doc": "w_i = exp(-(J_i - min J) / lam) / sum_j exp(-(J_j - min J) / lam).\n\nSubtracting min J multiplies every exp(-J_i / lam) by the same factor, so the weights do\nnot change, and the largest term is exp(0) = 1, so the sum cannot underflow to 0.", "marimo": true},
"00_math_toolkit.py:d04_tail_estimates": {"file": "00_math_toolkit.py", "start": 2717, "end": 2728, "src": "def d04_tail_estimates(n, seed, shift=3.0, t=3.0):\n    \"\"\"P(X > t), X ~ N(0, 1): plain Monte Carlo, and importance sampling from q = N(shift, 1).\n\n    Both use Num.rng(seed): the first n normals are the plain draws, the next n (plus shift)\n    the draws from q. The importance weight is p(y)/q(y) = exp(-y^2/2 + (y - shift)^2/2).\n    \"\"\"\n    e = D04Rng(seed).normals(2 * n)\n    x, y = e[:n], shift + e[n:]\n    w = np.exp(-0.5 * y**2 + 0.5 * (y - shift) ** 2)\n    return {\"plain\": float(np.mean(x > t)), \"hits_plain\": int((x > t).sum()),\n            \"is\": float(np.mean((y > t) * w)), \"hits_is\": int((y > t).sum()),\n            \"exact\": 1.0 - d04_normal_cdf(t)}\n", "doc": "P(X > t), X ~ N(0, 1): plain Monte Carlo, and importance sampling from q = N(shift, 1).\n\nBoth use Num.rng(seed): the first n normals are the plain draws, the next n (plus shift)\nthe draws from q. The importance weight is p(y)/q(y) = exp(-y^2/2 + (y - shift)^2/2).", "marimo": true},
"00_math_toolkit.py:d04_tail_relative_std": {"file": "00_math_toolkit.py", "start": 2730, "end": 2740, "src": "def d04_tail_relative_std(n, shift=3.0, t=3.0):\n    \"\"\"Standard deviation / p of both estimators of p = P(X > t), from their exact variances.\n\n    Plain: p (1 - p) / n. Importance: (E_q[1(y > t) w^2] - p^2) / n with\n    E_q[1(y > t) w^2] = exp(shift^2) P(Z > t + shift).\n    \"\"\"\n    p = 1.0 - d04_normal_cdf(t)\n    m2 = _math.exp(shift * shift) * (1.0 - d04_normal_cdf(t + shift))\n    plain = _math.sqrt(p * (1 - p) / n) / p\n    imp = _math.sqrt((m2 - p * p) / n) / p\n    return {\"p\": p, \"plain\": plain, \"is\": imp, \"ratio_n\": (plain / imp) ** 2}\n", "doc": "Standard deviation / p of both estimators of p = P(X > t), from their exact variances.\n\nPlain: p (1 - p) / n. Importance: (E_q[1(y > t) w^2] - p^2) / n with\nE_q[1(y > t) w^2] = exp(shift^2) P(Z > t + shift).", "marimo": true},
"00_math_toolkit.py:d04_two_dice_counts": {"file": "00_math_toolkit.py", "start": 2336, "end": 2342, "src": "def d04_two_dice_counts():\n    \"\"\"How many of the 36 ordered outcomes (a, b) of two dice give each sum 2..12.\"\"\"\n    c = {s: 0 for s in range(2, 13)}\n    for a in range(1, 7):\n        for b in range(1, 7):\n            c[a + b] += 1\n    return c\n", "doc": "How many of the 36 ordered outcomes (a, b) of two dice give each sum 2..12.", "marimo": true},
"00_math_toolkit.py:d04_uniform_moments": {"file": "00_math_toolkit.py", "start": 2431, "end": 2434, "src": "def d04_uniform_moments(a, b):\n    \"\"\"Height 1/(b - a), mean (a + b)/2, variance (b - a)^2/12 and sd of U[a, b].\"\"\"\n    return {\"height\": 1.0 / (b - a), \"mean\": (a + b) / 2, \"var\": (b - a) ** 2 / 12,\n            \"std\": (b - a) / _math.sqrt(12)}\n", "doc": "Height 1/(b - a), mean (a + b)/2, variance (b - a)^2/12 and sd of U[a, b].", "marimo": true},
"00_math_toolkit.py:d04_uniform_stream": {"file": "00_math_toolkit.py", "start": 2294, "end": 2296, "src": "def d04_uniform_stream(seed, n):\n    \"\"\"The first n uniforms of Num.rng(seed) (slide pseudo-random-generators).\"\"\"\n    return D04Rng(seed).uniforms(n)\n", "doc": "The first n uniforms of Num.rng(seed) (slide pseudo-random-generators).", "marimo": true},
"00_math_toolkit.py:d04_weighted_mean": {"file": "00_math_toolkit.py", "start": 2686, "end": 2689, "src": "def d04_weighted_mean(x, w):\n    \"\"\"sum w_i x_i / sum w_i (slide weighted-average).\"\"\"\n    x, w = np.asarray(x, float), np.asarray(w, float)\n    return float(w @ x / w.sum())\n", "doc": "sum w_i x_i / sum w_i (slide weighted-average).", "marimo": true},
"01_optimization_fundamentals.py:J": {"file": "01_optimization_fundamentals.py", "start": 57, "end": 58, "src": "def J(z):\n    return z**4 - 4 * z**2 + z + 4\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:armijo_accepts": {"file": "01_optimization_fundamentals.py", "start": 172, "end": 173, "src": "def armijo_accepts(z, d, alpha, c1=1e-4):\n    return J(z + alpha * d) <= J(z) + c1 * alpha * dJ(z) * d\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:barrier_z": {"file": "01_optimization_fundamentals.py", "start": 226, "end": 227, "src": "def barrier_z(t):  # min z1\u00b2+z2\u00b2 - (1/t)ln(z1+z2-1), symmetric z\n    return 0.25 * (1 + np.sqrt(1 + 4 / t))\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:d2J": {"file": "01_optimization_fundamentals.py", "start": 63, "end": 64, "src": "def d2J(z):\n    return 12 * z**2 - 8\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:dJ": {"file": "01_optimization_fundamentals.py", "start": 60, "end": 61, "src": "def dJ(z):\n    return 4 * z**3 - 8 * z + 1\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:penalty_z": {"file": "01_optimization_fundamentals.py", "start": 223, "end": 224, "src": "def penalty_z(rho):  # min z1\u00b2+z2\u00b2 + (\u03c1/2)max(1-z1-z2,0)\u00b2, symmetric z\n    return rho / (2 + 2 * rho)\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:run_gradient_descent": {"file": "01_optimization_fundamentals.py", "start": 97, "end": 103, "src": "def run_gradient_descent(z0=2.0, alpha=0.05, iters=12):\n    rows, z = [], z0\n    for k in range(iters):\n        g = dJ(z)\n        rows.append((k, z, g))\n        z = z - alpha * g\n    return rows\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:run_newton": {"file": "01_optimization_fundamentals.py", "start": 105, "end": 111, "src": "def run_newton(z0=2.0, iters=6):\n    rows, z = [], z0\n    for k in range(iters):\n        g, H = dJ(z), d2J(z)\n        rows.append((k, z, g, H))\n        z = z - g / H\n    return rows\n", "doc": "", "marimo": true},
"01_optimization_fundamentals.py:solve_lcp_enumeration": {"file": "01_optimization_fundamentals.py", "start": 289, "end": 303, "src": "def solve_lcp_enumeration(G, g, tol=1e-12):\n    \"\"\"Brute-force LCP solver: try all 2^n active sets.\"\"\"\n    n = len(g)\n    results = []\n    for mask in range(2**n):\n        active = [bool(mask >> i & 1) for i in range(n)]  # active: \u03bb_i free, w_i=0\n        lam = np.zeros(n)\n        idx = [i for i in range(n) if active[i]]\n        if idx:\n            Gaa = G[np.ix_(idx, idx)]\n            lam[idx] = np.linalg.solve(Gaa, -g[idx])\n        w = G @ lam + g\n        ok = np.all(lam >= -tol) and np.all(w >= -tol) and abs(lam @ w) < 1e-9\n        results.append((active, lam.copy(), w.copy(), ok))\n    return results\n", "doc": "Brute-force LCP solver: try all 2^n active sets.", "marimo": true},
"02_lqr_ilqr_sliding_block.py:ilqr_block": {"file": "02_lqr_ilqr_sliding_block.py", "start": 194, "end": 250, "src": "def ilqr_block(T=3, h=1.0 / 3.0, w=100.0, iters=5, x_goal=None, verbose_t=2):\n    if x_goal is None:\n        x_goal = np.array([1.0, 0.0])\n    A = np.array([[1.0, h], [0.0, 1.0]])\n    B = np.array([[0.0], [h]])\n\n    def rollout(x0, us, ks=None, Ks=None, xs_nom=None, alpha=1.0):\n        xs = [x0.copy()]\n        us_new = []\n        for t in range(T):\n            u = us[t].copy()\n            if ks is not None:\n                u = us[t] + alpha * ks[t] + Ks[t] @ (xs[-1] - xs_nom[t])\n            us_new.append(u)\n            xs.append(A @ xs[-1] + (B * u).flatten())\n        return xs, us_new\n\n    def total_cost(xs, us):\n        return sum(float(np.sum(u**2)) for u in us) + w * float(\n            (xs[-1] - x_goal) @ (xs[-1] - x_goal)\n        )\n\n    x0 = np.zeros(2)\n    us = [np.zeros(1) for _ in range(T)]\n    xs, us = rollout(x0, us)\n    history = [total_cost(xs, us)]\n    debug = {}\n\n    for it in range(iters):\n        # backward pass\n        Vx = 2 * w * (xs[-1] - x_goal)\n        Vxx = 2 * w * np.eye(2)\n        ks, Ks = [None] * T, [None] * T\n        for t in reversed(range(T)):\n            Qx = A.T @ Vx\n            Qu = 2 * us[t] + B.T @ Vx\n            Qxx = A.T @ Vxx @ A\n            Quu = 2 * np.eye(1) + B.T @ Vxx @ B\n            Qux = B.T @ Vxx @ A\n            k = -np.linalg.solve(Quu, Qu)\n            K = -np.linalg.solve(Quu, Qux)\n            if it == 0 and t == verbose_t:\n                debug = dict(Qu=Qu.copy(), Quu=Quu.copy(), Qux=Qux.copy(),\n                             k=k.copy(), K=K.copy())\n            Vx = Qx + K.T @ Quu @ k + K.T @ Qu + Qux.T @ k\n            Vxx = Qxx + K.T @ Quu @ K + K.T @ Qux + Qux.T @ K\n            ks[t], Ks[t] = k, K\n        # forward pass with simple line search\n        best = None\n        for alpha in [1.0, 0.5, 0.25, 0.1]:\n            xs_try, us_try = rollout(x0, us, ks, Ks, xs, alpha)\n            c = total_cost(xs_try, us_try)\n            if best is None or c < best[0]:\n                best = (c, xs_try, us_try)\n        _, xs, us = best\n        history.append(best[0])\n    return xs, us, history, debug\n", "doc": "", "marimo": true},
"02_lqr_ilqr_sliding_block.py:scalar_lqr": {"file": "02_lqr_ilqr_sliding_block.py", "start": 135, "end": 143, "src": "def scalar_lqr(T=3, Qc=1.0, Rc=1.0, Qf=1.0, A=1.0, B=1.0):\n    P = Qf\n    rows = []\n    for t in reversed(range(T)):\n        K = (B * P * A) / (Rc + B * P * B)\n        Pn = Qc + A * P * A - (A * P * B) ** 2 / (Rc + B * P * B)\n        rows.append((t, P, K, Pn))\n        P = Pn\n    return rows[::-1], P  # chronological, P_0\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:_final_state": {"file": "03_sampling_mpc.py", "start": 245, "end": 252, "src": "def _final_state(theta):\n    import numpy as _np\n    A = _np.array([[1.0, 0.05], [0.0, 1.0]])\n    B = _np.array([0.0, 0.05])\n    x = _np.zeros(2)\n    for u in knots_to_controls(theta):\n        x = A @ x + B * u\n    return x\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:effective_sample_size": {"file": "03_sampling_mpc.py", "start": 68, "end": 69, "src": "def effective_sample_size(w):\n    return 1.0 / np.sum(w**2)\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:knots_to_controls": {"file": "03_sampling_mpc.py", "start": 155, "end": 158, "src": "def knots_to_controls(theta):\n    \"\"\"Zero-order hold: each knot held for T/P steps.\"\"\"\n    reps = T_task // P_knots\n    return np.repeat(theta, reps)\n", "doc": "Zero-order hold: each knot held for T/P steps.", "marimo": true},
"03_sampling_mpc.py:mppi_weights": {"file": "03_sampling_mpc.py", "start": 63, "end": 66, "src": "def mppi_weights(J, lam):\n    J = np.asarray(J, dtype=float)\n    w = np.exp(-(J - J.min()) / lam)\n    return w / w.sum()\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:rollout_cost": {"file": "03_sampling_mpc.py", "start": 160, "end": 168, "src": "def rollout_cost(theta, w=100.0, ctrl_weight=0.05):\n    u = knots_to_controls(theta)\n    x = np.zeros(2)\n    c = 0.0\n    for t in range(T_task):\n        c += ctrl_weight * u[t] ** 2\n        x = A_t @ x + B_t * u[t]\n    c += w * float((x - x_goal_t) @ (x - x_goal_t))\n    return c\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:run_cem": {"file": "03_sampling_mpc.py", "start": 204, "end": 218, "src": "def run_cem(iters=30, N=32, elite_frac=0.25, sigma0=1.0,\n            sigma_floor=0.05, seed=0):\n    rng = np.random.default_rng(seed)\n    mu = np.zeros(P_knots)\n    sigma = sigma0 * np.ones(P_knots)\n    hist = [rollout_cost(mu)]\n    n_elite = max(2, int(elite_frac * N))\n    for _ in range(iters):\n        cands = mu + sigma * rng.standard_normal((N, P_knots))\n        costs = np.array([rollout_cost(c) for c in cands])\n        elites = cands[np.argsort(costs)[:n_elite]]\n        mu = elites.mean(axis=0)\n        sigma = np.maximum(elites.std(axis=0), sigma_floor)\n        hist.append(rollout_cost(mu))\n    return mu, hist\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:run_mppi": {"file": "03_sampling_mpc.py", "start": 190, "end": 202, "src": "def run_mppi(iters=30, N=32, sigma=1.0, lam=2.0, seed=0):\n    rng = np.random.default_rng(seed)\n    theta = np.zeros(P_knots)\n    hist = [rollout_cost(theta)]\n    for _ in range(iters):\n        eps = sigma * rng.standard_normal((N, P_knots))\n        cands = theta + eps\n        costs = np.array([rollout_cost(c) for c in cands])\n        w = np.exp(-(costs - costs.min()) / lam)\n        w /= w.sum()\n        theta = theta + (w[:, None] * eps).sum(axis=0)\n        hist.append(rollout_cost(theta))\n    return theta, hist\n", "doc": "", "marimo": true},
"03_sampling_mpc.py:run_predictive_sampling": {"file": "03_sampling_mpc.py", "start": 178, "end": 188, "src": "def run_predictive_sampling(iters=30, N=32, sigma=1.0, seed=0):\n    rng = np.random.default_rng(seed)\n    theta = np.zeros(P_knots)\n    hist = [rollout_cost(theta)]\n    for _ in range(iters):\n        cands = theta + sigma * rng.standard_normal((N, P_knots))\n        cands = np.vstack([theta, cands])  # always keep the nominal\n        costs = np.array([rollout_cost(c) for c in cands])\n        theta = cands[np.argmin(costs)]\n        hist.append(costs.min())\n    return theta, hist\n", "doc": "", "marimo": true},
"04_friction_cones.py:friction_angle": {"file": "04_friction_cones.py", "start": 135, "end": 136, "src": "def friction_angle(mu):\n    return np.degrees(np.arctan(mu))\n", "doc": "", "marimo": true},
"04_friction_cones.py:friction_models": {"file": "04_friction_cones.py", "start": 381, "end": 388, "src": "def friction_models(mu):\n    return {\n        \"circle\": dict(kind=\"circle\", mu=mu),\n        \"diamond\": dict(kind=\"poly\", verts=regular_polygon(4, \"inscribed\", mu)),\n        \"box\": dict(kind=\"poly\", verts=regular_polygon(4, \"circumscribed\", mu)),\n        \"octagon\": dict(kind=\"poly\", verts=regular_polygon(8, \"inscribed\", mu)),\n        \"ellipse\": dict(kind=\"ellipse\", mu=mu, mu2=mu / 3),\n    }\n", "doc": "", "marimo": true},
"04_friction_cones.py:in_floor_cone": {"file": "04_friction_cones.py", "start": 495, "end": 498, "src": "def in_floor_cone(P, h, w, mu, mg=1.0):\n    E = np.array([[s * mu, 1.0, t * w / 2] for s in (1, -1) for t in (1, -1)]).T\n    _, res = nnls(E, np.array([-P, mg, h * P]))\n    return res < 1e-9\n", "doc": "", "marimo": true},
"04_friction_cones.py:mdp_brute": {"file": "04_friction_cones.py", "start": 224, "end": 225, "src": "def mdp_brute(boundary, v):\n    return boundary[np.argmin(boundary @ np.asarray(v, float))]\n", "doc": "", "marimo": true},
"04_friction_cones.py:mdp_ellipse": {"file": "04_friction_cones.py", "start": 219, "end": 222, "src": "def mdp_ellipse(v, a, b):\n    v = np.asarray(v, float)\n    num = np.array([a * a * v[0], b * b * v[1]])\n    return -num / np.hypot(a * v[0], b * v[1])\n", "doc": "", "marimo": true},
"04_friction_cones.py:project_slice": {"file": "04_friction_cones.py", "start": 337, "end": 367, "src": "def project_slice(model, z, scale):\n    \"\"\"Closest point to z in scale * slice.\"\"\"\n    z = np.asarray(z, float)\n    if model[\"kind\"] == \"circle\":\n        r, n = model[\"mu\"] * scale, np.linalg.norm(z)\n        return z if n <= r else z * (r / n)\n    if model[\"kind\"] == \"ellipse\":\n        a, b = model[\"mu\"] * scale, model[\"mu2\"] * scale\n        if (z[0] / a) ** 2 + (z[1] / b) ** 2 <= 1:\n            return z\n        g = lambda t: (a * z[0] / (a * a + t)) ** 2 + (b * z[1] / (b * b + t)) ** 2 - 1\n        lo, hi = 0.0, 1.0\n        while g(hi) > 0:\n            hi *= 2\n        for _ in range(80):\n            mid = 0.5 * (lo + hi)\n            lo, hi = (mid, hi) if g(mid) > 0 else (lo, mid)\n        return np.array([a * a * z[0] / (a * a + hi), b * b * z[1] / (b * b + hi)])\n    P = model[\"verts\"] * scale\n    cross = lambda a, b: a[0] * b[1] - a[1] * b[0]\n    inside = all(cross(P[(i + 1) % len(P)] - P[i], z - P[i]) >= 0 for i in range(len(P)))\n    if inside:\n        return z\n    best, bd = None, np.inf\n    for i in range(len(P)):\n        a, e = P[i], P[(i + 1) % len(P)] - P[i]\n        t = np.clip((z - a) @ e / (e @ e), 0, 1)\n        q = a + t * e\n        if np.linalg.norm(z - q) < bd:\n            best, bd = q, np.linalg.norm(z - q)\n    return best\n", "doc": "Closest point to z in scale * slice.", "marimo": true},
"04_friction_cones.py:push_box": {"file": "04_friction_cones.py", "start": 72, "end": 79, "src": "def push_box(P, m=10.0, mu_s=0.5, mu_k=0.4, g=G, down_deg=0.0):\n    \"\"\"A push of P newtons aimed down_deg below horizontal on a resting box.\"\"\"\n    side, press = P * np.cos(np.radians(down_deg)), P * np.sin(np.radians(down_deg))\n    N = m * g + press\n    if side <= mu_s * N:\n        return dict(N=N, side=side, budget=mu_s * N, friction=side, accel=0.0, mode=\"sticks\")\n    F = mu_k * N\n    return dict(N=N, side=side, budget=mu_s * N, friction=F, accel=(side - F) / m, mode=\"slides\")\n", "doc": "A push of P newtons aimed down_deg below horizontal on a resting box.", "marimo": true},
"04_friction_cones.py:reach": {"file": "04_friction_cones.py", "start": 269, "end": 278, "src": "def reach(verts, U):\n    \"\"\"How far a convex polygon (CCW verts, containing 0) extends along each unit row of U.\"\"\"\n    e = np.roll(verts, -1, axis=0) - verts\n    n = np.stack([e[:, 1], -e[:, 0]], 1) / np.linalg.norm(e, axis=1, keepdims=True)\n    h = np.sum(n * verts, 1)                          # side i: n_i . x <= h_i\n    nu = np.atleast_2d(U) @ n.T\n    with np.errstate(divide=\"ignore\"):\n        t = np.where(nu > 1e-12, h / nu, np.inf)\n    out = t.min(axis=1)\n    return out if np.ndim(U) == 2 else out[0]\n", "doc": "How far a convex polygon (CCW verts, containing 0) extends along each unit row of U.", "marimo": true},
"04_friction_cones.py:regular_polygon": {"file": "04_friction_cones.py", "start": 263, "end": 267, "src": "def regular_polygon(k, how=\"inscribed\", mu=1.0, phase=None):\n    r = mu if how == \"inscribed\" else mu / np.cos(np.pi / k)\n    ph = (0.0 if how == \"inscribed\" else np.pi / k) if phase is None else phase\n    a = ph + 2 * np.pi * np.arange(k) / k\n    return r * np.stack([np.cos(a), np.sin(a)], 1)\n", "doc": "", "marimo": true},
"04_friction_cones.py:slide_or_tip": {"file": "04_friction_cones.py", "start": 489, "end": 493, "src": "def slide_or_tip(P, h, w, mu, mg=1.0):\n    NA, NB = mg / 2 - P * h / w, mg / 2 + P * h / w\n    P_slide, P_tip = mu * mg, mg * w / (2 * h)\n    return dict(NA=NA, NB=NB, P_slide=P_slide, P_tip=P_tip,\n                first=\"tips\" if P_tip < P_slide else \"slides\")\n", "doc": "", "marimo": true},
"04_friction_cones.py:slide_puck": {"file": "04_friction_cones.py", "start": 369, "end": 379, "src": "def slide_puck(model, v0, g=9.81, h=0.002, tmax=10.0):\n    x, v = np.zeros(2), np.asarray(v0, float)\n    path = [x.copy()]\n    for _ in range(int(tmax / h)):\n        f = project_slice(model, -v / h, g)       # friction per unit mass\n        v = v + h * f\n        x = x + h * v\n        path.append(x.copy())\n        if np.linalg.norm(v) < 1e-9:\n            break\n    return np.array(path)\n", "doc": "", "marimo": true},
"04_friction_cones.py:slip_angle_scan": {"file": "04_friction_cones.py", "start": 138, "end": 142, "src": "def slip_angle_scan(mu, m=1.0, g=9.81, step=1e-3):\n    \"\"\"Smallest tilt (deg) where gravity along the board beats the friction budget.\"\"\"\n    th = np.radians(np.arange(0.0, 90.0, step))\n    along, budget = m * g * np.sin(th), mu * m * g * np.cos(th)\n    return np.degrees(th[np.argmax(along > budget)])\n", "doc": "Smallest tilt (deg) where gravity along the board beats the friction budget.", "marimo": true},
"05_contact_solvers.py:ball_floor_lcp": {"file": "05_contact_solvers.py", "start": 65, "end": 74, "src": "def ball_floor_lcp(v, m=1.0, g=10.0, h=0.01):\n    \"\"\"Returns (impulse, post-velocity) for one normal contact.\"\"\"\n    G = 1.0 / m\n    vf = v - h * g\n    # mode 1: separated (lambda = 0): need vf >= 0\n    if vf >= 0:\n        return 0.0, vf\n    # mode 2: active (post-velocity = 0): lambda = -vf / G\n    lam = -vf / G\n    return lam, 0.0\n", "doc": "Returns (impulse, post-velocity) for one normal contact.", "marimo": true},
"05_contact_solvers.py:box_drop_viewer": {"file": "05_contact_solvers.py", "start": 322, "end": 336, "src": "def box_drop_viewer(seconds=3.0):\n    \"\"\"mjview.show on models/box_on_plane.xml, then `seconds` of the drop in the background.\"\"\"\n    from pathlib import Path\n\n    try:\n        import mujoco\n    except ImportError:\n        return mjview.Unavailable(\"mujoco is not installed (the browser build has none)\", 420)\n    xml = Path(mo.notebook_dir() or \".\") / \"models\" / \"box_on_plane.xml\"\n    model = mujoco.MjModel.from_xml_path(str(xml))\n    data = mujoco.MjData(model)\n    mujoco.mj_forward(model, data)\n    view = mjview.show(model, data, height=420, key=\"deck18-box-drop\")\n    view.run(seconds=seconds)\n    return view\n", "doc": "mjview.show on models/box_on_plane.xml, then `seconds` of the drop in the background.", "marimo": true},
"05_contact_solvers.py:pgs": {"file": "05_contact_solvers.py", "start": 107, "end": 116, "src": "def pgs(G, g, iters=50, lam0=None):\n    n = len(g)\n    lam = np.zeros(n) if lam0 is None else lam0.copy()\n    trace = [lam.copy()]\n    for _ in range(iters):\n        for i in range(n):\n            w_i = G[i] @ lam + g[i]\n            lam[i] = max(0.0, lam[i] - w_i / G[i, i])\n        trace.append(lam.copy())\n    return lam, np.array(trace)\n", "doc": "", "marimo": true},
"05_contact_solvers.py:project_soc": {"file": "05_contact_solvers.py", "start": 156, "end": 165, "src": "def project_soc(lam_n, lam_t, mu):\n    \"\"\"Project (lam_n, lam_t in R^k) onto the cone ||lam_t|| <= mu*lam_n.\"\"\"\n    lam_t = np.atleast_1d(np.asarray(lam_t, dtype=float))\n    s = np.linalg.norm(lam_t)\n    if s <= mu * lam_n:                      # inside: keep (stick)\n        return lam_n, lam_t, \"stick (inside cone)\"\n    if mu * s <= -lam_n:                     # in polar cone: zero (separate)\n        return 0.0, np.zeros_like(lam_t), \"separate (project to tip)\"\n    coef = (lam_n + mu * s) / (1 + mu**2)    # surface: radial shrink (slip)\n    return coef, coef * mu * lam_t / s, \"slip (project to surface)\"\n", "doc": "Project (lam_n, lam_t in R^k) onto the cone ||lam_t|| <= mu*lam_n.", "marimo": true},
"05_contact_solvers.py:simulate_sliding_cube": {"file": "05_contact_solvers.py", "start": 195, "end": 205, "src": "def simulate_sliding_cube(v0=2.0, m=0.01, mu=0.5, g=9.8, h=0.002, t_end=0.6):\n    ts, vs = [0.0], [v0]\n    v = v0\n    steps = int(t_end / h)\n    for k in range(steps):\n        lam_n = m * g * h                       # normal impulse (resting contact)\n        lam_t_stick = m * abs(v)                # impulse that would stop slip\n        lam_t = min(lam_t_stick, mu * lam_n)    # Coulomb budget\n        v = v - np.sign(v) * lam_t / m\n        ts.append((k + 1) * h); vs.append(v)\n    return np.array(ts), np.array(vs)\n", "doc": "", "marimo": true},
"06_force_closure.py:_sphere_pinch": {"file": "06_force_closure.py", "start": 355, "end": 357, "src": "def _sphere_pinch(delta, mu, soft):\n    p2 = np.array([-np.cos(delta), np.sin(delta), 0.0])\n    return positively_spans(wrenches_3d([([1.0, 0, 0], [-1, 0, 0]), (p2, -p2)], mu, soft=soft))\n", "doc": "", "marimo": true},
"06_force_closure.py:ball_fc": {"file": "06_force_closure.py", "start": 399, "end": 400, "src": "def ball_fc(phi, mu, **kw):\n    return positively_spans(wrenches_3d(ring_contacts(phi), mu, **kw))\n", "doc": "", "marimo": true},
"06_force_closure.py:bisect": {"file": "06_force_closure.py", "start": 251, "end": 256, "src": "def bisect(pred, lo, hi, iters=50):\n    \"\"\"Largest x in [lo, hi] with pred(x) True, assuming pred flips once.\"\"\"\n    for _ in range(iters):\n        mid = 0.5 * (lo + hi)\n        lo, hi = (mid, hi) if pred(mid) else (lo, mid)\n    return lo\n", "doc": "Largest x in [lo, hi] with pred(x) True, assuming pred flips once.", "marimo": true},
"06_force_closure.py:box_fc": {"file": "06_force_closure.py", "start": 258, "end": 260, "src": "def box_fc(d, mu, w=6.0):\n    c = [(np.array([-w / 2, -d / 2]), [1, 0]), (np.array([w / 2, d / 2]), [-1, 0])]\n    return positively_spans(edge_wrenches_2d(c, mu))\n", "doc": "", "marimo": true},
"06_force_closure.py:cone_edges_3d": {"file": "06_force_closure.py", "start": 325, "end": 330, "src": "def cone_edges_3d(n, mu, k=64, how=\"inscribed\", phase=0.0):\n    n, t1, t2 = contact_frame(n)\n    r = mu if how == \"inscribed\" else mu / np.cos(np.pi / k)\n    ph = phase if how == \"inscribed\" else phase + np.pi / k\n    th = ph + 2 * np.pi * np.arange(k) / k\n    return [n + r * (np.cos(a) * t1 + np.sin(a) * t2) for a in th]\n", "doc": "", "marimo": true},
"06_force_closure.py:contact_frame": {"file": "06_force_closure.py", "start": 316, "end": 323, "src": "def contact_frame(n, up=(0.0, 0.0, 1.0)):\n    \"\"\"Inward normal n, t1 = the 'up' direction projected onto the tangent plane, t2 = n x t1.\"\"\"\n    n = np.asarray(n, float) / np.linalg.norm(n)\n    t1 = np.asarray(up, float) - (np.asarray(up, float) @ n) * n\n    if np.linalg.norm(t1) < 1e-9:\n        t1 = np.array([1.0, 0, 0]) - n[0] * n\n    t1 /= np.linalg.norm(t1)\n    return n, t1, np.cross(n, t1)\n", "doc": "Inward normal n, t1 = the 'up' direction projected onto the tangent plane, t2 = n x t1.", "marimo": true},
"06_force_closure.py:cross2": {"file": "06_force_closure.py", "start": 79, "end": 80, "src": "def cross2(a, b):\n    return a[0] * b[1] - a[1] * b[0]\n", "doc": "", "marimo": true},
"06_force_closure.py:disk_fc": {"file": "06_force_closure.py", "start": 262, "end": 264, "src": "def disk_fc(delta, mu):\n    p1, p2 = np.array([-1.0, 0.0]), np.array([np.cos(delta), np.sin(delta)])\n    return positively_spans(edge_wrenches_2d([(p1, -p1), (p2, -p2)], mu))\n", "doc": "", "marimo": true},
"06_force_closure.py:edge_wrenches_2d": {"file": "06_force_closure.py", "start": 90, "end": 100, "src": "def edge_wrenches_2d(contacts, mu, lam=1.0):\n    \"\"\"Planar primitive wrenches (f_x, f_y, tau/lam), 2 per frictional contact.\n    contacts: list of (point, inward normal). Each edge has unit normal part.\"\"\"\n    cols = []\n    a = np.arctan(mu)\n    for p, n in contacts:\n        n = unit(n)\n        for s in (-a, a):\n            f = rot(n, s) / np.cos(a)\n            cols.append([f[0], f[1], cross2(p, f) / lam])\n    return np.array(cols).T\n", "doc": "Planar primitive wrenches (f_x, f_y, tau/lam), 2 per frictional contact.\ncontacts: list of (point, inward normal). Each edge has unit normal part.", "marimo": true},
"06_force_closure.py:ellipse_point": {"file": "06_force_closure.py", "start": 175, "end": 178, "src": "def ellipse_point(a, b, t):\n    p = np.array([a * np.cos(t), b * np.sin(t)])\n    n_out = unit([b * np.cos(t), a * np.sin(t)])\n    return p, -n_out\n", "doc": "", "marimo": true},
"06_force_closure.py:epsilon_l1": {"file": "06_force_closure.py", "start": 578, "end": 584, "src": "def epsilon_l1(W):\n    \"\"\"Ferrari-Canny epsilon (L1 version) for primitive wrenches in the columns of W.\"\"\"\n    try:\n        hull = ConvexHull(np.asarray(W, float).T)\n    except Exception:\n        return 0.0                                   # flat hull: origin can't be strictly inside\n    return max(0.0, float(-hull.equations[:, -1].max()))\n", "doc": "Ferrari-Canny epsilon (L1 version) for primitive wrenches in the columns of W.", "marimo": true},
"06_force_closure.py:equilateral": {"file": "06_force_closure.py", "start": 536, "end": 546, "src": "def equilateral(so, e):\n    h = so * np.sqrt(3) / 2\n    V = [np.array([-so / 2, -h / 3]), np.array([so / 2, -h / 3]), np.array([0.0, 2 * h / 3])]\n    P, N = [], []\n    for i in range(3):\n        A, B = V[i], V[(i + 1) % 3]\n        u = (B - A) / np.linalg.norm(B - A)\n        P.append((A + B) / 2 + e * u); N.append(np.array([-u[1], u[0]]))\n    meet = lambda p, a, q, b: p + cross2(q - p, b) / cross2(a, b) * a\n    I = [meet(P[i], N[i], P[(i + 1) % 3], N[(i + 1) % 3]) for i in range(3)]\n    return P, N, np.linalg.norm(I[0] - I[1])\n", "doc": "", "marimo": true},
"06_force_closure.py:frictionless_wrenches_2d": {"file": "06_force_closure.py", "start": 102, "end": 103, "src": "def frictionless_wrenches_2d(contacts, lam=1.0):\n    return np.array([[*unit(n), cross2(p, unit(n)) / lam] for p, n in contacts]).T\n", "doc": "", "marimo": true},
"06_force_closure.py:max_twist_2d": {"file": "06_force_closure.py", "start": 511, "end": 529, "src": "def max_twist_2d(P, N, mu, sign, total=None, each=None):\n    \"\"\"Largest pure moment (sign * tau) the contacts can make with zero net force.\n    Variables: normal c_i and tangential s_i per contact.\"\"\"\n    k = len(P)\n    T = [np.array([-n[1], n[0]]) for n in N]\n    Aeq = np.zeros((2, 2 * k)); obj = np.zeros(2 * k)\n    for i in range(k):\n        Aeq[:, i], Aeq[:, k + i] = N[i], T[i]\n        obj[i], obj[k + i] = cross2(P[i], N[i]), cross2(P[i], T[i])\n    Aub, bub = [], []\n    for i in range(k):\n        for s in (1, -1):\n            r = np.zeros(2 * k); r[k + i] = s; r[i] = -mu; Aub.append(r); bub.append(0.0)\n    if total is not None:\n        r = np.zeros(2 * k); r[:k] = 1; Aub.append(r); bub.append(total)\n    ub = each if each is not None else None\n    res = linprog(-sign * obj, A_ub=Aub, b_ub=bub, A_eq=Aeq, b_eq=[0, 0],\n                  bounds=[(0, ub)] * k + [(None, None)] * k, method=\"highs\")\n    return sign * obj @ res.x\n", "doc": "Largest pure moment (sign * tau) the contacts can make with zero net force.\nVariables: normal c_i and tangential s_i per contact.", "marimo": true},
"06_force_closure.py:nguyen": {"file": "06_force_closure.py", "start": 163, "end": 169, "src": "def nguyen(p1, n1, p2, n2, mu):\n    \"\"\"Returns (holds, beta1, beta2) with angles in radians. n1, n2 are inward normals.\"\"\"\n    d = unit(p2 - p1)\n    b1 = np.arccos(np.clip(d @ unit(n1), -1, 1))\n    b2 = np.arccos(np.clip(-d @ unit(n2), -1, 1))\n    a = np.arctan(mu)\n    return (b1 < a) and (b2 < a), b1, b2\n", "doc": "Returns (holds, beta1, beta2) with angles in radians. n1, n2 are inward normals.", "marimo": true},
"06_force_closure.py:normal_angle": {"file": "06_force_closure.py", "start": 171, "end": 173, "src": "def normal_angle(n1, n2):\n    \"\"\"Angle between inward normal 1 and minus inward normal 2 (0 = perfectly opposite).\"\"\"\n    return np.arccos(np.clip(unit(n1) @ -unit(n2), -1, 1))\n", "doc": "Angle between inward normal 1 and minus inward normal 2 (0 = perfectly opposite).", "marimo": true},
"06_force_closure.py:polygon_point": {"file": "06_force_closure.py", "start": 184, "end": 193, "src": "def polygon_point(verts, s):\n    \"\"\"Point at arc-length fraction s in [0,1) and its inward normal.\"\"\"\n    e = np.roll(verts, -1, axis=0) - verts\n    L = np.linalg.norm(e, axis=1)\n    d = (s % 1.0) * L.sum()\n    i = int(np.searchsorted(np.cumsum(L), d))\n    i = min(i, len(verts) - 1)\n    d0 = d - (np.cumsum(L)[i] - L[i])\n    u = e[i] / L[i]\n    return verts[i] + u * d0, np.array([-u[1], u[0]])  # CCW: inward = left normal\n", "doc": "Point at arc-length fraction s in [0,1) and its inward normal.", "marimo": true},
"06_force_closure.py:positively_spans": {"file": "06_force_closure.py", "start": 70, "end": 77, "src": "def positively_spans(W):\n    \"\"\"W: one vector per column. True iff the columns positively span R^d.\"\"\"\n    W = np.asarray(W, float)\n    d, m = W.shape\n    if np.linalg.matrix_rank(W, tol=1e-9) < d:\n        return False\n    res = linprog(np.zeros(m), A_eq=W, b_eq=np.zeros(d), bounds=[(1, None)] * m, method=\"highs\")\n    return res.status == 0\n", "doc": "W: one vector per column. True iff the columns positively span R^d.", "marimo": true},
"06_force_closure.py:random_polygon": {"file": "06_force_closure.py", "start": 180, "end": 182, "src": "def random_polygon(rng, n=7):\n    pts = rng.normal(size=(n, 2))\n    return pts[ConvexHull(pts).vertices]                # CCW\n", "doc": "", "marimo": true},
"06_force_closure.py:ring_contacts": {"file": "06_force_closure.py", "start": 392, "end": 397, "src": "def ring_contacts(phi, R=1.0, angles=(0, 120, 240)):\n    out = []\n    for a in np.radians(angles):\n        p = R * np.array([np.cos(phi) * np.cos(a), np.cos(phi) * np.sin(a), np.sin(phi)])\n        out.append((p, -p))\n    return out\n", "doc": "", "marimo": true},
"06_force_closure.py:rot": {"file": "06_force_closure.py", "start": 86, "end": 88, "src": "def rot(v, t):\n    c, s = np.cos(t), np.sin(t)\n    return np.array([c * v[0] - s * v[1], s * v[0] + c * v[1]])\n", "doc": "", "marimo": true},
"06_force_closure.py:unit": {"file": "06_force_closure.py", "start": 82, "end": 84, "src": "def unit(v):\n    v = np.asarray(v, float)\n    return v / np.linalg.norm(v)\n", "doc": "", "marimo": true},
"06_force_closure.py:wedge_fc": {"file": "06_force_closure.py", "start": 266, "end": 269, "src": "def wedge_fc(beta, mu, y=0.0):\n    n1, n2 = np.array([np.cos(beta), -np.sin(beta)]), np.array([-np.cos(beta), -np.sin(beta)])\n    x = 1.0\n    return positively_spans(edge_wrenches_2d([(np.array([-x, y]), n1), (np.array([x, y]), n2)], mu))\n", "doc": "", "marimo": true},
"06_force_closure.py:wrenches_3d": {"file": "06_force_closure.py", "start": 332, "end": 343, "src": "def wrenches_3d(contacts, mu, k=64, soft=None, how=\"inscribed\", phase=0.0, lam=1.0):\n    \"\"\"contacts: list of (point, inward normal). Columns are (f, p x f / lam).\"\"\"\n    cols = []\n    for p, n in contacts:\n        p = np.asarray(p, float)\n        for f in cone_edges_3d(n, mu, k, how, phase):\n            cols.append(np.r_[f, np.cross(p, f) / lam])\n        if soft:\n            nn = np.asarray(n, float) / np.linalg.norm(n)\n            for s in (1, -1):\n                cols.append(np.r_[nn, (np.cross(p, nn) + s * soft * nn) / lam])\n    return np.array(cols).T\n", "doc": "contacts: list of (point, inward normal). Columns are (f, p x f / lam).", "marimo": true},
"07_hybrid_servoing.py:_fmt": {"file": "07_hybrid_servoing.py", "start": 193, "end": 194, "src": "def _fmt(x):\n    return \"(\" + \", \".join(f\"{0.0 if abs(v) < 1e-10 else v:.4g}\" for v in np.atleast_1d(x)) + \")\"\n", "doc": "", "marimo": true},
"07_hybrid_servoing.py:_md": {"file": "07_hybrid_servoing.py", "start": 288, "end": 300, "src": "def _md():\n    lines = [\"| goal | dim | method | solved | crash mean / median | ill (> 100) | velocity ms mean / worst | force ms mean / worst |\",\n             \"|---|---|---|---|---|---|---|---|\"]\n    notes = []\n    for g, res in lab_t2.items():\n        for dim, (rows, _, extra) in res.items():\n            for name, r in rows.items():\n                lines.append(f\"| {g} | {dim}D | {name} | {r['solved']} / {r['total']} | {r['mean_crash']:.3g} / {r['median_crash']:.3g} | \"\n                             f\"{r['ill']} | {r['t_vel_mean']:.2f} / {r['t_vel_worst']:.2f} | \"\n                             f\"{r['t_force_mean']:.2f} / {r['t_force_worst']:.2f} |\")\n            notes.append(f\"* goal `{g}`, {dim}D: OCHS worse than HS3 or HS10 on {extra['ochs_worse']} problems; \"\n                         f\"HS3 failures: {extra['hs3_failures'] or 'none'}.\")\n    return \"\\n\".join(lines) + \"\\n\\n\" + \"\\n\".join(notes)\n", "doc": "", "marimo": true},
"07_hybrid_servoing.py:lab_alg2_vs_qp": {"file": "07_hybrid_servoing.py", "start": 456, "end": 473, "src": "def lab_alg2_vs_qp(count=100, seed=7):\n    \"\"\"On planar random problems: HS3 force-step failures, how many of them the eq. 30 QP\n    solves with the same T, and the contact counts of the failed problems.\"\"\"\n    fails = qp_ok = 0\n    contacts = {}\n    for p in lab_hfvc.random_problems(count, dim=2, seed=seed):\n        s = lab_hfvc.solve_hs(p, 3, rng=0)\n        if s.vel is None or s.ok:\n            continue\n        fails += 1\n        k = len(p.info[\"contacts\"])\n        contacts[k] = contacts.get(k, 0) + 1\n        try:\n            lab_hfvc.ochs_force(p, s.vel)\n            qp_ok += 1\n        except lab_hfvc.Infeasible:\n            pass\n    return dict(problems=count, alg2_failures=fails, qp_solves=qp_ok, contacts=contacts)\n", "doc": "On planar random problems: HS3 force-step failures, how many of them the eq. 30 QP\nsolves with the same T, and the contact counts of the failed problems.", "marimo": true},
"07_hybrid_servoing.py:lab_block_tilt_solution": {"file": "07_hybrid_servoing.py", "start": 172, "end": 186, "src": "def lab_block_tilt_solution(theta_deg=0.0, guards=\"paper\", method=\"ochs\", seed=0):\n    \"\"\"The HFVC of 2019 Sec. V at tilt theta_deg: n_av, n_af, crashing index, R_a, w_av,\n    eta_af, the world-frame velocity and force commands, and the three contact forces.\n\n    guards='paper': eight-sided cones, 10 N minimum normal force at every contact (eq. 35-36);\n    guards='code': six sides and the hand bound only (block_tilting_control.m).\"\"\"\n    bt = lab_hfvc.BlockTilt() if guards == \"paper\" else lab_hfvc.BlockTilt(cone_sides=6, n_min_table=0.0)\n    prob = lab_hfvc.block_tilt_problem(np.radians(theta_deg), bt)\n    sol = lab_hfvc.solve_ochs(prob) if method == \"ochs\" else lab_hfvc.solve_hs(prob, 3, rng=seed)\n    v_w, f_w = lab_hfvc.world_commands(sol.vel, sol.force, prob.n_u)\n    lam = sol.force.lam.reshape(3, 3)\n    return dict(method=sol.method, n_av=sol.vel.n_av, n_af=sol.vel.n_af, crash=sol.crash,\n                R_a=sol.vel.R_a, w_av=sol.vel.w_av, eta_af=sol.force.eta_af, v_world=v_w,\n                f_world=f_w, lam_hand=lam[0], lam_table1=lam[1], lam_table2=lam[2],\n                t_vel_ms=1e3 * sol.t_vel, t_force_ms=1e3 * sol.t_force)\n", "doc": "The HFVC of 2019 Sec. V at tilt theta_deg: n_av, n_af, crashing index, R_a, w_av,\neta_af, the world-frame velocity and force commands, and the three contact forces.\n\nguards='paper': eight-sided cones, 10 N minimum normal force at every contact (eq. 35-36);\nguards='code': six sides and the hand bound only (block_tilting_control.m).", "marimo": true},
"07_hybrid_servoing.py:lab_bound_gap": {"file": "07_hybrid_servoing.py", "start": 327, "end": 336, "src": "def lab_bound_gap(res):\n    \"\"\"Largest relative gap between the OCHS crashing index and hfvc.crash_bound over the\n    problems of one lab_table2 result, and the number of problems compared.\"\"\"\n    gap, n = 0.0, 0\n    for _, per, extra in res.values():\n        for p, o in zip(extra[\"probs\"], per[\"OCHS\"]):\n            if o.vel is not None and o.vel.n_av:\n                gap = max(gap, abs(o.crash / lab_hfvc.crash_bound(p)[0] - 1.0))\n                n += 1\n    return gap, n\n", "doc": "Largest relative gap between the OCHS crashing index and hfvc.crash_bound over the\nproblems of one lab_table2 result, and the number of problems compared.", "marimo": true},
"07_hybrid_servoing.py:lab_fig1_markdown": {"file": "07_hybrid_servoing.py", "start": 130, "end": 146, "src": "def lab_fig1_markdown():\n    \"\"\"2021 Fig. 1: the six reconstructed crashing indexes next to the printed ones, and the\n    fitted (phi, h) with its residuals (hfvc.fig1_table, hfvc.fig1_fit).\"\"\"\n    _names = {\"right\": \"right\", \"diag\": \"diagonal\", \"down\": \"down\"}\n    rows = lab_hfvc.fig1_table()\n    fit = lab_hfvc.fig1_fit()\n    lines = [\"| support | $V$ | printed | reconstruction |\", \"|---|---|---|---|\"]\n    for r in rows:\n        lines.append(f\"| {r['support']} | {_names[r['direction']]} | {r['paper']} | {r['ours']:.4f} |\")\n    lines.append(\"\")\n    lines.append(\n        f\"Fit: $\\\\varphi$ = {fit['phi_deg']:.2f}\u00b0, $h$ = {fit['h']:.4f}, residuals \"\n        f\"{', '.join(f'{x:+.4f}' for x in fit['residuals'])}. One-parameter fits: \"\n        f\"$\\\\varphi$ = {fit['phi_from_387']:.3f}\u00b0 from 3.87 alone, $h$ = {fit['h_from_710']:.4f} \"\n        f\"from 7.10 alone. The top-row diagonal at exactly 45\u00b0 gives {fit['ground_diag_at_45']:.4f}.\"\n    )\n    return \"\\n\".join(lines)\n", "doc": "2021 Fig. 1: the six reconstructed crashing indexes next to the printed ones, and the\nfitted (phi, h) with its residuals (hfvc.fig1_table, hfvc.fig1_fit).", "marimo": true},
"07_hybrid_servoing.py:lab_pairwise_trace": {"file": "07_hybrid_servoing.py", "start": 384, "end": 392, "src": "def lab_pairwise_trace(t, steps=30, s0=0.1):\n    \"\"\"|c_1^T c_2| over projected-gradient steps for two unit columns and M = 0.\"\"\"\n    K = np.array([[1.0, s0], [0.0, np.sqrt(1 - s0 * s0)]])\n    out = [s0]\n    for _ in range(steps):\n        K = K - t * lab_hfvc.alg1_grad(K, np.zeros((2, 2)), \"code\")\n        K = K / np.linalg.norm(K, axis=0)\n        out.append(abs(float(K[:, 0] @ K[:, 1])))\n    return np.array(out)\n", "doc": "|c_1^T c_2| over projected-gradient steps for two unit columns and M = 0.", "marimo": true},
"07_hybrid_servoing.py:lab_step_sweep": {"file": "07_hybrid_servoing.py", "start": 394, "end": 417, "src": "def lab_step_sweep(count=80, seed=7, settings=((10.0, 50), (1.0, 50), (0.2, 50), (0.2, 200))):\n    \"\"\"Algorithm 1 (Ns = 3, authors' cost) on 3D goal='max' problems for several (t, iters):\n    numbers solved, failed on dependent rows, failed on eq. 14, and the median and worst of\n    crash / bound over the solved ones.\"\"\"\n    probs = lab_hfvc.random_problems(count, dim=3, seed=seed, goal=\"max\")\n    rows = []\n    for t, iters in settings:\n        ok = dep = eq14 = other = 0\n        ratio = []\n        for i, p in enumerate(probs):\n            try:\n                v = lab_hfvc.alg1_velocity(p, 3, t, iters, \"code\", rng=i)\n                ok += 1\n                ratio.append(lab_hfvc.crashing_index(p.J, v.C) / lab_hfvc.crash_bound(p)[0])\n            except lab_hfvc.Infeasible as e:\n                msg = str(e)\n                dep += \"dependent\" in msg\n                eq14 += \"eq. 14\" in msg\n                other += not (\"dependent\" in msg or \"eq. 14\" in msg)\n        ratio = np.array(ratio)\n        rows.append(dict(t=t, iters=iters, solved=ok, dependent=dep, eq14=eq14, other=other,\n                         median_ratio=float(np.median(ratio)) if ratio.size else np.nan,\n                         worst_ratio=float(ratio.max()) if ratio.size else np.nan))\n    return rows\n", "doc": "Algorithm 1 (Ns = 3, authors' cost) on 3D goal='max' problems for several (t, iters):\nnumbers solved, failed on dependent rows, failed on eq. 14, and the median and worst of\ncrash / bound over the solved ones.", "marimo": true},
"07_hybrid_servoing.py:lab_study_numbers": {"file": "07_hybrid_servoing.py", "start": 512, "end": 540, "src": "def lab_study_numbers(rows, series):\n    \"\"\"The numbers the study's text quotes, computed from the result CSVs.\"\"\"\n    def pick(sweep, ctrl, **kw):\n        return [r for r in rows if r[\"sweep\"] == sweep and r[\"controller\"] == ctrl\n                and all(abs(r[k] - v) < 1e-9 for k, v in kw.items())]\n    hs = pick(\"size\", \"hfvc\")\n    ht = pick(\"table\", \"hfvc\")\n    keys = (\"peak_finger_N\", \"max_table_slip_mm\", \"t_reach_s\")\n    fs = [r for r in series if r[\"sweep\"] == \"nominal\" and r[\"controller\"] == \"force\"]\n\n    def rate(a, b):\n        return (b[\"theta_deg\"] - a[\"theta_deg\"]) / (b[\"t\"] - a[\"t\"])\n\n    k = max(1, round(0.1 / (fs[1][\"t\"] - fs[0][\"t\"]))) if len(fs) > 1 else 1\n    return dict(\n        random={c: sum(int(r[\"success\"]) for r in rows if r[\"sweep\"] == \"random\" and r[\"controller\"] == c)\n                for c in (\"hfvc\", \"velocity\", \"force\")},\n        hfvc_size_fn=(min(r[\"peak_finger_N\"] for r in hs), max(r[\"peak_finger_N\"] for r in hs)),\n        hfvc_size_t=(min(r[\"t_reach_s\"] for r in hs), max(r[\"t_reach_s\"] for r in hs)),\n        hfvc_table_same=\"yes\" if all(all(r[q] == ht[0][q] for q in keys) for r in ht) else \"no\",\n        hfvc_mu03_slip=pick(\"friction\", \"hfvc\", mu=0.3)[0][\"max_table_slip_mm\"],\n        hfvc_mu03_fn=pick(\"friction\", \"hfvc\", mu=0.3)[0][\"peak_finger_N\"],\n        vel_fn={L: pick(\"size\", \"velocity\", L_mm=L)[0][\"peak_finger_N\"] for L in (78.0, 81.0)},\n        vel_69_reason=pick(\"size\", \"velocity\", L_mm=69.0)[0][\"fail_reason\"] or \"success\",\n        vel_mu03_slip=pick(\"friction\", \"velocity\", mu=0.3)[0][\"max_table_slip_mm\"],\n        force_nominal_theta=pick(\"nominal\", \"force\")[0][\"theta_end_deg\"],\n        force_rate=(rate(fs[0], fs[k]), rate(fs[-1 - k], fs[-1])) if len(fs) > k else (float(\"nan\"),) * 2,\n        force_size_ok=\", \".join(f\"{r['L_mm']:.0f}\" for r in pick(\"size\", \"force\") if r[\"success\"]) or \"none\",\n    )\n", "doc": "The numbers the study's text quotes, computed from the result CSVs.", "marimo": true},
"07_hybrid_servoing.py:lab_success_table": {"file": "07_hybrid_servoing.py", "start": 542, "end": 556, "src": "def lab_success_table(rows):\n    \"\"\"Successes / trials and peak finger normal force (N, worst trial) per sweep and controller.\"\"\"\n    cells = {}\n    for r in rows:\n        k = (r[\"sweep\"], r[\"controller\"])\n        s, n, pk = cells.get(k, (0, 0, 0.0))\n        cells[k] = (s + int(r[\"success\"]), n + 1, max(pk, r[\"peak_finger_N\"]))\n    sweeps = list(dict.fromkeys(r[\"sweep\"] for r in rows))\n    ctrls = (\"hfvc\", \"velocity\", \"force\")\n    lines = [\"| sweep | \" + \" | \".join(ctrls) + \" |\", \"|---\" * (len(ctrls) + 1) + \"|\"]\n    for sw in sweeps:\n        lines.append(f\"| {sw} | \" + \" | \".join(\n            f\"{cells[(sw, c)][0]}/{cells[(sw, c)][1]}, {cells[(sw, c)][2]:.1f} N\" if (sw, c) in cells else \"\"\n            for c in ctrls) + \" |\")\n    return \"\\n\".join(lines)\n", "doc": "Successes / trials and peak finger normal force (N, worst trial) per sweep and controller.", "marimo": true},
"07_hybrid_servoing.py:lab_table2": {"file": "07_hybrid_servoing.py", "start": 247, "end": 279, "src": "def lab_table2(n_planar=100, n_3d=200, goal=\"min\", seed=7):\n    \"\"\"Table II-style comparison of OCHS, OCHS(M), HS3 and HS10 on random problems.\n\n    Returns {dim: (rows, per, extra)}: rows from hfvc.table2, the per-problem solutions,\n    and extra = {'ochs_worse': number of problems where OCHS has a larger crashing index\n    than HS3 or HS10, 'hs3_failures': failure messages of HS3 by cause,\n    'ratio': crash(HS3) / crash(OCHS) where both solved, 'probs': the problems}.\"\"\"\n    out = {}\n    for dim, count in ((2, n_planar), (3, n_3d)):\n        probs = lab_hfvc.random_problems(count, dim=dim, seed=seed, goal=goal)\n        solvers = {\"OCHS\": lab_hfvc.solve_ochs,\n                   \"OCHS(M)\": lambda p: lab_hfvc.solve_ochs(p, maximal=True),\n                   \"HS3\": lambda p: lab_hfvc.solve_hs(p, 3, rng=0),\n                   \"HS10\": lambda p: lab_hfvc.solve_hs(p, 10, rng=0)}\n        rows, per = lab_hfvc.table2(probs, solvers)\n        worse, ratio, causes = 0, [], {}\n        for i in range(len(probs)):\n            o = per[\"OCHS\"][i]\n            for h in (per[\"HS3\"][i], per[\"HS10\"][i]):\n                if o.vel is not None and h.vel is not None and o.vel.n_av:\n                    worse += int(o.crash > h.crash * (1 + 1e-6))\n            h3 = per[\"HS3\"][i]\n            if o.vel is not None and h3.vel is not None and o.vel.n_av and np.isfinite(h3.crash):\n                ratio.append(h3.crash / o.crash)\n            if not h3.ok:\n                key = (\"velocity: eq. 14 (underactuated)\" if \"eq. 14\" in h3.message else\n                       \"velocity: rows of C dependent\" if \"dependent\" in h3.message else\n                       \"velocity: goal inclusion\" if \"goal inclusion\" in h3.message else\n                       \"force: Algorithm 2 LP infeasible\" if \"Algorithm 2\" in h3.message else h3.message)\n                causes[key] = causes.get(key, 0) + 1\n        out[dim] = (rows, per, dict(ochs_worse=worse, hs3_failures=causes, ratio=np.array(ratio),\n                                    probs=probs))\n    return out\n", "doc": "Table II-style comparison of OCHS, OCHS(M), HS3 and HS10 on random problems.\n\nReturns {dim: (rows, per, extra)}: rows from hfvc.table2, the per-problem solutions,\nand extra = {'ochs_worse': number of problems where OCHS has a larger crashing index\nthan HS3 or HS10, 'hs3_failures': failure messages of HS3 by cause,\n'ratio': crash(HS3) / crash(OCHS) where both solved, 'probs': the problems}.", "marimo": true},
"labs/hybrid_servoing/hfvc.py:BlockTilt": {"file": "labs/hybrid_servoing/hfvc.py", "start": 959, "end": 994, "src": "@dataclass\nclass BlockTilt:\n    \"\"\"Parameters of the block-tilting example. Defaults: the authors' block_tilting_control.m\n    (0.5 kg block of 75 mm, 0.3 kg hand, mu = 0.8, 10 N minimum normal force, 0.5 rad/s), with\n    the eight-sided cones and the normal bounds on all three contacts of the paper (eq. 35-36).\n    Set n_min_table = 0 to reproduce the code, which bounds only the hand's normal force.\"\"\"\n\n    L: float = 0.075\n    mass: float = 0.5\n    hand_mass: float = 0.3\n    g: float = 9.8\n    mu_hand: float = 0.8\n    mu_table: float = 0.8\n    n_min_hand: float = 10.0\n    n_min_table: float = 10.0\n    cone_sides: int = 8\n    hand_x: float = -0.1\n    omega_goal: float = 0.5\n    edge: Optional[np.ndarray] = None  # world position of O (rotation-edge midpoint)\n\n    def __post_init__(self):\n        if self.edge is None:\n            self.edge = np.array([self.L / 2, 0.0, 0.0])\n        self.edge = np.asarray(self.edge, float)\n\n    @property\n    def p_hc(self):  # hand contact in the object frame\n        return np.array([self.hand_x * self.L, 0.0, self.L])\n\n    @property\n    def p_tc(self):  # the two table contacts (ends of the rotation edge) in the object frame\n        return np.array([[0.0, self.L / 2, 0.0], [0.0, -self.L / 2, 0.0]])\n\n    @property\n    def com(self):  # centre of mass in the object frame\n        return np.array([-self.L / 2, 0.0, self.L / 2])\n", "doc": "Parameters of the block-tilting example. Defaults: the authors' block_tilting_control.m\n(0.5 kg block of 75 mm, 0.3 kg hand, mu = 0.8, 10 N minimum normal force, 0.5 rad/s), with\nthe eight-sided cones and the normal bounds on all three contacts of the paper (eq. 35-36).\nSet n_min_table = 0 to reproduce the code, which bounds only the hand's normal force.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:Body": {"file": "labs/hybrid_servoing/hfvc.py", "start": 683, "end": 690, "src": "@dataclass\nclass Body:\n    \"\"\"A body whose velocity is (linear velocity of `ref`, angular velocity), world frame.\n\n    kind='rigid': dim + (1 if dim == 2 else 3) coordinates; kind='point': dim coordinates.\"\"\"\n\n    ref: np.ndarray\n    kind: str = \"rigid\"\n", "doc": "A body whose velocity is (linear velocity of `ref`, angular velocity), world frame.\n\nkind='rigid': dim + (1 if dim == 2 else 3) coordinates; kind='point': dim coordinates.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:Contact": {"file": "labs/hybrid_servoing/hfvc.py", "start": 693, "end": 711, "src": "@dataclass\nclass Contact:\n    \"\"\"A point contact at world point p with unit normal n pointing from body a (None = the\n    fixed environment) into body b. lambda_n > 0 pushes b along +n and a along -n.\n\n    mode 'stick': all frame directions are velocity constraints, friction cone guard;\n    mode 'slide': only the normal is a constraint; friction mu_slide opposes the sliding\n    direction slide_dir (a unit tangent) through an extra J' row and a Gam equality, as in the\n    authors' flip-against-corner example. mu_slide = 0 makes the contact frictionless.\"\"\"\n\n    p: np.ndarray\n    n: np.ndarray\n    b: int\n    a: Optional[int]\n    mode: str = \"stick\"\n    mu: float = 0.8\n    n_min: float = 0.0\n    mu_slide: float = 0.0\n    slide_dir: Optional[np.ndarray] = None\n", "doc": "A point contact at world point p with unit normal n pointing from body a (None = the\nfixed environment) into body b. lambda_n > 0 pushes b along +n and a along -n.\n\nmode 'stick': all frame directions are velocity constraints, friction cone guard;\nmode 'slide': only the normal is a constraint; friction mu_slide opposes the sliding\ndirection slide_dir (a unit tangent) through an extra J' row and a Gam equality, as in the\nauthors' flip-against-corner example. mu_slide = 0 makes the contact frictionless.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:E_quat": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1033, "end": 1036, "src": "def E_quat(q):\n    \"\"\"2019 eq. 27: qdot = E(q) omega_body, 4 x 3.\"\"\"\n    w, x, y, z = q\n    return 0.5 * np.array([[-x, -y, -z], [w, -z, y], [z, w, -x], [-y, x, w]])\n", "doc": "2019 eq. 27: qdot = E(q) omega_body, 4 x 3.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:ForceControl": {"file": "labs/hybrid_servoing/hfvc.py", "start": 469, "end": 476, "src": "@dataclass\nclass ForceControl:\n    eta_af: np.ndarray  # (n_af,) force command magnitudes\n    lam: np.ndarray  # contact forces\n    eta: np.ndarray  # transformed generalized force T f = [eta_u; eta_af; eta_av]\n    f: np.ndarray  # generalized (robot) force\n    method: str = \"\"\n    info: dict = field(default_factory=dict)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:GoalInclusion": {"file": "labs/hybrid_servoing/hfvc.py", "start": 217, "end": 228, "src": "@dataclass\nclass GoalInclusion:\n    null_inclusion: bool  # condition 1): NULL([J;C]) subset of NULL([J;G]), via the rank test eq. 13\n    common_solution: bool  # condition 2): some v with J v = 0, C v = b_C, G v = b_G\n    rank_JC: int\n    rank_JCG: int\n    residual: float  # least-squares residual of the stacked system in condition 2)\n    sampled_goal_error: float  # max |G v - b_G| over random solutions of J v = 0, C v = b_C\n\n    @property\n    def ok(self):\n        return self.null_inclusion and self.common_solution\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:HFVCProblem": {"file": "labs/hybrid_servoing/hfvc.py", "start": 132, "end": 184, "src": "@dataclass\nclass HFVCProblem:\n    \"\"\"One time step of a hybrid servoing problem.\n\n    J        (m x n)   velocity constraints J v = 0 (2021 J; 2019 N = J_Phi Omega)\n    n_u      int       number of unactuated coordinates (the first n_u entries of v)\n    G, b_G             goal G v = b_G (2019 eq. 1, 2021 eq. 2)\n    F        (n,)      external generalized force (gravity), Newton J'^T lam + f + F = 0\n    J_force  (m' x n)  rows that carry contact forces (J plus sliding-friction rows); None = J\n    Lam, b_Lam         guard inequalities Lam [lam; f] <= b_Lam (2019 eq. 6 and 18, 2021 eq. 4)\n    Gam, b_Gam         guard equalities Gam [lam; f] = b_Gam (2019 eq. 6 and 19)\n    \"\"\"\n\n    J: np.ndarray\n    n_u: int\n    G: np.ndarray\n    b_G: np.ndarray\n    F: Optional[np.ndarray] = None\n    J_force: Optional[np.ndarray] = None\n    Lam: Optional[np.ndarray] = None\n    b_Lam: Optional[np.ndarray] = None\n    Gam: Optional[np.ndarray] = None\n    b_Gam: Optional[np.ndarray] = None\n    name: str = \"\"\n    info: dict = field(default_factory=dict)\n\n    def __post_init__(self):\n        self.J = _as2d(self.J)\n        n = self.J.shape[1]\n        self.G = _as2d(self.G, n)\n        self.b_G = np.atleast_1d(np.asarray(self.b_G, float))\n        self.F = np.zeros(n) if self.F is None else np.asarray(self.F, float)\n        self.J_force = self.J.copy() if self.J_force is None else _as2d(self.J_force, n)\n        m = self.J_force.shape[0]\n        if self.Lam is None:\n            self.Lam, self.b_Lam = np.zeros((0, m + n)), np.zeros(0)\n        if self.Gam is None:\n            self.Gam, self.b_Gam = np.zeros((0, m + n)), np.zeros(0)\n        self.Lam, self.Gam = _as2d(self.Lam, m + n), _as2d(self.Gam, m + n)\n        self.b_Lam = np.atleast_1d(np.asarray(self.b_Lam, float))\n        self.b_Gam = np.atleast_1d(np.asarray(self.b_Gam, float))\n\n    @property\n    def n(self):\n        return self.J.shape[1]\n\n    @property\n    def n_a(self):\n        return self.n - self.n_u\n\n    @property\n    def n_lam(self):\n        return self.J_force.shape[0]\n", "doc": "One time step of a hybrid servoing problem.\n\nJ        (m x n)   velocity constraints J v = 0 (2021 J; 2019 N = J_Phi Omega)\nn_u      int       number of unactuated coordinates (the first n_u entries of v)\nG, b_G             goal G v = b_G (2019 eq. 1, 2021 eq. 2)\nF        (n,)      external generalized force (gravity), Newton J'^T lam + f + F = 0\nJ_force  (m' x n)  rows that carry contact forces (J plus sliding-friction rows); None = J\nLam, b_Lam         guard inequalities Lam [lam; f] <= b_Lam (2019 eq. 6 and 18, 2021 eq. 4)\nGam, b_Gam         guard equalities Gam [lam; f] = b_Gam (2019 eq. 6 and 19)", "marimo": false},
"labs/hybrid_servoing/hfvc.py:HFVCSolution": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1285, "end": 1299, "src": "@dataclass\nclass HFVCSolution:\n    method: str\n    ok: bool\n    message: str = \"\"\n    vel: Optional[VelocityControl] = None\n    force: Optional[ForceControl] = None\n    crash: float = math.inf\n    t_vel: float = math.nan  # seconds\n    t_force: float = math.nan\n\n    def summary(self):\n        return dict(method=self.method, ok=self.ok, message=self.message, crash=self.crash,\n                    n_av=self.vel.n_av if self.vel else None, t_vel_ms=1e3 * self.t_vel,\n                    t_force_ms=1e3 * self.t_force)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:Infeasible": {"file": "labs/hybrid_servoing/hfvc.py", "start": 274, "end": 275, "src": "class Infeasible(Exception):\n    \"\"\"The velocity or force problem has no solution (the message names the failed test).\"\"\"\n", "doc": "The velocity or force problem has no solution (the message names the failed test).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:Locked": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1175, "end": 1176, "src": "class Locked(RuntimeError):\n    \"\"\"The sampled contact setting leaves the robot no free motion, so no goal can be posed.\"\"\"\n", "doc": "The sampled contact setting leaves the robot no free motion, so no goal can be posed.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:VelocityControl": {"file": "labs/hybrid_servoing/hfvc.py", "start": 259, "end": 271, "src": "@dataclass\nclass VelocityControl:\n    \"\"\"The velocity half of a HFVC: dimensions, directions (T) and magnitudes (w_av).\"\"\"\n\n    n_av: int\n    n_af: int\n    C: np.ndarray  # (n_av x n) velocity-controlled rows, zero in the first n_u columns\n    R_a: np.ndarray  # (n_a x n_a) [force-controlled rows; C's actuated part]\n    T: np.ndarray  # diag(I_u, R_a)\n    w_av: np.ndarray  # (n_av,) velocity command magnitudes, C v = w_av\n    v_star: np.ndarray  # one velocity that satisfies J v = 0, G v = b_G\n    method: str = \"\"\n    info: dict = field(default_factory=dict)\n", "doc": "The velocity half of a HFVC: dimensions, directions (T) and magnitudes (w_av).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:_as2d": {"file": "labs/hybrid_servoing/hfvc.py", "start": 57, "end": 61, "src": "def _as2d(A, n=None):\n    A = np.asarray(A, dtype=float)\n    if A.ndim == 1:\n        A = A.reshape(1, -1) if A.size else np.zeros((0, n or 0))\n    return A\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:_rank_from_sv": {"file": "labs/hybrid_servoing/hfvc.py", "start": 64, "end": 67, "src": "def _rank_from_sv(s, rtol=RTOL, atol=ATOL):\n    if s.size == 0:\n        return 0\n    return int(np.sum(s > max(rtol * s[0], atol)))\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:_solve": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1302, "end": 1315, "src": "def _solve(prob, method, vel_fn, force_fn):\n    t0 = time.perf_counter()\n    try:\n        vel = vel_fn(prob)\n    except Infeasible as e:\n        return HFVCSolution(method, False, f\"velocity: {e}\", t_vel=time.perf_counter() - t0)\n    t1 = time.perf_counter()\n    crash = crashing_index(prob.J, vel.C) if vel.n_av else math.nan\n    try:\n        force = force_fn(prob, vel)\n    except Infeasible as e:\n        return HFVCSolution(method, False, f\"force: {e}\", vel, None, crash, t1 - t0,\n                            time.perf_counter() - t1)\n    return HFVCSolution(method, True, \"\", vel, force, crash, t1 - t0, time.perf_counter() - t1)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:_unit": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1185, "end": 1190, "src": "def _unit(rng, dim, upper=False):\n    v = rng.standard_normal(dim)\n    v /= np.linalg.norm(v)\n    if upper and v[-1] < 0:\n        v[-1] = -v[-1]\n    return v\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg1_basis": {"file": "labs/hybrid_servoing/hfvc.py", "start": 342, "end": 363, "src": "def alg1_basis(prob: HFVCProblem, check=True):\n    \"\"\"Steps 1-3 of 2019 Algorithm 1: ranks, n_av (eq. 10), B_c (eq. 13) and Null(N).\n\n    Returns dict with r_N, r_NG, n_av, sigma (rows sigma_i^T), Bc (n x n_c, orthonormal columns),\n    NullN (rows: orthonormal basis of null(N)) and M = B_c^T Null(N)^T Null(N) B_c.\n    check=False skips eq. 14, so the basis also exists for underactuated problems.\n\n    The columns of B_c span S = ROW([N; G]) intersected with {c : c_u = 0}: every goal-inclusive\n    velocity-command row lies in S (2021 eq. 11-13), so Algorithm 1 and OCHS search one space.\"\"\"\n    N, G, n, n_u = prob.J, prob.G, prob.n, prob.n_u\n    n_a = n - n_u\n    NG = np.vstack([N, G])\n    r_N, r_NG = svd_rank(N), svd_rank(NG)\n    if check and r_N + n_a < n:  # eq. 14 (the authors' code asserts the strict version)\n        raise Infeasible(f\"eq. 14 fails: r_N + n_a = {r_N + n_a} < n = {n}\")\n    n_av = r_NG - r_N  # eq. 10\n    sigma = null_rows(NG)  # rows sigma_i^T, i = 1..n - r_NG\n    A13 = np.vstack([sigma, np.hstack([np.eye(n_u), np.zeros((n_u, n_a))])])\n    Bc = null_rows(A13, n).T  # eq. 13 solution space, orthonormal columns\n    NullN = null_rows(N, n)\n    M = Bc.T @ NullN.T @ NullN @ Bc\n    return dict(r_N=r_N, r_NG=r_NG, n_av=n_av, n_c=Bc.shape[1], sigma=sigma, Bc=Bc, NullN=NullN, M=M)\n", "doc": "Steps 1-3 of 2019 Algorithm 1: ranks, n_av (eq. 10), B_c (eq. 13) and Null(N).\n\nReturns dict with r_N, r_NG, n_av, sigma (rows sigma_i^T), Bc (n x n_c, orthonormal columns),\nNullN (rows: orthonormal basis of null(N)) and M = B_c^T Null(N)^T Null(N) B_c.\ncheck=False skips eq. 14, so the basis also exists for underactuated problems.\n\nThe columns of B_c span S = ROW([N; G]) intersected with {c : c_u = 0}: every goal-inclusive\nvelocity-command row lies in S (2021 eq. 11-13), so Algorithm 1 and OCHS search one space.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg1_cost": {"file": "labs/hybrid_servoing/hfvc.py", "start": 301, "end": 321, "src": "def alg1_cost(K, M, form=\"code\"):\n    \"\"\"Cost of 2019 eq. 15 for coefficients K (n_c x n_av), c_i = B_c k_i with B_c orthonormal.\n\n    form='paper':   sum_{i!=j} |c_i^T c_j| - sum_i ||Null(N)^T c_i||      (eq. 15 as printed)\n    form='squared': sum_{i!=j} (c_i^T c_j)^2 - sum_i ||Null(N)^T c_i||^2\n    form='code':    sum_{i<j} (c_i^T c_j)^2 - sum_i ||Null(N)^T c_i||^2    (authors' MATLAB code)\n    M = B_c^T Null(N)^T Null(N) B_c, so ||Null(N)^T c_i||^2 = k_i^T M k_i.\n\n    The authors' code sums (c_i^T c_j)^2 over i != j but differentiates it with the factor 2 of\n    a single pair, so the descent direction it follows is the gradient of the 'code' cost, which\n    counts each unordered pair once. The cost value it prints is the 'squared' one.\"\"\"\n    Gram = K.T @ K\n    off = Gram - np.diag(np.diag(Gram))\n    quad = np.einsum(\"ji,jk,ki->i\", K, M, K)\n    if form == \"paper\":\n        return float(np.abs(off).sum() - np.sqrt(np.maximum(quad, 0.0)).sum())\n    if form == \"squared\":\n        return float((off**2).sum() - quad.sum())\n    if form == \"code\":\n        return float(0.5 * (off**2).sum() - quad.sum())\n    raise ValueError(form)\n", "doc": "Cost of 2019 eq. 15 for coefficients K (n_c x n_av), c_i = B_c k_i with B_c orthonormal.\n\nform='paper':   sum_{i!=j} |c_i^T c_j| - sum_i ||Null(N)^T c_i||      (eq. 15 as printed)\nform='squared': sum_{i!=j} (c_i^T c_j)^2 - sum_i ||Null(N)^T c_i||^2\nform='code':    sum_{i<j} (c_i^T c_j)^2 - sum_i ||Null(N)^T c_i||^2    (authors' MATLAB code)\nM = B_c^T Null(N)^T Null(N) B_c, so ||Null(N)^T c_i||^2 = k_i^T M k_i.\n\nThe authors' code sums (c_i^T c_j)^2 over i != j but differentiates it with the factor 2 of\na single pair, so the descent direction it follows is the gradient of the 'code' cost, which\ncounts each unordered pair once. The cost value it prints is the 'squared' one.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg1_grad": {"file": "labs/hybrid_servoing/hfvc.py", "start": 324, "end": 339, "src": "def alg1_grad(K, M, form=\"code\"):\n    \"\"\"Gradient of alg1_cost with respect to K (same shape as K).\n\n    Each unordered pair {i, j} appears twice in sum_{i!=j}, which gives the factor 2 ('paper')\n    and 4 ('squared'); 'code' counts each pair once, factor 2, as in the authors' code.\"\"\"\n    Gram = K.T @ K\n    off = Gram - np.diag(np.diag(Gram))\n    MK = M @ K\n    if form == \"paper\":\n        quad = np.maximum(np.einsum(\"ji,ji->i\", K, MK), 1e-300)\n        return 2.0 * K @ np.sign(off) - MK / np.sqrt(quad)\n    if form == \"squared\":\n        return 4.0 * K @ off - 2.0 * MK\n    if form == \"code\":\n        return 2.0 * K @ off - 2.0 * MK\n    raise ValueError(form)\n", "doc": "Gradient of alg1_cost with respect to K (same shape as K).\n\nEach unordered pair {i, j} appears twice in sum_{i!=j}, which gives the factor 2 ('paper')\nand 4 ('squared'); 'code' counts each pair once, factor 2, as in the authors' code.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg1_pgd": {"file": "labs/hybrid_servoing/hfvc.py", "start": 400, "end": 419, "src": "def alg1_pgd(M, n_av, K0, t=10.0, iters=50, form=\"code\", tol=0.0, record=False):\n    \"\"\"Projected gradient descent of 2019 Sec. IV-A on unit-length columns of K.\n\n    Steps: k <- k - t grad; k_i <- k_i / ||B_c k_i|| (= ||k_i|| since B_c is orthonormal).\n    Runs `iters` iterations (the authors' code and 2021 Sec. VI-B use 50) and stops early when\n    the cost changes by less than tol. Returns (K, cost, history of costs if record).\"\"\"\n    K = K0 / np.linalg.norm(K0, axis=0, keepdims=True)\n    hist = [alg1_cost(K, M, form)] if record else None\n    last = alg1_cost(K, M, form)\n    for _ in range(iters):\n        K = K - t * alg1_grad(K, M, form)\n        K = K / np.linalg.norm(K, axis=0, keepdims=True)\n        cost = alg1_cost(K, M, form)\n        if record:\n            hist.append(cost)\n        if tol and abs(cost - last) < tol:\n            last = cost\n            break\n        last = cost\n    return K, last, hist\n", "doc": "Projected gradient descent of 2019 Sec. IV-A on unit-length columns of K.\n\nSteps: k <- k - t grad; k_i <- k_i / ||B_c k_i|| (= ||k_i|| since B_c is orthonormal).\nRuns `iters` iterations (the authors' code and 2021 Sec. VI-B use 50) and stops early when\nthe cost changes by less than tol. Returns (K, cost, history of costs if record).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg1_velocity": {"file": "labs/hybrid_servoing/hfvc.py", "start": 422, "end": 461, "src": "def alg1_velocity(prob: HFVCProblem, Ns=3, t=10.0, iters=50, form=\"code\", rng=None, tol=0.0,\n                  init=\"uniform\"):\n    \"\"\"2019 Algorithm 1: n_av, C (via eq. 13 and 15), R_a (eq. 16), T, v* and w_av.\n\n    Ns random initializations (init='uniform': entries U[0, 1), as the authors' code draws them;\n    init='normal': standard normal) are each run through alg1_pgd; the lowest final cost wins.\n    The defaults (form='code', t = 10, 50 iterations, uniform starts) reproduce the authors'\n    MATLAB; form='paper' is eq. 15 as printed (see alg1_cost).\"\"\"\n    rng = np.random.default_rng(rng)\n    b = alg1_basis(prob)\n    n, n_u, n_av = prob.n, prob.n_u, b[\"n_av\"]\n    n_a = n - n_u\n    if b[\"n_c\"] < n_av:\n        raise Infeasible(f\"n_c = {b['n_c']} < n_av = {n_av}\")\n\n    def start():\n        shape = (b[\"n_c\"], n_av)\n        return rng.uniform(size=shape) if init == \"uniform\" else rng.standard_normal(shape)\n\n    if n_av == 0:\n        C = np.zeros((0, n))\n        costs, best = [0.0], 0\n    else:\n        results = [alg1_pgd(b[\"M\"], n_av, start(), t, iters, form, tol) for _ in range(Ns)]\n        costs = [r[1] for r in results]\n        best = int(np.argmin(costs))\n        C = (b[\"Bc\"] @ results[best][0]).T\n    # Algorithm 1 as printed stops here. Its C always satisfies C sigma_i = 0, but projected\n    # gradient descent can return rows that are dependent on each other or on the rows of N,\n    # and then Sol(N & C) is larger than Sol(N & G) (eq. 7 fails) and R_a is singular.\n    check_goal_rank(prob, C, \"Algorithm 1\")\n    R_a, T = complete_axes(C, n_u)\n    NG = np.vstack([prob.J, prob.G])\n    v_star, res = special_solution(NG, np.concatenate([np.zeros(prob.J.shape[0]), prob.b_G]))\n    if res > 1e-7 * (1 + np.linalg.norm(prob.b_G)):\n        raise Infeasible(f\"goal inconsistent with the constraints (residual {res:.2e})\")\n    return VelocityControl(\n        n_av, n_a - n_av, C, R_a, T, C @ v_star, v_star, f\"alg1(Ns={Ns},{form},{init})\",\n        dict(costs=costs, best=best, r_N=b[\"r_N\"], r_NG=b[\"r_NG\"], n_c=b[\"n_c\"]),\n    )\n", "doc": "2019 Algorithm 1: n_av, C (via eq. 13 and 15), R_a (eq. 16), T, v* and w_av.\n\nNs random initializations (init='uniform': entries U[0, 1), as the authors' code draws them;\ninit='normal': standard normal) are each run through alg1_pgd; the lowest final cost wins.\nThe defaults (form='code', t = 10, 50 iterations, uniform starts) reproduce the authors'\nMATLAB; form='paper' is eq. 15 as printed (see alg1_cost).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg2_force": {"file": "labs/hybrid_servoing/hfvc.py", "start": 515, "end": 564, "src": "def alg2_force(prob: HFVCProblem, vel: VelocityControl, objective=\"l1\"):\n    \"\"\"2019 Algorithm 2: choose eta_af so that the forces fixed by eq. 23 satisfy the guards (18).\n\n    The KKT system makes the free forces an affine function f_free = f0 + P eta_af (computed with\n    the pseudo-inverse, which equals the KKT solution when the KKT matrix is nonsingular, and\n    which adds the consistency rows (I - M M^+)(b - M_af eta_af) = 0 when it is singular). The\n    guard rows then become linear inequalities on eta_af alone, a small LP.\n    objective: 'l1' min sum |eta_af| (LP), 'feasibility' (LP, zero cost), 'l2' min ||eta_af||^2\n    (the authors' code solves this QP with quadprog).\"\"\"\n    M_free, M_af, b, i_free, i_af, Tinv = alg2_newton_system(prob, vel)\n    m, n, n_af = prob.n_lam, prob.n, vel.n_af\n    Mp = np.linalg.pinv(M_free, rcond=1e-10)\n    f0, P = Mp @ b, -Mp @ M_af\n    Q = np.eye(M_free.shape[0]) - M_free @ Mp  # consistency projector\n    A_eq, b_eq = Q @ M_af, Q @ b\n    keep = np.linalg.norm(np.hstack([A_eq, b_eq[:, None]]), axis=1) > 1e-9\n    A_eq, b_eq = A_eq[keep], b_eq[keep]\n    # [lam; eta] = E_free f_free + E_af eta_af\n    E_free = np.zeros((m + n, len(i_free)))\n    E_free[i_free, np.arange(len(i_free))] = 1\n    E_af = np.zeros((m + n, n_af))\n    E_af[i_af, np.arange(n_af)] = 1\n    Lam_t = np.hstack([prob.Lam[:, :m], prob.Lam[:, m:] @ Tinv])  # eq. 18\n    A_ub = Lam_t @ (E_free @ P + E_af)\n    b_ub = prob.b_Lam - Lam_t @ (E_free @ f0)\n    if n_af == 0:\n        eta_af = np.zeros(0)\n        if (A_ub.size and np.any(b_ub < -1e-7)) or (A_eq.size and np.any(np.abs(b_eq) > 1e-7)):\n            raise Infeasible(\"guard conditions fail with no force-controlled direction\")\n    elif objective == \"l2\":\n        eta_af, ok = least_distance(A_ub, b_ub, A_eq if A_eq.size else None, b_eq if A_eq.size else None)\n        if not ok:\n            raise Infeasible(\"Algorithm 2: guard conditions infeasible (QP)\")\n    else:\n        c = np.concatenate([np.zeros(n_af), np.ones(n_af) if objective == \"l1\" else np.zeros(n_af)])\n        I = np.eye(n_af)\n        Aub = np.vstack([np.hstack([A_ub, np.zeros((A_ub.shape[0], n_af))]),\n                         np.hstack([I, -I]), np.hstack([-I, -I])])\n        bub = np.concatenate([b_ub, np.zeros(2 * n_af)])\n        Aeq = np.hstack([A_eq, np.zeros((A_eq.shape[0], n_af))]) if A_eq.size else None\n        res = linprog(c, A_ub=Aub, b_ub=bub, A_eq=Aeq, b_eq=b_eq if A_eq.size else None,\n                      bounds=[(None, None)] * n_af + [(0, None)] * n_af, method=\"highs\")\n        if res.status != 0:\n            raise Infeasible(f\"Algorithm 2: LP status {res.status} ({res.message})\")\n        eta_af = res.x[:n_af]\n    x = E_free @ (f0 + P @ eta_af) + E_af @ eta_af\n    lam, eta = x[:m], x[m:]\n    return ForceControl(eta_af, lam, eta, Tinv @ eta, f\"alg2({objective})\",\n                        dict(M_free_shape=M_free.shape, rank_M_free=svd_rank(M_free),\n                             n_consistency_rows=int(A_eq.shape[0])))\n", "doc": "2019 Algorithm 2: choose eta_af so that the forces fixed by eq. 23 satisfy the guards (18).\n\nThe KKT system makes the free forces an affine function f_free = f0 + P eta_af (computed with\nthe pseudo-inverse, which equals the KKT solution when the KKT matrix is nonsingular, and\nwhich adds the consistency rows (I - M M^+)(b - M_af eta_af) = 0 when it is singular). The\nguard rows then become linear inequalities on eta_af alone, a small LP.\nobjective: 'l1' min sum |eta_af| (LP), 'feasibility' (LP, zero cost), 'l2' min ||eta_af||^2\n(the authors' code solves this QP with quadprog).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg2_kkt": {"file": "labs/hybrid_servoing/hfvc.py", "start": 501, "end": 512, "src": "def alg2_kkt(prob: HFVCProblem, vel: VelocityControl, eta_af):\n    \"\"\"Solve 2019 eq. 22 for the free forces given a force command eta_af.\n\n    [[2I, M_free^T], [M_free, 0]] [f_free; f_free*] = [0; b - M_af eta_af], the KKT system of\n    min ||f_free||^2 s.t. M_free f_free = b - M_af eta_af (eq. 21). The printed eq. 22-23 drop\n    b_Gam from the right-hand side; it is kept here, as in the authors' code.\"\"\"\n    M_free, M_af, b, _, _, _ = alg2_newton_system(prob, vel)\n    k, p = M_free.shape\n    KKT = np.block([[2 * np.eye(p), M_free.T], [M_free, np.zeros((k, k))]])\n    rhs = np.concatenate([np.zeros(p), b - M_af @ np.atleast_1d(eta_af)])\n    sol = np.linalg.solve(KKT, rhs)\n    return sol[:p], sol[p:]\n", "doc": "Solve 2019 eq. 22 for the free forces given a force command eta_af.\n\n[[2I, M_free^T], [M_free, 0]] [f_free; f_free*] = [0; b - M_af eta_af], the KKT system of\nmin ||f_free||^2 s.t. M_free f_free = b - M_af eta_af (eq. 21). The printed eq. 22-23 drop\nb_Gam from the right-hand side; it is kept here, as in the authors' code.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:alg2_newton_system": {"file": "labs/hybrid_servoing/hfvc.py", "start": 479, "end": 498, "src": "def alg2_newton_system(prob: HFVCProblem, vel: VelocityControl):\n    \"\"\"2019 eq. 20 split into free and commanded columns (eq. 21).\n\n    Unknowns x = [lam; eta], eta = [eta_u; eta_af; eta_av]. Rows: H T^-1 eta = 0 (f_u = 0),\n    T J'^T lam + eta = -T F (eq. 17), [Gam_lam, Gam_f T^-1][lam; eta] = b_Gam (eq. 19).\n    Returns M_free, M_af, b, and index arrays of the free forces [lam, eta_u, eta_av].\"\"\"\n    n, n_u, m = prob.n, prob.n_u, prob.n_lam\n    T = vel.T\n    Tinv = np.linalg.inv(T)\n    H = np.hstack([np.eye(n_u), np.zeros((n_u, n - n_u))])\n    Gl, Gf = prob.Gam[:, :m], prob.Gam[:, m:]\n    M = np.vstack([\n        np.hstack([np.zeros((n_u, m)), H @ Tinv]),\n        np.hstack([T @ prob.J_force.T, np.eye(n)]),\n        np.hstack([Gl, Gf @ Tinv]),\n    ])\n    b = np.concatenate([np.zeros(n_u), -T @ prob.F, prob.b_Gam])\n    i_af = m + n_u + np.arange(vel.n_af)\n    i_free = np.setdiff1d(np.arange(m + n), i_af)\n    return M[:, i_free], M[:, i_af], b, i_free, i_af, Tinv\n", "doc": "2019 eq. 20 split into free and commanded columns (eq. 21).\n\nUnknowns x = [lam; eta], eta = [eta_u; eta_af; eta_av]. Rows: H T^-1 eta = 0 (f_u = 0),\nT J'^T lam + eta = -T F (eq. 17), [Gam_lam, Gam_f T^-1][lam; eta] = b_Gam (eq. 19).\nReturns M_free, M_af, b, and index arrays of the free forces [lam, eta_u, eta_av].", "marimo": false},
"labs/hybrid_servoing/hfvc.py:block_tilt_jac": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1066, "end": 1074, "src": "def block_tilt_jac(q, bt: BlockTilt):\n    \"\"\"d Phi / d q, 9 x 10, derived by hand from eq. 33 (columns p_O, q_O, p_H).\"\"\"\n    qO = q[3:7]\n    Jp = np.zeros((9, 10))\n    for k, p in enumerate([bt.p_hc, bt.p_tc[0], bt.p_tc[1]]):\n        Jp[3 * k:3 * k + 3, 0:3] = np.eye(3)\n        Jp[3 * k:3 * k + 3, 3:7] = dRp_dq(qO, p)\n    Jp[0:3, 7:10] = -np.eye(3)\n    return Jp\n", "doc": "d Phi / d q, 9 x 10, derived by hand from eq. 33 (columns p_O, q_O, p_H).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:block_tilt_omega": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1039, "end": 1042, "src": "def block_tilt_omega(q):\n    \"\"\"2019 eq. 26: Omega(q) = diag(R, E(q), I_3), 10 x 9, so qdot = Omega v.\"\"\"\n    R = quat_to_R(q[3:7])\n    return block_diag(R, E_quat(q[3:7]), np.eye(3))\n", "doc": "2019 eq. 26: Omega(q) = diag(R, E(q), I_3), 10 x 9, so qdot = Omega v.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:block_tilt_phi": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1052, "end": 1063, "src": "def block_tilt_phi(q, bt: BlockTilt, p_tc_world=None):\n    \"\"\"2019 eq. 33: Phi(q) = [R p_hc + p_O - p_H; R p_tc,1 + p_O - W p_tc,1; ...] in R^9.\n\n    p_tc_world (2 x 3): the fixed world points of the table contacts (default: their positions\n    at theta = 0).\"\"\"\n    pO, qO, pH = q[:3], q[3:7], q[7:]\n    R = quat_to_R(qO)\n    if p_tc_world is None:\n        p_tc_world = bt.edge + bt.p_tc\n    rows = [R @ bt.p_hc + pO - pH]\n    rows += [R @ bt.p_tc[i] + pO - p_tc_world[i] for i in range(2)]\n    return np.concatenate(rows)\n", "doc": "2019 eq. 33: Phi(q) = [R p_hc + p_O - p_H; R p_tc,1 + p_O - W p_tc,1; ...] in R^9.\n\np_tc_world (2 x 3): the fixed world points of the table contacts (default: their positions\nat theta = 0).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:block_tilt_problem": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1077, "end": 1124, "src": "def block_tilt_problem(theta=0.0, bt: Optional[BlockTilt] = None, q=None):\n    \"\"\"The HFVC problem of 2019 Sec. V at tilt angle theta (or at configuration q).\n\n    v = [body twist of O (v_b, omega_b); hand velocity], lambda = [lam_hc; lam_tc1; lam_tc2] in\n    world frame (forces on the object), f = [body wrench on O; hand force].\"\"\"\n    bt = bt or BlockTilt()\n    q = block_tilt_state(theta, bt) if q is None else np.asarray(q, float)\n    R = quat_to_R(q[3:7])\n    pO = q[:3]\n    N = block_tilt_jac(q, bt) @ block_tilt_omega(q)  # N = J_Phi Omega (2019 Sec. IV-A)\n    # goal, eq. 29-30: spatial twist about the edge line, mapped to the body twist\n    w_g = np.array([0.0, 1.0, 0.0])\n    xi_s = np.concatenate([-np.cross(w_g, bt.edge), w_g]) * bt.omega_goal\n    Ad_inv = np.block([[R.T, -R.T @ skew(pO)], [np.zeros((3, 3)), R.T]])\n    G = np.hstack([np.eye(6), np.zeros((6, 3))])\n    b_G = Ad_inv @ xi_s\n    # external force, eq. 34 plus the gravity torque about O\n    gW = np.array([0.0, 0.0, -bt.g])\n    fO = R.T @ (bt.mass * gW)\n    F = np.concatenate([fO, np.cross(bt.com, fO), bt.hand_mass * gW])\n    # guard conditions, eq. 35-36 (hand rows use the pressing normal -z_O)\n    m, n = 9, 9\n    z = np.array([0.0, 0.0, 1.0])\n    D = cone_directions(bt.cone_sides)\n    Lam, bL = [], []\n    for d in D:\n        dd = np.array([d[0], d[1], 0.0])\n        row = np.zeros(m + n)\n        row[0:3] = (dd + bt.mu_hand * z) @ R.T  # d^T lam_O <= mu (-z^T lam_O)\n        Lam.append(row)\n        bL.append(0.0)\n        for k in (1, 2):\n            row = np.zeros(m + n)\n            row[3 * k:3 * k + 3] = dd - bt.mu_table * z  # d^T lam <= mu z^T lam\n            Lam.append(row)\n            bL.append(0.0)\n    row = np.zeros(m + n)\n    row[0:3] = z @ R.T  # -z^T R^T lam_hc >= n_min_hand\n    Lam.append(row)\n    bL.append(-bt.n_min_hand)\n    for k in (1, 2):\n        if bt.n_min_table > 0:\n            row = np.zeros(m + n)\n            row[3 * k:3 * k + 3] = -z\n            Lam.append(row)\n            bL.append(-bt.n_min_table)\n    return HFVCProblem(N, 6, G, b_G, F, None, np.array(Lam), np.array(bL), name=\"block-tilting\",\n                       info=dict(q=q, R=R, bt=bt))\n", "doc": "The HFVC problem of 2019 Sec. V at tilt angle theta (or at configuration q).\n\nv = [body twist of O (v_b, omega_b); hand velocity], lambda = [lam_hc; lam_tc1; lam_tc2] in\nworld frame (forces on the object), f = [body wrench on O; hand force].", "marimo": false},
"labs/hybrid_servoing/hfvc.py:block_tilt_state": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1045, "end": 1049, "src": "def block_tilt_state(theta, bt: BlockTilt):\n    \"\"\"q = [p_O; q_O; p_H] with the block tilted by theta (rad) about +y through the edge.\"\"\"\n    qO = np.array([math.cos(theta / 2), 0.0, math.sin(theta / 2), 0.0])\n    pH = bt.edge + quat_to_R(qO) @ bt.p_hc\n    return np.concatenate([bt.edge, qO, pH])\n", "doc": "q = [p_O; q_O; p_H] with the block tilted by theta (rad) about +y through the edge.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:body_dofs": {"file": "labs/hybrid_servoing/hfvc.py", "start": 720, "end": 721, "src": "def body_dofs(dim, body: Body):\n    return dim if body.kind == \"point\" else (3 if dim == 2 else 6)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/hfvc.py:check_goal_rank": {"file": "labs/hybrid_servoing/hfvc.py", "start": 278, "end": 286, "src": "def check_goal_rank(prob: HFVCProblem, C, who):\n    \"\"\"Raise Infeasible unless rank(R_C) = rows(C) and rank([J; C]) = rank([J; C; G]) (eq. 13).\"\"\"\n    C = _as2d(C, prob.n)\n    if C.shape[0] and svd_rank(C[:, prob.n_u:]) < C.shape[0]:\n        raise Infeasible(f\"{who}: the rows of C are linearly dependent\")\n    r1 = svd_rank(np.vstack([prob.J, C]))\n    r2 = svd_rank(np.vstack([prob.J, C, prob.G]))\n    if r1 != r2:\n        raise Infeasible(f\"{who}: goal inclusion fails, rank [J; C] = {r1} < rank [J; C; G] = {r2}\")\n", "doc": "Raise Infeasible unless rank(R_C) = rows(C) and rank([J; C]) = rank([J; C; G]) (eq. 13).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:complete_axes": {"file": "labs/hybrid_servoing/hfvc.py", "start": 289, "end": 295, "src": "def complete_axes(C, n_u):\n    \"\"\"R_a = [Null(R_C); R_C] with R_C the actuated columns of C (2019 eq. 16, 2021 eq. 27).\"\"\"\n    C = _as2d(C)\n    R_C = C[:, n_u:]\n    n_a = C.shape[1] - n_u\n    R_a = np.vstack([null_rows(R_C, n_a), R_C]) if R_C.shape[0] else np.eye(n_a)\n    return R_a, block_diag(np.eye(n_u), R_a)\n", "doc": "R_a = [Null(R_C); R_C] with R_C the actuated columns of C (2019 eq. 16, 2021 eq. 27).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:cond_rows": {"file": "labs/hybrid_servoing/hfvc.py", "start": 106, "end": 117, "src": "def cond_rows(A, rtol=1e-10):\n    \"\"\"2-norm condition number sigma_1 / sigma_k over all k = min(m, n) singular values.\n\n    2021 eq. 8 writes cond(A) = ||A|| ||A^+||, which equals this only when A has full rank; a\n    rank-deficient A gets inf here, as in the 'inf' entries of 2021 Fig. 1.\"\"\"\n    A = _as2d(A)\n    s = np.linalg.svd(A, compute_uv=False)\n    if s.size == 0 or s[0] == 0.0:\n        return math.inf\n    if s[-1] <= rtol * s[0]:\n        return math.inf\n    return float(s[0] / s[-1])\n", "doc": "2-norm condition number sigma_1 / sigma_k over all k = min(m, n) singular values.\n\n2021 eq. 8 writes cond(A) = ||A|| ||A^+||, which equals this only when A has full rank; a\nrank-deficient A gets inf here, as in the 'inf' entries of 2021 Fig. 1.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:cone_directions": {"file": "labs/hybrid_servoing/hfvc.py", "start": 752, "end": 760, "src": "def cone_directions(sides):\n    \"\"\"Unit tangent directions d_i = (sin(2 pi i / sides), cos(2 pi i / sides)), i = 1..sides.\n\n    2019 Sec. V-D uses sides = 8, d_i = [sin(pi i/4), cos(pi i/4), 0]; the constraints\n    d_i^T lambda_t <= mu lambda_n define the octagon that circumscribes the circle of radius\n    mu lambda_n (d_i are facet normals, not ridges), so tangential forces up to\n    mu / cos(pi/8) = 1.082 mu pass along the octagon's corners.\"\"\"\n    i = np.arange(1, sides + 1)\n    return np.stack([np.sin(2 * np.pi * i / sides), np.cos(2 * np.pi * i / sides)], axis=1)\n", "doc": "Unit tangent directions d_i = (sin(2 pi i / sides), cos(2 pi i / sides)), i = 1..sides.\n\n2019 Sec. V-D uses sides = 8, d_i = [sin(pi i/4), cos(pi i/4), 0]; the constraints\nd_i^T lambda_t <= mu lambda_n define the octagon that circumscribes the circle of radius\nmu lambda_n (d_i are facet normals, not ridges), so tangential forces up to\nmu / cos(pi/8) = 1.082 mu pass along the octagon's corners.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:contact_frame": {"file": "labs/hybrid_servoing/hfvc.py", "start": 743, "end": 749, "src": "def contact_frame(dim, n):\n    \"\"\"Rows: the normal, then the tangent(s).\"\"\"\n    n = np.asarray(n, float) / np.linalg.norm(n)\n    if dim == 2:\n        return np.array([n, [-n[1], n[0]]])\n    t1, t2 = tangent_basis(n)\n    return np.array([n, t1, t2])\n", "doc": "Rows: the normal, then the tangent(s).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:contact_system": {"file": "labs/hybrid_servoing/hfvc.py", "start": 763, "end": 828, "src": "def contact_system(dim, bodies, contacts, n_u, F, G, b_G, cone_sides=8, name=\"\", info=None):\n    \"\"\"Assemble J, J', the guard rows and the problem for a list of bodies and contacts.\n\n    Coordinates: bodies in order (body 0 first); the first n_u coordinates are unactuated.\n    lambda: per contact its frame components (normal first), then one friction component per\n    sliding contact with mu_slide > 0 (appended last, like the authors' J_phi 'all').\"\"\"\n    offs = np.cumsum([0] + [body_dofs(dim, b) for b in bodies])\n    n = int(offs[-1])\n    rows, frows, lam_of, fric = [], [], [], []\n    for ci, c in enumerate(contacts):\n        fr = contact_frame(dim, c.n)\n        dirs = fr if c.mode == \"stick\" else fr[:1]\n\n        def vel_row(d, c=c):\n            r = np.zeros(n)\n            Vb = point_velocity_map(dim, bodies[c.b], c.p)\n            r[offs[c.b]:offs[c.b + 1]] += d @ Vb\n            if c.a is not None:\n                Va = point_velocity_map(dim, bodies[c.a], c.p)\n                r[offs[c.a]:offs[c.a + 1]] -= d @ Va\n            return r\n\n        idx = []\n        for d in dirs:\n            idx.append(len(rows))\n            rows.append(vel_row(d))\n        lam_of.append(idx)\n        if c.mode == \"slide\" and c.mu_slide > 0:\n            fric.append((ci, vel_row(np.asarray(c.slide_dir, float))))\n    J = np.array(rows) if rows else np.zeros((0, n))\n    m0 = J.shape[0]\n    J_force = np.vstack([J] + [r[None, :] for _, r in fric]) if fric else J.copy()\n    m = J_force.shape[0]\n    Lam, bL, Gam, bG = [], [], [], []\n    D = cone_directions(cone_sides) if dim == 3 else None\n    for ci, c in enumerate(contacts):\n        idx = lam_of[ci]\n        row = np.zeros(m + n)\n        row[idx[0]] = -1.0\n        Lam.append(row)\n        bL.append(-c.n_min)\n        if c.mode == \"stick\":\n            if dim == 2:\n                for s in (1.0, -1.0):\n                    row = np.zeros(m + n)\n                    row[idx[1]], row[idx[0]] = s, -c.mu\n                    Lam.append(row)\n                    bL.append(0.0)\n            else:\n                for d in D:\n                    row = np.zeros(m + n)\n                    row[idx[1]], row[idx[2]], row[idx[0]] = d[0], d[1], -c.mu\n                    Lam.append(row)\n                    bL.append(0.0)\n    for k, (ci, _) in enumerate(fric):\n        row = np.zeros(m + n)\n        row[m0 + k] = 1.0  # friction on b along slide_dir equals -mu_slide * lambda_n\n        row[lam_of[ci][0]] = contacts[ci].mu_slide\n        Gam.append(row)\n        bG.append(0.0)\n    return HFVCProblem(\n        J, n_u, G, b_G, F, J_force,\n        np.array(Lam) if Lam else None, np.array(bL) if bL else None,\n        np.array(Gam) if Gam else None, np.array(bG) if bG else None,\n        name, dict(info or {}, dim=dim, bodies=bodies, contacts=contacts, lam_of=lam_of),\n    )\n", "doc": "Assemble J, J', the guard rows and the problem for a list of bodies and contacts.\n\nCoordinates: bodies in order (body 0 first); the first n_u coordinates are unactuated.\nlambda: per contact its frame components (normal first), then one friction component per\nsliding contact with mu_slide > 0 (appended last, like the authors' J_phi 'all').", "marimo": false},
"labs/hybrid_servoing/hfvc.py:crash_bound": {"file": "labs/hybrid_servoing/hfvc.py", "start": 366, "end": 388, "src": "def crash_bound(prob: HFVCProblem):\n    \"\"\"The smallest crashing index any goal-inclusive C with n_av = r_NG - r_N rows can have.\n\n    For a C with orthonormal rows spanning W, the singular values of [J_hat; C] are 1 and\n    sqrt(1 +- cos theta_i), theta_i the principal angles between W and ROW(J), so the crashing\n    index is sqrt((1 + c) / (1 - c)) with c = cos(smallest angle). A unit row w of S has\n    NULL(J) component |P_N w|^2 = k^T M k (w = B_c k), so the best W is the span of the top n_av\n    eigenvectors of M (Courant-Fischer) and c^2 = 1 - lambda_{n_av}(M). OCHS attains this bound:\n    S splits orthogonally into span(U_bar) \u2229 ROW([J; G]), where M is positive definite, and\n    {c_u = 0} \u2229 ROW(J), where M vanishes. Returns (bound, eigenvalues of M in decreasing order,\n    B_c times the top n_av eigenvectors, as rows).\"\"\"\n    b = alg1_basis(prob, check=False)\n    n_av = b[\"n_av\"]\n    lam, V = np.linalg.eigh(b[\"M\"])\n    lam, V = lam[::-1], V[:, ::-1]\n    if n_av == 0:\n        return 1.0, lam, np.zeros((0, prob.n))\n    if n_av > lam.size:\n        return math.inf, lam, np.zeros((0, prob.n))\n    c2 = min(max(1.0 - lam[n_av - 1], 0.0), 1.0)\n    c = math.sqrt(c2)\n    bound = math.inf if 1.0 - c <= 1e-15 else math.sqrt((1.0 + c) / (1.0 - c))\n    return bound, lam, (b[\"Bc\"] @ V[:, :n_av]).T\n", "doc": "The smallest crashing index any goal-inclusive C with n_av = r_NG - r_N rows can have.\n\nFor a C with orthonormal rows spanning W, the singular values of [J_hat; C] are 1 and\nsqrt(1 +- cos theta_i), theta_i the principal angles between W and ROW(J), so the crashing\nindex is sqrt((1 + c) / (1 - c)) with c = cos(smallest angle). A unit row w of S has\nNULL(J) component |P_N w|^2 = k^T M k (w = B_c k), so the best W is the span of the top n_av\neigenvectors of M (Courant-Fischer) and c^2 = 1 - lambda_{n_av}(M). OCHS attains this bound:\nS splits orthogonally into span(U_bar) \u2229 ROW([J; G]), where M is positive definite, and\n{c_u = 0} \u2229 ROW(J), where M vanishes. Returns (bound, eigenvalues of M in decreasing order,\nB_c times the top n_av eigenvectors, as rows).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:crashing_index": {"file": "labs/hybrid_servoing/hfvc.py", "start": 208, "end": 214, "src": "def crashing_index(J, C):\n    \"\"\"cond([J_hat; C_hat]): J_hat = orthonormal rows spanning ROW(J), C_hat = C with unit rows.\n\n    Large when a velocity-controlled direction is nearly a combination of the constraint rows\n    (the robot would push against a natural constraint); inf when it is exactly one.\"\"\"\n    C = _as2d(C, _as2d(J).shape[1])\n    return cond_rows(np.vstack([row_rows(J), normalize_rows(C)]))\n", "doc": "cond([J_hat; C_hat]): J_hat = orthonormal rows spanning ROW(J), C_hat = C with unit rows.\n\nLarge when a velocity-controlled direction is nearly a combination of the constraint rows\n(the robot would push against a natural constraint); inf when it is exactly one.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:dRp_dq": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1024, "end": 1030, "src": "def dRp_dq(q, p):\n    \"\"\"d(R(q) p)/dq, 3 x 4, from R(q) p = (w^2 - u.u) p + 2 (u.p) u + 2 w (u x p), q = [w; u].\"\"\"\n    w, u = q[0], np.asarray(q[1:])\n    p = np.asarray(p, float)\n    d_w = 2 * w * p + 2 * np.cross(u, p)\n    d_u = 2 * (u @ p) * np.eye(3) + 2 * np.outer(u, p) - 2 * np.outer(p, u) - 2 * w * skew(p)\n    return np.hstack([d_w[:, None], d_u])\n", "doc": "d(R(q) p)/dq, 3 x 4, from R(q) p = (w^2 - u.u) p + 2 (u.p) u + 2 w (u x p), q = [w; u].", "marimo": false},
"labs/hybrid_servoing/hfvc.py:drawer_crashing_index": {"file": "labs/hybrid_servoing/hfvc.py", "start": 920, "end": 925, "src": "def drawer_crashing_index(theta_deg):\n    \"\"\"Crashing index of the drawer with the finger in the loop: Fig. 1 top row, V at angle theta\n    above the rail direction. Equals sqrt((1 + c) / (1 - c)) with c^2 = (1 + sin^2 theta) / 2.\"\"\"\n    th = math.radians(theta_deg)\n    C = np.array([[0.0, 0.0, 0.0, math.cos(th), math.sin(th)]])\n    return crashing_index(fig1_problem(\"ground\").J, C)\n", "doc": "Crashing index of the drawer with the finger in the loop: Fig. 1 top row, V at angle theta\nabove the rail direction. Equals sqrt((1 + c) / (1 - c)) with c^2 = (1 + sin^2 theta) / 2.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:drawer_system": {"file": "labs/hybrid_servoing/hfvc.py", "start": 901, "end": 917, "src": "def drawer_system(theta_deg, eps_deg=0.0, b=1.0):\n    \"\"\"The drawer of deck 02 (slide drawer-setup): v = (vx, vy) of a drawer on a rail along x.\n\n    Natural constraint n^T v = 0 with the true rail normal n = (-sin eps, cos eps) (the model\n    assumes eps = 0); velocity command c^T v = b with c = (cos theta, sin theta). Returns the\n    condition number of the modelled system [n0; c] (= tan(45 deg + theta / 2)), the speed along\n    the rail the model predicts (b / cos theta) and the true one (b / cos(theta - eps)), and\n    whether the true system is consistent (it is not when theta - eps = 90 deg).\"\"\"\n    th, ep = math.radians(theta_deg), math.radians(eps_deg)\n    c = np.array([math.cos(th), math.sin(th)])\n    A_model = np.array([[0.0, 1.0], c])\n    A_true = np.array([[-math.sin(ep), math.cos(ep)], c])\n    s_true = abs(math.cos(th - ep))\n    feasible = s_true > 1e-12\n    return dict(cond=cond_rows(A_model), speed_model=b / math.cos(th) if math.cos(th) else math.inf,\n                speed_true=b / math.cos(th - ep) if feasible else math.inf, feasible=feasible,\n                v_true=np.linalg.solve(A_true, [0.0, b]) if feasible else None)\n", "doc": "The drawer of deck 02 (slide drawer-setup): v = (vx, vy) of a drawer on a rail along x.\n\nNatural constraint n^T v = 0 with the true rail normal n = (-sin eps, cos eps) (the model\nassumes eps = 0); velocity command c^T v = b with c = (cos theta, sin theta). Returns the\ncondition number of the modelled system [n0; c] (= tan(45 deg + theta / 2)), the speed along\nthe rail the model predicts (b / cos theta) and the true one (b / cos(theta - eps)), and\nwhether the true system is consistent (it is not when theta - eps = 90 deg).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:fig1_C": {"file": "labs/hybrid_servoing/hfvc.py", "start": 882, "end": 886, "src": "def fig1_C(direction, phi_deg=FIG1_PHI_DEG):\n    \"\"\"The velocity-controlled row of Fig. 1: finger velocity to the right, diagonal, or down.\"\"\"\n    a = math.radians(phi_deg)\n    d = {\"right\": (1.0, 0.0), \"diag\": (math.cos(a), -math.sin(a)), \"down\": (0.0, -1.0)}[direction]\n    return np.array([[0.0, 0.0, 0.0, d[0], d[1]]])\n", "doc": "The velocity-controlled row of Fig. 1: finger velocity to the right, diagonal, or down.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:fig1_fit": {"file": "labs/hybrid_servoing/hfvc.py", "start": 928, "end": 941, "src": "def fig1_fit():\n    \"\"\"Fit (phi, h) to the printed 3.87, 7.10 and 10.48 by least squares; also return the exact\n    one-parameter solutions (phi from 3.87 alone, h from 7.10 alone) and the 45-degree value.\"\"\"\n    def ci(support, direction, phi, h):\n        return crashing_index(fig1_problem(support, h=h).J, fig1_C(direction, phi))\n\n    phi_only = brentq(lambda p: ci(\"ground\", \"diag\", p, 1.0) - 3.87, 45.0, 60.0)\n    h_only = brentq(lambda hh: ci(\"pivot\", \"right\", 45.0, hh) - 7.10, 0.05, 1.0)\n    res = least_squares(lambda x: [ci(\"ground\", \"diag\", x[0], x[1]) - 3.87,\n                                   ci(\"pivot\", \"right\", x[0], x[1]) - 7.10,\n                                   ci(\"pivot\", \"diag\", x[0], x[1]) - 10.48], x0=[46.8, 0.29])\n    return dict(phi_deg=float(res.x[0]), h=float(res.x[1]), residuals=res.fun.tolist(),\n                phi_from_387=phi_only, h_from_710=h_only,\n                ground_diag_at_45=ci(\"ground\", \"diag\", 45.0, 1.0))\n", "doc": "Fit (phi, h) to the printed 3.87, 7.10 and 10.48 by least squares; also return the exact\none-parameter solutions (phi from 3.87 alone, h from 7.10 alone) and the 45-degree value.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:fig1_problem": {"file": "labs/hybrid_servoing/hfvc.py", "start": 855, "end": 879, "src": "def fig1_problem(support=\"ground\", h=FIG1_H, w=None, weight=1.0, mu_finger=0.8, mu_ground=0.3,\n                 n_min=0.1, speed=0.1):\n    \"\"\"Planar block of height h and width w (default w = h) with a point finger on its top centre.\n\n    support='ground': the block slides right on the ground, Coulomb friction mu_ground at both\n    corners (J' and Gam rows); goal: block vx = speed. support='pivot': the block sticks on a\n    pivot under its bottom centre; goal: omega = -speed / h (the finger moves right at `speed`).\"\"\"\n    w = h if w is None else w\n    bodies = [Body(np.array([0.0, 0.0])), Body(np.array([0.0, h / 2]), \"point\")]\n    top = Contact(np.array([0.0, h / 2]), np.array([0.0, -1.0]), b=0, a=1, mode=\"stick\",\n                  mu=mu_finger, n_min=n_min)\n    if support == \"ground\":\n        env = [Contact(np.array([s * w / 2, -h / 2]), np.array([0.0, 1.0]), b=0, a=None,\n                       mode=\"slide\", n_min=0.0, mu_slide=mu_ground, slide_dir=np.array([1.0, 0.0]))\n               for s in (-1, 1)]\n        G, b_G = np.array([[1.0, 0, 0, 0, 0]]), np.array([speed])\n    elif support == \"pivot\":\n        env = [Contact(np.array([0.0, -h / 2]), np.array([0.0, 1.0]), b=0, a=None, mode=\"stick\",\n                       mu=1.0, n_min=0.0)]\n        G, b_G = np.array([[0.0, 0, 1, 0, 0]]), np.array([-speed / h])\n    else:\n        raise ValueError(support)\n    F = np.array([0.0, -weight, 0.0, 0.0, 0.0])\n    return contact_system(2, bodies, [top] + env, 3, F, G, b_G, name=f\"fig1-{support}\",\n                          info=dict(h=h, w=w))\n", "doc": "Planar block of height h and width w (default w = h) with a point finger on its top centre.\n\nsupport='ground': the block slides right on the ground, Coulomb friction mu_ground at both\ncorners (J' and Gam rows); goal: block vx = speed. support='pivot': the block sticks on a\npivot under its bottom centre; goal: omega = -speed / h (the finger moves right at `speed`).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:fig1_table": {"file": "labs/hybrid_servoing/hfvc.py", "start": 889, "end": 898, "src": "def fig1_table(phi_deg=FIG1_PHI_DEG, h=FIG1_H):\n    \"\"\"The six crashing indexes of 2021 Fig. 1 from the reconstruction, next to the paper's.\"\"\"\n    out = []\n    for support in (\"ground\", \"pivot\"):\n        J = fig1_problem(support, h=h).J\n        for direction in (\"right\", \"diag\", \"down\"):\n            out.append(dict(support=support, direction=direction,\n                            ours=crashing_index(J, fig1_C(direction, phi_deg)),\n                            paper=FIG1_PAPER[(support, direction)]))\n    return out\n", "doc": "The six crashing indexes of 2021 Fig. 1 from the reconstruction, next to the paper's.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:goal_inclusion": {"file": "labs/hybrid_servoing/hfvc.py", "start": 231, "end": 251, "src": "def goal_inclusion(J, G, b_G, C, b_C, samples=20, tol=1e-7, rng=0):\n    \"\"\"Check both goal-inclusion conditions of 2021 Sec. V for a velocity command C v = b_C.\"\"\"\n    J = _as2d(J)\n    n = J.shape[1]\n    G, C = _as2d(G, n), _as2d(C, n)\n    b_G, b_C = np.atleast_1d(b_G).astype(float), np.atleast_1d(b_C).astype(float)\n    JC, JCG = np.vstack([J, C]), np.vstack([J, C, G])\n    r1, r2 = svd_rank(JC), svd_rank(JCG)\n    A = JCG\n    b = np.concatenate([np.zeros(J.shape[0]), b_C, b_G])\n    _, res = special_solution(A, b)\n    scale = 1.0 + np.linalg.norm(b)\n    # every solution of the command system = particular solution + NULL([J;C])\n    vp, res_c = special_solution(JC, np.concatenate([np.zeros(J.shape[0]), b_C]))\n    Z = null_rows(JC)\n    gen = np.random.default_rng(rng)\n    err = 0.0\n    for _ in range(samples):\n        v = vp + Z.T @ gen.standard_normal(Z.shape[0]) if Z.shape[0] else vp\n        err = max(err, float(np.max(np.abs(G @ v - b_G))) if G.shape[0] else 0.0)\n    return GoalInclusion(r1 == r2, res <= tol * scale, r1, r2, res, err)\n", "doc": "Check both goal-inclusion conditions of 2021 Sec. V for a velocity command C v = b_C.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:guard_violation": {"file": "labs/hybrid_servoing/hfvc.py", "start": 192, "end": 200, "src": "def guard_violation(prob: HFVCProblem, lam, f):\n    \"\"\"Largest violation of the guard conditions (0 when every row holds).\"\"\"\n    x = np.concatenate([lam, f])\n    viol = 0.0\n    if prob.Lam.shape[0]:\n        viol = max(viol, float(np.max(prob.Lam @ x - prob.b_Lam)))\n    if prob.Gam.shape[0]:\n        viol = max(viol, float(np.max(np.abs(prob.Gam @ x - prob.b_Gam))))\n    return max(viol, 0.0)\n", "doc": "Largest violation of the guard conditions (0 when every row holds).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:interior_force": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1193, "end": 1204, "src": "def interior_force(prob: HFVCProblem, rng):\n    \"\"\"A contact force strictly inside the friction-cone and normal-force guards of a\n    contact_system problem: normal n_min + U[1, 2], tangential at most half of mu * normal.\"\"\"\n    dim, contacts, lam_of = prob.info[\"dim\"], prob.info[\"contacts\"], prob.info[\"lam_of\"]\n    lam = np.zeros(prob.n_lam)\n    for c, idx in zip(contacts, lam_of):\n        ln = c.n_min + rng.uniform(1.0, 2.0)\n        lam[idx[0]] = ln\n        if c.mode == \"stick\":\n            t = _unit(rng, dim - 1) if dim == 3 else np.array([rng.choice([-1.0, 1.0])])\n            lam[idx[1:]] = rng.uniform(0.0, 0.5) * c.mu * ln * t\n    return lam\n", "doc": "A contact force strictly inside the friction-cone and normal-force guards of a\ncontact_system problem: normal n_min + U[1, 2], tangential at most half of mu * normal.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:least_distance": {"file": "labs/hybrid_servoing/hfvc.py", "start": 637, "end": 675, "src": "def least_distance(A_ub, b_ub, E=None, e=None, feas_tol=1e-7):\n    \"\"\"Minimum-norm point of a polyhedron (Lawson and Hanson, Solving Least Squares Problems,\n    ch. 23, algorithm LDP). Equalities are removed first: x = x0 + Z y with x0 the minimum-norm\n    solution of E x = e and Z an orthonormal basis of NULL(E), so ||x||^2 = ||x0||^2 + ||y||^2.\n    Then min ||y|| s.t. Gm y >= h is solved by one NNLS: E' = [Gm^T; h^T], f = e_last,\n    u = argmin ||E'u - f|| (u >= 0), r = E'u - f, y = -r[:k] / r[k]. Returns (x, feasible).\"\"\"\n    A_ub = np.atleast_2d(np.asarray(A_ub, float))\n    n = A_ub.shape[1] if A_ub.size else (np.atleast_2d(E).shape[1])\n    b_ub = np.asarray(b_ub, float).reshape(-1)\n    if E is not None and np.size(E):\n        E = np.atleast_2d(np.asarray(E, float))\n        e = np.asarray(e, float).reshape(-1)\n        x0, res = special_solution(E, e)\n        if res > feas_tol * (1 + np.linalg.norm(e)):\n            return x0, False\n        Z = null_rows(E, n).T\n    else:\n        x0, Z = np.zeros(n), np.eye(n)\n    k = Z.shape[1]\n    if A_ub.shape[0] == 0 or A_ub.size == 0:\n        return x0, True\n    Gm = -A_ub @ Z\n    h = -(b_ub - A_ub @ x0)\n    if k == 0:\n        return x0, bool(np.all(Gm.shape[0] == 0 or h <= feas_tol))\n    # scale rows so NNLS works on unit-size numbers\n    s = np.maximum(np.linalg.norm(np.hstack([Gm, h[:, None]]), axis=1), 1e-300)\n    Gs, hs = Gm / s[:, None], h / s\n    Ep = np.vstack([Gs.T, hs[None, :]])\n    fp = np.zeros(k + 1)\n    fp[-1] = 1.0\n    u, _ = nnls(Ep, fp, maxiter=50 * (Ep.shape[1] + 10))\n    r = Ep @ u - fp\n    if np.linalg.norm(r) < 1e-12 or abs(r[-1]) < 1e-12:\n        return x0, False\n    y = -r[:k] / r[-1]\n    x = x0 + Z @ y\n    ok = bool(np.all(A_ub @ x - b_ub <= feas_tol * (1 + np.abs(b_ub))))\n    return x, ok\n", "doc": "Minimum-norm point of a polyhedron (Lawson and Hanson, Solving Least Squares Problems,\nch. 23, algorithm LDP). Equalities are removed first: x = x0 + Z y with x0 the minimum-norm\nsolution of E x = e and Z an orthonormal basis of NULL(E), so ||x||^2 = ||x0||^2 + ||y||^2.\nThen min ||y|| s.t. Gm y >= h is solved by one NNLS: E' = [Gm^T; h^T], f = e_last,\nu = argmin ||E'u - f|| (u >= 0), r = E'u - f, y = -r[:k] / r[k]. Returns (x, feasible).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:newton_residual": {"file": "labs/hybrid_servoing/hfvc.py", "start": 187, "end": 189, "src": "def newton_residual(prob: HFVCProblem, lam, f):\n    \"\"\"Norm of J'^T lam + f + F (quasi-static Newton law, 2019 eq. 5).\"\"\"\n    return float(np.linalg.norm(prob.J_force.T @ lam + f + prob.F))\n", "doc": "Norm of J'^T lam + f + F (quasi-static Newton law, 2019 eq. 5).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:normalize_rows": {"file": "labs/hybrid_servoing/hfvc.py", "start": 99, "end": 103, "src": "def normalize_rows(A):\n    \"\"\"Each row divided by its 2-norm (2021 'C hat'); zero rows stay zero.\"\"\"\n    A = _as2d(A)\n    nr = np.linalg.norm(A, axis=1, keepdims=True)\n    return np.divide(A, nr, out=np.zeros_like(A), where=nr > 0)\n", "doc": "Each row divided by its 2-norm (2021 'C hat'); zero rows stay zero.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:null_rows": {"file": "labs/hybrid_servoing/hfvc.py", "start": 78, "end": 87, "src": "def null_rows(A, n=None, rtol=RTOL, atol=ATOL):\n    \"\"\"Matrix whose rows are an orthonormal basis of NULL(A); shape (n - rank A, n).\n\n    A matrix with no rows constrains nothing, so its null space is all of R^n (pass n).\"\"\"\n    A = _as2d(A, n)\n    n = A.shape[1] if n is None else n\n    if A.shape[0] == 0:\n        return np.eye(n)\n    _, s, Vt = np.linalg.svd(A, full_matrices=True)\n    return Vt[_rank_from_sv(s, rtol, atol):].copy()\n", "doc": "Matrix whose rows are an orthonormal basis of NULL(A); shape (n - rank A, n).\n\nA matrix with no rows constrains nothing, so its null space is all of R^n (pass n).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:ochs_force": {"file": "labs/hybrid_servoing/hfvc.py", "start": 610, "end": 629, "src": "def ochs_force(prob: HFVCProblem, vel: VelocityControl):\n    \"\"\"2021 eq. 30: min lam^T lam + eta_a^T eta_a s.t. Newton (eq. 3) and the guards (eq. 4).\n\n    Unknowns x = [lam; eta_a] with eta_u = 0 and f = T^-1 [0; eta_a]; solved exactly as a\n    least-distance problem (section 7). eta_af is the first n_af entries of eta_a.\"\"\"\n    m, n, n_u = prob.n_lam, prob.n, prob.n_u\n    Tinv = np.linalg.inv(vel.T)\n    Ta = Tinv[:, n_u:]  # f = Ta eta_a\n    E_eq = np.hstack([prob.J_force.T, Ta])\n    e_eq = -prob.F\n    if prob.Gam.shape[0]:\n        E_eq = np.vstack([E_eq, np.hstack([prob.Gam[:, :m], prob.Gam[:, m:] @ Ta])])\n        e_eq = np.concatenate([e_eq, prob.b_Gam])\n    A_ub = np.hstack([prob.Lam[:, :m], prob.Lam[:, m:] @ Ta])\n    x, ok = least_distance(A_ub, prob.b_Lam, E_eq, e_eq)\n    if not ok:\n        raise Infeasible(\"OCHS force QP (eq. 30) infeasible\")\n    lam, eta_a = x[:m], x[m:]\n    eta = np.concatenate([np.zeros(n_u), eta_a])\n    return ForceControl(eta_a[: vel.n_af], lam, eta, Tinv @ eta, \"ochs-qp\")\n", "doc": "2021 eq. 30: min lam^T lam + eta_a^T eta_a s.t. Newton (eq. 3) and the guards (eq. 4).\n\nUnknowns x = [lam; eta_a] with eta_u = 0 and f = T^-1 [0; eta_a]; solved exactly as a\nleast-distance problem (section 7). eta_af is the first n_af entries of eta_a.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:ochs_velocity": {"file": "labs/hybrid_servoing/hfvc.py", "start": 572, "end": 607, "src": "def ochs_velocity(prob: HFVCProblem, maximal=False):\n    \"\"\"2021 Algorithm 1 lines 1-13 (Optimally-Conditioned Hybrid Servoing).\n\n    U = Null(J) (eq. 14); U_bar = Row(U S_a) (eq. 15); n_av from eq. 21 (or eq. 19 when\n    maximal); K = Null(Null([J;G]) U_bar^T) (eq. 24, row-basis form); C = K U_bar (eq. 22);\n    R_a from eq. 27; v* from eq. 28; w_av = C v* (eq. 29).\"\"\"\n    J, G, n, n_u = prob.J, prob.G, prob.n, prob.n_u\n    U = null_rows(J, n)\n    US = U.copy()\n    US[:, :n_u] = 0.0\n    Ubar = row_rows(US)\n    r_J, r_JG = svd_rank(J), svd_rank(np.vstack([J, G]))\n    n_min = r_JG - r_J\n    if Ubar.shape[0] < n_min:  # eq. 18\n        raise Infeasible(f\"eq. 18 fails: rows(U_bar) = {Ubar.shape[0]} < {n_min}\")\n    info = dict(U=U, Ubar=Ubar, r_J=r_J, r_JG=r_JG)\n    if maximal:\n        n_av, C = Ubar.shape[0], Ubar\n        check_goal_rank(prob, C, \"OCHS(M), eq. 13\")\n    else:\n        n_av = n_min\n        Z = null_rows(np.vstack([J, G]), n)\n        K = null_rows(Z @ Ubar.T, Ubar.shape[0])  # eq. 24\n        info[\"K\"], info[\"Z\"] = K, Z\n        # rows(K) = dim(span(U_bar) \u2229 ROW([J; G])) <= n_av always, because span(U_bar) meets\n        # ROW(J) only at 0; eq. 25 therefore holds with equality whenever it holds.\n        if K.shape[0] < n_av:  # eq. 25\n            raise Infeasible(f\"eq. 25 fails: rows(K) = {K.shape[0]} < n_av = {n_av}\")\n        C = K[:n_av] @ Ubar\n        check_goal_rank(prob, C, \"OCHS\")  # holds by construction; kept as a safeguard\n    R_a, T = complete_axes(C, n_u)\n    v_star, res = special_solution(np.vstack([J, G]), np.concatenate([np.zeros(J.shape[0]), prob.b_G]))\n    if res > 1e-7 * (1 + np.linalg.norm(prob.b_G)):\n        raise Infeasible(f\"eq. 28 has no solution (residual {res:.2e})\")\n    return VelocityControl(n_av, n - n_u - n_av, C, R_a, T, C @ v_star, v_star,\n                           \"ochs(M)\" if maximal else \"ochs\", info)\n", "doc": "2021 Algorithm 1 lines 1-13 (Optimally-Conditioned Hybrid Servoing).\n\nU = Null(J) (eq. 14); U_bar = Row(U S_a) (eq. 15); n_av from eq. 21 (or eq. 19 when\nmaximal); K = Null(Null([J;G]) U_bar^T) (eq. 24, row-basis form); C = K U_bar (eq. 22);\nR_a from eq. 27; v* from eq. 28; w_av = C v* (eq. 29).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:point_velocity_map": {"file": "labs/hybrid_servoing/hfvc.py", "start": 724, "end": 731, "src": "def point_velocity_map(dim, body: Body, p):\n    \"\"\"Matrix V with (velocity of the material point of `body` at p) = V @ v_body.\"\"\"\n    if body.kind == \"point\":\n        return np.eye(dim)\n    r = np.asarray(p, float) - np.asarray(body.ref, float)\n    if dim == 2:\n        return np.array([[1.0, 0.0, -r[1]], [0.0, 1.0, r[0]]])\n    return np.hstack([np.eye(3), -skew(r)])\n", "doc": "Matrix V with (velocity of the material point of `body` at p) = V @ v_body.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:quat_integrate": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1014, "end": 1021, "src": "def quat_integrate(q, omega_body, dt):\n    \"\"\"q(t + dt) = q(t) exp(omega_body dt / 2): rotation by a body angular velocity.\"\"\"\n    th = np.linalg.norm(omega_body) * dt\n    if th == 0.0:\n        return np.asarray(q, float).copy()\n    axis = np.asarray(omega_body) / np.linalg.norm(omega_body)\n    dq = np.concatenate([[math.cos(th / 2)], math.sin(th / 2) * axis])\n    return quat_mul(q, dq)\n", "doc": "q(t + dt) = q(t) exp(omega_body dt / 2): rotation by a body angular velocity.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:quat_mul": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1007, "end": 1011, "src": "def quat_mul(a, b):\n    \"\"\"Hamilton product a b of quaternions [w, x, y, z].\"\"\"\n    aw, av = a[0], np.asarray(a[1:])\n    bw, bv = b[0], np.asarray(b[1:])\n    return np.concatenate([[aw * bw - av @ bv], aw * bv + bw * av + np.cross(av, bv)])\n", "doc": "Hamilton product a b of quaternions [w, x, y, z].", "marimo": false},
"labs/hybrid_servoing/hfvc.py:quat_to_R": {"file": "labs/hybrid_servoing/hfvc.py", "start": 997, "end": 1004, "src": "def quat_to_R(q):\n    \"\"\"Rotation matrix of a quaternion [w, x, y, z] (homogeneous form, exact for unit q).\"\"\"\n    w, x, y, z = q\n    return np.array([\n        [w * w + x * x - y * y - z * z, 2 * (x * y - w * z), 2 * (x * z + w * y)],\n        [2 * (x * y + w * z), w * w - x * x + y * y - z * z, 2 * (y * z - w * x)],\n        [2 * (x * z - w * y), 2 * (y * z + w * x), w * w - x * x - y * y + z * z],\n    ])\n", "doc": "Rotation matrix of a quaternion [w, x, y, z] (homogeneous form, exact for unit q).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:random_problem": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1207, "end": 1260, "src": "def random_problem(rng=None, dim=2, env=\"f\", hand=1, fingers=1, goal=\"min\", load=\"feasible\",\n                   weight=1.0, n_min_finger=0.1, cone_sides=8, max_tries=50):\n    \"\"\"One random HFVC problem of 2021 Table I (see the comment above for the distributions).\"\"\"\n    rng = np.random.default_rng(rng)\n    for _ in range(max_tries):\n        bodies = [Body(np.zeros(dim))]\n        contacts = []\n        for mode in env:\n            contacts.append(Contact(rng.uniform(-0.5, 0.5, dim), _unit(rng, dim, upper=True), b=0,\n                                    a=None, mode=\"stick\" if mode == \"f\" else \"slide\",\n                                    mu=rng.uniform(0.2, 1.0), n_min=0.0))\n        for k in range(fingers):\n            pts = [rng.uniform(-0.5, 0.5, dim) for _ in range(hand)]\n            bodies.append(Body(np.mean(pts, axis=0) + rng.uniform(-0.2, 0.2, dim)))\n            for p in pts:\n                contacts.append(Contact(p, _unit(rng, dim), b=0, a=1 + k, mode=\"stick\",\n                                        mu=rng.uniform(0.5, 1.2), n_min=n_min_finger))\n        n_u = 3 if dim == 2 else 6\n        base = contact_system(dim, bodies, contacts, n_u, None, np.zeros((0, 1)), np.zeros(0),\n                              cone_sides)\n        J, n = base.J, base.n\n        U = null_rows(J, n)\n        US = U.copy()\n        US[:, :n_u] = 0.0\n        Ubar = row_rows(US)\n        if Ubar.shape[0] == 0:\n            continue\n        if goal in (\"min\", \"max\"):\n            W0 = row_rows(Ubar @ U.T @ U)  # projection of ROW(U_bar) onto NULL(J)\n            nG = int(rng.integers(1, W0.shape[0] + 1)) if goal == \"min\" else W0.shape[0]\n            G = rng.standard_normal((nG, W0.shape[0])) @ W0\n            if J.shape[0]:\n                G = G + rng.standard_normal((nG, J.shape[0])) @ J\n        elif goal == \"object\":\n            Eu = np.hstack([np.eye(n_u), np.zeros((n_u, n - n_u))])\n            d = svd_rank(np.vstack([J, Eu])) - svd_rank(J)  # object DOF the contacts leave free\n            if d == 0:\n                continue\n            nG = int(rng.integers(1, d + 1))\n            G = rng.standard_normal((nG, n_u)) @ Eu\n        else:\n            raise ValueError(goal)\n        v_g = U.T @ rng.standard_normal(U.shape[0])\n        F = np.zeros(n)\n        if load == \"feasible\":\n            F[:n_u] = -(base.J_force.T @ interior_force(base, rng))[:n_u]\n        elif load == \"gravity\":\n            F[dim - 1] = -weight\n        else:\n            raise ValueError(load)\n        return contact_system(dim, bodies, contacts, n_u, F, G, G @ v_g, cone_sides,\n                              name=f\"{dim}d-{env}-{hand}x{fingers}-{goal}\",\n                              info=dict(env=env, hand=hand, fingers=fingers, goal=goal, load=load))\n    raise Locked(f\"{dim}D setting env={env}, {hand} contacts x {fingers} fingers: no free robot motion\")\n", "doc": "One random HFVC problem of 2021 Table I (see the comment above for the distributions).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:random_problems": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1263, "end": 1277, "src": "def random_problems(count, dim=2, goal=\"min\", seed=0, settings=None, load=\"feasible\"):\n    \"\"\"`count` problems cycling through the Table I settings, reproducible from `seed`.\n\n    Settings that lock every body (class Locked) are dropped from the cycle.\"\"\"\n    rng = np.random.default_rng(seed)\n    settings = list(settings or table1_settings(dim))\n    out, i = [], 0\n    while len(out) < count and settings:\n        s = settings[i % len(settings)]\n        try:\n            out.append(random_problem(rng, dim, *s, goal=goal, load=load))\n            i += 1\n        except Locked:\n            settings.remove(s)\n    return out\n", "doc": "`count` problems cycling through the Table I settings, reproducible from `seed`.\n\nSettings that lock every body (class Locked) are dropped from the cycle.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:random_valid_C": {"file": "labs/hybrid_servoing/hfvc.py", "start": 391, "end": 397, "src": "def random_valid_C(prob: HFVCProblem, rng=None, rows=None):\n    \"\"\"A random velocity-command matrix whose rows lie in S = span(B_c) (goal-inclusive for\n    almost every draw when rows = n_av): the search space shared by Algorithm 1 and OCHS.\"\"\"\n    rng = np.random.default_rng(rng)\n    b = alg1_basis(prob, check=False)\n    k = b[\"n_av\"] if rows is None else rows\n    return (b[\"Bc\"] @ rng.standard_normal((b[\"n_c\"], k))).T\n", "doc": "A random velocity-command matrix whose rows lie in S = span(B_c) (goal-inclusive for\nalmost every draw when rows = n_av): the search space shared by Algorithm 1 and OCHS.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:row_rows": {"file": "labs/hybrid_servoing/hfvc.py", "start": 90, "end": 96, "src": "def row_rows(A, rtol=RTOL, atol=ATOL):\n    \"\"\"Matrix whose rows are an orthonormal basis of ROW(A); shape (rank A, n).\"\"\"\n    A = _as2d(A)\n    if A.shape[0] == 0:\n        return np.zeros((0, A.shape[1]))\n    _, s, Vt = np.linalg.svd(A, full_matrices=False)\n    return Vt[:_rank_from_sv(s, rtol, atol)].copy()\n", "doc": "Matrix whose rows are an orthonormal basis of ROW(A); shape (rank A, n).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:skew": {"file": "labs/hybrid_servoing/hfvc.py", "start": 714, "end": 717, "src": "def skew(p):\n    \"\"\"[p]x, the matrix with [p]x w = p x w.\"\"\"\n    x, y, z = p\n    return np.array([[0.0, -z, y], [z, 0.0, -x], [-y, x, 0.0]])\n", "doc": "[p]x, the matrix with [p]x w = p x w.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:solve_hs": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1324, "end": 1331, "src": "def solve_hs(prob: HFVCProblem, Ns=3, rng=None, form=\"code\", t=10.0, iters=50, objective=\"l1\",\n             init=\"uniform\"):\n    \"\"\"The 2019 method (2021 calls it HS3 / HS10 by Ns): Algorithm 1, then Algorithm 2.\n\n    Defaults follow the authors' MATLAB (cost form 'code', t = 10, 50 iterations, U[0, 1)\n    starts); 2021 Sec. VI-B also runs 50 iterations per start.\"\"\"\n    return _solve(prob, f\"HS{Ns}\", lambda p: alg1_velocity(p, Ns, t, iters, form, rng, 0.0, init),\n                  lambda p, v: alg2_force(p, v, objective))\n", "doc": "The 2019 method (2021 calls it HS3 / HS10 by Ns): Algorithm 1, then Algorithm 2.\n\nDefaults follow the authors' MATLAB (cost form 'code', t = 10, 50 iterations, U[0, 1)\nstarts); 2021 Sec. VI-B also runs 50 iterations per start.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:solve_ochs": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1318, "end": 1321, "src": "def solve_ochs(prob: HFVCProblem, maximal=False):\n    \"\"\"OCHS (2021 Algorithm 1): closed-form velocity part, then the force QP of eq. 30.\"\"\"\n    return _solve(prob, \"OCHS(M)\" if maximal else \"OCHS\",\n                  lambda p: ochs_velocity(p, maximal), ochs_force)\n", "doc": "OCHS (2021 Algorithm 1): closed-form velocity part, then the force QP of eq. 30.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:special_solution": {"file": "labs/hybrid_servoing/hfvc.py", "start": 120, "end": 124, "src": "def special_solution(A, b):\n    \"\"\"One solution of A v = b (least squares, minimum norm) and its residual norm.\"\"\"\n    A = _as2d(A)\n    v, *_ = np.linalg.lstsq(A, np.asarray(b, float), rcond=None)\n    return v, float(np.linalg.norm(A @ v - b))\n", "doc": "One solution of A v = b (least squares, minimum norm) and its residual norm.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:stopwatch": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1334, "end": 1342, "src": "@contextmanager\ndef stopwatch():\n    \"\"\"with stopwatch() as sw: ...; then sw['s'] holds the elapsed seconds.\"\"\"\n    sw = {}\n    t0 = time.perf_counter()\n    try:\n        yield sw\n    finally:\n        sw[\"s\"] = time.perf_counter() - t0\n", "doc": "with stopwatch() as sw: ...; then sw['s'] holds the elapsed seconds.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:svd_rank": {"file": "labs/hybrid_servoing/hfvc.py", "start": 70, "end": 75, "src": "def svd_rank(A, rtol=RTOL, atol=ATOL):\n    \"\"\"Numerical rank: the number of singular values above max(rtol * sigma_max, atol).\"\"\"\n    A = _as2d(A)\n    if A.size == 0:\n        return 0\n    return _rank_from_sv(np.linalg.svd(A, compute_uv=False), rtol, atol)\n", "doc": "Numerical rank: the number of singular values above max(rtol * sigma_max, atol).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:table1_settings": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1179, "end": 1182, "src": "def table1_settings(dim):\n    \"\"\"All (env, contacts per finger, fingers) settings of 2021 Table I for dim = 2 or 3.\"\"\"\n    t = TABLE1[dim]\n    return [(e, h, k) for e in t[\"env\"] for h in t[\"hand\"] for k in t[\"fingers\"]]\n", "doc": "All (env, contacts per finger, fingers) settings of 2021 Table I for dim = 2 or 3.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:table2": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1355, "end": 1374, "src": "def table2(problems, solvers, ill=100.0):\n    \"\"\"Table II-style summary: for each named solver (name -> fn(prob) -> HFVCSolution) the\n    number solved, mean and median crashing index over solved problems, the number with crashing index\n    above `ill` (our threshold; 2021 does not state one), and mean / worst velocity and force\n    times in ms. Also returns the per-problem solutions.\"\"\"\n    per = {name: [fn(p) for p in problems] for name, fn in solvers.items()}\n    rows = {}\n    for name, sols in per.items():\n        ok = [s for s in sols if s.ok]\n        cr = np.array([s.crash for s in ok if s.vel.n_av > 0])\n        tv = np.array([s.t_vel for s in sols]) * 1e3\n        tf = np.array([s.t_force for s in ok]) * 1e3\n        rows[name] = dict(total=len(sols), solved=len(ok),\n                          mean_crash=float(np.mean(cr[np.isfinite(cr)])) if cr.size else math.nan,\n                          median_crash=float(np.median(cr)) if cr.size else math.nan,\n                          ill=int(np.sum(cr > ill)), t_vel_mean=float(np.mean(tv)),\n                          t_vel_worst=float(np.max(tv)),\n                          t_force_mean=float(np.mean(tf)) if tf.size else math.nan,\n                          t_force_worst=float(np.max(tf)) if tf.size else math.nan)\n    return rows, per\n", "doc": "Table II-style summary: for each named solver (name -> fn(prob) -> HFVCSolution) the\nnumber solved, mean and median crashing index over solved problems, the number with crashing index\nabove `ill` (our threshold; 2021 does not state one), and mean / worst velocity and force\ntimes in ms. Also returns the per-problem solutions.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:tangent_basis": {"file": "labs/hybrid_servoing/hfvc.py", "start": 734, "end": 740, "src": "def tangent_basis(n):\n    \"\"\"Two unit tangents t1, t2 with (n, t1, t2) right-handed and orthonormal.\"\"\"\n    n = np.asarray(n, float) / np.linalg.norm(n)\n    a = np.array([1.0, 0.0, 0.0]) if abs(n[0]) < 0.9 else np.array([0.0, 1.0, 0.0])\n    t1 = np.cross(n, a)\n    t1 /= np.linalg.norm(t1)\n    return t1, np.cross(n, t1)\n", "doc": "Two unit tangents t1, t2 with (n, t1, t2) right-handed and orthonormal.", "marimo": false},
"labs/hybrid_servoing/hfvc.py:time_call": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1345, "end": 1352, "src": "def time_call(fn, *args, repeat=1, **kwargs):\n    \"\"\"(result of the last call, fastest wall time in seconds over `repeat` calls).\"\"\"\n    best, out = math.inf, None\n    for _ in range(repeat):\n        t0 = time.perf_counter()\n        out = fn(*args, **kwargs)\n        best = min(best, time.perf_counter() - t0)\n    return out, best\n", "doc": "(result of the last call, fastest wall time in seconds over `repeat` calls).", "marimo": false},
"labs/hybrid_servoing/hfvc.py:world_commands": {"file": "labs/hybrid_servoing/hfvc.py", "start": 1127, "end": 1134, "src": "def world_commands(vel: VelocityControl, force: Optional[ForceControl], n_u):\n    \"\"\"World-frame (actuated-coordinate) velocity and force commands, as the authors' code\n    prints them: R_a^-1 [0; w_av] and R_a^-1 [eta_af; 0].\"\"\"\n    Rinv = np.linalg.inv(vel.R_a)\n    v = Rinv @ np.concatenate([np.zeros(vel.n_af), vel.w_av])\n    f = Rinv @ np.concatenate([force.eta_af if force is not None else np.zeros(vel.n_af),\n                               np.zeros(vel.n_av)])\n    return v, f\n", "doc": "World-frame (actuated-coordinate) velocity and force commands, as the authors' code\nprints them: R_a^-1 [0; w_av] and R_a^-1 [eta_af; 0].", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:Gains": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 90, "end": 97, "src": "@dataclass\nclass Gains:\n    K_v: float = 60.0  # N s/m, hfvc velocity servo along c (with K_p on the integrated error)\n    D_f: float = 2.0  # N s/m, hfvc damping on the force-controlled axes\n    K_p: float = 1.0e4  # N/m, velocity controller position gain\n    K_d: float = 60.0  # N s/m, velocity controller velocity gain\n    D_low: float = 6.0  # N s/m, force controller damping (one tenth of K_v)\n    preload: float = 10.0  # N, settle force and the velocity controller's press depth * K_p\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:HFVCCache": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 175, "end": 196, "src": "class HFVCCache:\n    \"\"\"The OCHS solution at the latest measured theta; keeps the last good one on failure.\"\"\"\n\n    def __init__(self, bt):\n        self.bt, self.sol, self.fails, self.t_solve = bt, None, 0, 0.0\n\n    def update(self, theta):\n        t0 = time.perf_counter()\n        s = hfvc.solve_ochs(hfvc.block_tilt_problem(theta, self.bt))\n        self.t_solve += time.perf_counter() - t0\n        if s.ok:\n            # the sign of C is arbitrary; flip it so that w_av >= 0 and the integral along c\n            # keeps its meaning from one solve to the next\n            R_a, w_av, eta_av = s.vel.R_a.copy(), float(s.vel.w_av[0]), float(s.force.eta[-1])\n            if w_av < 0:\n                R_a[-1], w_av, eta_av = -R_a[-1], -w_av, -eta_av\n            Rinv = np.linalg.inv(R_a)\n            self.sol = dict(Rinv=Rinv, c=R_a[-1], w_av=w_av, eta_af=s.force.eta_af.copy(),\n                            eta_av=eta_av, f=s.force.f[6:9].copy(), v=Rinv[:, -1] * w_av)\n        else:\n            self.fails += 1\n        return self.sol\n", "doc": "The OCHS solution at the latest measured theta; keeps the last good one on failure.", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:Trial": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 100, "end": 111, "src": "@dataclass\nclass Trial:\n    sweep: str\n    controller: str\n    L: float = MODEL_L  # m, real cube edge\n    dz: float = 0.0  # m, real table height (the model assumes 0)\n    mu: float = MU_MODEL  # real friction on every contact\n    series: bool = False  # record a 250 Hz trace\n\n    @property\n    def key(self):\n        return f\"{self.sweep}|{self.controller}|{self.L * 1e3:.2f}|{self.dz * 1e3:.2f}|{self.mu:.3f}\"\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:_append_rows": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 358, "end": 367, "src": "def _append_rows(path, rows, fields):\n    new = not path.exists() or path.stat().st_size == 0\n    with open(path, \"a\", newline=\"\") as fh:\n        w = csv.DictWriter(fh, fieldnames=fields)\n        if new:\n            w.writeheader()\n        for r in rows:\n            w.writerow(r)\n        fh.flush()\n        os.fsync(fh.fileno())\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:build": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 121, "end": 141, "src": "def build(trial: Trial):\n    \"\"\"Compile block_tilt.xml with the trial's block size, table height and friction.\"\"\"\n    spec = mujoco.MjSpec.from_file(str(MODEL_XML))\n    h = trial.L / 2\n    spec.geom(\"block\").size = [h, h, h]\n    spec.body(\"block\").pos = [0.0, 0.0, trial.dz + h]\n    spec.geom(\"table\").pos = [0.0, 0.0, trial.dz]\n    # the finger starts where the model puts the hand, x = (0.5 + HAND_X) L_model = 30 mm,\n    # 0.5 mm above the real top face\n    spec.body(\"finger\").pos = [(0.5 + HAND_X) * MODEL_L, 0.0,\n                               trial.dz + trial.L + FINGER_R + 0.0005]\n    for name in (\"table\", \"block\", \"finger\"):\n        spec.geom(name).friction = [trial.mu, 0.005, 0.0001]\n    m = spec.compile()\n    d = mujoco.MjData(m)\n    ids = dict(block=m.body(\"block\").id, finger_body=m.body(\"finger\").id,\n               g_block=m.geom(\"block\").id, g_table=m.geom(\"table\").id,\n               g_finger=m.geom(\"finger\").id,\n               qf=np.array([m.joint(j).qposadr[0] for j in (\"fx\", \"fy\", \"fz\")]),\n               vf=np.array([m.joint(j).dofadr[0] for j in (\"fx\", \"fy\", \"fz\")]))\n    return m, d, ids\n", "doc": "Compile block_tilt.xml with the trial's block size, table height and friction.", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:contact_forces": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 149, "end": 172, "src": "def contact_forces(m, d, ids, buf, vel6):\n    \"\"\"(finger normal, finger tangential, table normal sum, finger touching, finger sliding\n    speed) from the active contacts.\"\"\"\n    fn = ft = tn = slide = 0.0\n    touching = False\n    for i in range(d.ncon):\n        con = d.contact[i]\n        pair = {con.geom1, con.geom2}\n        if ids[\"g_block\"] not in pair:\n            continue\n        mujoco.mj_contactForce(m, d, i, buf)\n        if ids[\"g_finger\"] in pair:\n            touching = True\n            fn += buf[0]\n            ft += math.hypot(buf[1], buf[2])\n            # sliding speed: tangential part of (finger velocity - block velocity at the point)\n            mujoco.mj_objectVelocity(m, d, mujoco.mjtObj.mjOBJ_BODY, ids[\"block\"], vel6, 0)\n            vb = vel6[3:] + np.cross(vel6[:3], con.pos - d.xpos[ids[\"block\"]])\n            vr = d.qvel[ids[\"vf\"]] - vb\n            nrm = con.frame[:3]\n            slide = max(slide, float(np.linalg.norm(vr - nrm * (nrm @ vr))))\n        elif ids[\"g_table\"] in pair:\n            tn += buf[0]\n    return fn, ft, tn, touching, slide\n", "doc": "(finger normal, finger tangential, table normal sum, finger touching, finger sliding\nspeed) from the active contacts.", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:controller_model": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 114, "end": 118, "src": "def controller_model():\n    \"\"\"hfvc.BlockTilt as the controller believes it: nominal cube, table at z = 0.\"\"\"\n    return hfvc.BlockTilt(L=MODEL_L, mass=DENSITY * MODEL_L**3, hand_mass=0.0, g=GRAVITY,\n                          mu_hand=MU_MODEL, mu_table=MU_MODEL, n_min_hand=10.0, n_min_table=0.0,\n                          cone_sides=8, hand_x=HAND_X, omega_goal=OMEGA)\n", "doc": "hfvc.BlockTilt as the controller believes it: nominal cube, table at z = 0.", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:load_rows": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 370, "end": 386, "src": "def load_rows(path=STUDY_CSV):\n    \"\"\"The study CSV as a list of dicts (numbers converted), or [] if it does not exist.\"\"\"\n    path = Path(path)\n    if not path.exists():\n        return []\n    rows = []\n    with open(path, newline=\"\") as fh:\n        for r in csv.DictReader(fh):\n            for k, v in r.items():\n                if k in (\"key\", \"sweep\", \"controller\", \"fail_reason\"):\n                    continue\n                try:\n                    r[k] = float(v) if v != \"\" else math.nan\n                except ValueError:\n                    pass\n            rows.append(r)\n    return rows\n", "doc": "The study CSV as a list of dicts (numbers converted), or [] if it does not exist.", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:main": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 389, "end": 429, "src": "def main(argv=None):\n    ap = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\n    ap.add_argument(\"--quick\", action=\"store_true\", help=\"12 trials instead of 99\")\n    ap.add_argument(\"--fresh\", action=\"store_true\", help=\"delete earlier results first\")\n    ap.add_argument(\"--out\", type=Path, default=STUDY_CSV)\n    args = ap.parse_args(argv)\n    if mujoco is None:\n        sys.exit(\"sim_block_tilt.py needs mujoco==3.14.0 (uv run --script sim_block_tilt.py)\")\n    out = args.out\n    series_path = out.with_name(out.stem.replace(\"_study\", \"\") + \"_timeseries.csv\") \\\n        if out != STUDY_CSV else SERIES_CSV\n    out.parent.mkdir(parents=True, exist_ok=True)\n    if args.fresh:\n        for p in (out, series_path):\n            if p.exists():\n                p.unlink()\n    done = {r[\"key\"] for r in load_rows(out)}\n    trials = [t for t in study_trials(args.quick) if t.key not in done]\n    meta = dict(model=str(MODEL_XML.relative_to(HERE.parents[1])), mujoco=mujoco.__version__,\n                model_L_m=MODEL_L, density=DENSITY, mu_model=MU_MODEL, hand_x=HAND_X,\n                omega=OMEGA, theta_goal_deg=math.degrees(THETA_GOAL), settle_s=SETTLE,\n                t_max_s=T_MAX, control_dt_s=CONTROL_DT, force_limit_N=FORCE_LIMIT,\n                slip_limit_m=SLIP_LIMIT, gap_limit_s=GAP_LIMIT, gains=asdict(Gains()),\n                bt=dict((k, v) for k, v in asdict(controller_model()).items() if k != \"edge\"),\n                started=time.strftime(\"%Y-%m-%d %H:%M:%S\"), quick=args.quick)\n    with open(out.with_suffix(\".json\"), \"w\") as fh:\n        json.dump(meta, fh, indent=1)\n    print(f\"{len(done)} trials already in {out.name}; running {len(trials)}\")\n    fields = None\n    t0 = time.perf_counter()\n    for i, tr in enumerate(trials):\n        series = [] if tr.series else None\n        row = run_trial(tr, series_rows=series)\n        fields = fields or list(row)\n        _append_rows(out, [row], fields)\n        if series:\n            _append_rows(series_path, series, list(series[0]))\n        print(f\"[{i + 1}/{len(trials)}] {tr.key:34s} success={row['success']} \"\n              f\"peak={row['peak_finger_N']:.1f} N slip={row['max_table_slip_mm']:.2f} mm \"\n              f\"gap={row['max_contact_gap_ms']:.0f} ms {row['fail_reason']}\", flush=True)\n    print(f\"done in {time.perf_counter() - t0:.1f} s\")\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:run_trial": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 199, "end": 325, "src": "def run_trial(trial: Trial, gains: Gains = Gains(), series_rows=None):\n    \"\"\"Simulate one trial; returns the result row (dict).\"\"\"\n    wall0 = time.perf_counter()\n    m, d, ids = build(trial)\n    h = m.opt.timestep\n    g_up = np.array([0.0, 0.0, FINGER_MASS * GRAVITY])\n    base = m.body_pos[ids[\"finger_body\"]].copy()\n    buf, vel6 = np.zeros(6), np.zeros(6)\n    bt = controller_model()\n    cache = HFVCCache(bt)\n\n    def finger_state():\n        return base + d.qpos[ids[\"qf\"]], d.qvel[ids[\"vf\"]].copy()\n\n    # settle: press the preload onto the top face\n    for _ in range(int(round(SETTLE / h))):\n        _, v = finger_state()\n        d.ctrl[:] = np.array([0.0, 0.0, -gains.preload]) - 5.0 * v + g_up\n        mujoco.mj_step(m, d)\n\n    R0 = d.xmat[ids[\"block\"]].reshape(3, 3).copy()\n    pb0 = d.xpos[ids[\"block\"]].copy()\n    half = trial.L / 2\n    edge0 = pb0 + R0 @ np.array([half, 0.0, -half])\n    p_start, _ = finger_state()\n    # velocity controller plan: arc about the MODEL edge through the pressed start point\n    e_model = np.array([MODEL_L / 2, 0.0, 0.0])\n    p_anchor = p_start - np.array([0.0, 0.0, gains.preload / gains.K_p])\n\n    stats = dict(peak_fn=0.0, sum_fn=0.0, n_fn=0, peak_tn=0.0, slip=0.0, lift=0.0, fslip=0.0,\n                 gap=0.0, cur_gap=0.0, peak_ctrl=0.0)\n    reached, t_reach, reason = False, math.nan, \"\"\n    steps = int(round(T_MAX / h))\n    every = int(round(CONTROL_DT / h))\n    theta, s_err = 0.0, 0.0\n    for k in range(steps):\n        t = k * h\n        R = d.xmat[ids[\"block\"]].reshape(3, 3)\n        theta = tilt_angle(R)\n        p, v = finger_state()\n        if trial.controller in (\"hfvc\", \"force\") and k % every == 0:\n            cache.update(max(theta, 0.0))\n        if trial.controller == \"hfvc\":\n            s = cache.sol\n            e_v = s[\"w_av\"] - s[\"c\"] @ v\n            s_err += e_v * h  # position error along c: the stiff inner loop of a robot\n            eta_av = s[\"eta_av\"] + gains.K_v * e_v + gains.K_p * s_err\n            f = s[\"Rinv\"] @ np.r_[s[\"eta_af\"], eta_av]\n            f = f - gains.D_f * (v - s[\"c\"] * (s[\"c\"] @ v)) + g_up\n        elif trial.controller == \"velocity\":\n            th_p = min(OMEGA * t, THETA_GOAL)\n            c, sn = math.cos(th_p), math.sin(th_p)\n            Ry = np.array([[c, 0.0, sn], [0.0, 1.0, 0.0], [-sn, 0.0, c]])\n            p_plan = e_model + Ry @ (p_anchor - e_model)\n            v_plan = (np.cross([0.0, OMEGA, 0.0], p_plan - e_model)\n                      if OMEGA * t < THETA_GOAL else np.zeros(3))\n            f = gains.K_p * (p_plan - p) + gains.K_d * (v_plan - v) + g_up\n        elif trial.controller == \"force\":\n            s = cache.sol\n            f = s[\"f\"] + gains.D_low * (s[\"v\"] - v) + g_up\n        else:\n            raise ValueError(trial.controller)\n        d.ctrl[:] = f\n        stats[\"peak_ctrl\"] = max(stats[\"peak_ctrl\"], float(np.linalg.norm(np.clip(f, -200, 200))))\n        mujoco.mj_step(m, d)\n\n        # measurements after the step\n        fn, ft, tn, touching, slide = contact_forces(m, d, ids, buf, vel6)\n        stats[\"fslip\"] += slide * h\n        stats[\"peak_fn\"] = max(stats[\"peak_fn\"], fn)\n        stats[\"peak_tn\"] = max(stats[\"peak_tn\"], tn)\n        if touching:\n            stats[\"sum_fn\"] += fn\n            stats[\"n_fn\"] += 1\n            stats[\"cur_gap\"] = 0.0\n        else:\n            stats[\"cur_gap\"] += h\n            stats[\"gap\"] = max(stats[\"gap\"], stats[\"cur_gap\"])\n        R = d.xmat[ids[\"block\"]].reshape(3, 3)\n        pb = d.xpos[ids[\"block\"]]\n        edge = pb + R @ np.array([half, 0.0, -half])\n        stats[\"slip\"] = max(stats[\"slip\"], float(np.hypot(*(edge - edge0)[:2])))\n        stats[\"lift\"] = max(stats[\"lift\"], float(edge[2] - edge0[2]))\n        theta = tilt_angle(R)\n        if series_rows is not None and k % every == 0:\n            series_rows.append(dict(key=trial.key, sweep=trial.sweep, controller=trial.controller,\n                                    t=round(t + h, 4), theta_deg=math.degrees(theta),\n                                    finger_normal_N=fn, finger_tangential_N=ft, table_normal_N=tn,\n                                    table_slip_mm=1e3 * float(np.hypot(*(edge - edge0)[:2])),\n                                    finger_slide_mm=1e3 * stats[\"fslip\"]))\n        if theta >= THETA_GOAL:\n            reached, t_reach = True, t + h\n            break\n        if theta > math.radians(70):\n            reason = \"block fell over\"\n            break\n        if stats[\"cur_gap\"] > 0.25:\n            reason = \"finger lost the block\"\n            break\n    fails = []\n    if not reached:\n        fails.append(reason or \"did not reach 40 deg in 2.5 s\")\n    if stats[\"slip\"] > SLIP_LIMIT:\n        fails.append(\"table slip\")\n    if stats[\"gap\"] > GAP_LIMIT:\n        fails.append(\"finger contact lost\")\n    if stats[\"peak_fn\"] > FORCE_LIMIT:\n        fails.append(\"finger force above 25 N\")\n    return dict(\n        key=trial.key, sweep=trial.sweep, controller=trial.controller,\n        L_mm=round(trial.L * 1e3, 3), dz_mm=round(trial.dz * 1e3, 3), mu=round(trial.mu, 4),\n        success=int(not fails), reached=int(reached),\n        t_reach_s=round(t_reach, 4) if reached else \"\",\n        theta_end_deg=round(math.degrees(theta), 3),\n        peak_finger_N=round(stats[\"peak_fn\"], 3),\n        mean_finger_N=round(stats[\"sum_fn\"] / max(stats[\"n_fn\"], 1), 3),\n        peak_table_N=round(stats[\"peak_tn\"], 3),\n        max_table_slip_mm=round(1e3 * stats[\"slip\"], 4),\n        max_edge_lift_mm=round(1e3 * stats[\"lift\"], 4),\n        finger_slide_mm=round(1e3 * stats[\"fslip\"], 4),\n        max_contact_gap_ms=round(1e3 * stats[\"gap\"], 2),\n        peak_command_N=round(stats[\"peak_ctrl\"], 3),\n        hfvc_solve_failures=cache.fails,\n        hfvc_solve_ms=round(1e3 * cache.t_solve, 2),\n        fail_reason=\"; \".join(fails),\n        wall_s=round(time.perf_counter() - wall0, 3),\n    )\n", "doc": "Simulate one trial; returns the result row (dict).", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:study_trials": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 331, "end": 355, "src": "def study_trials(quick=False, n_random=20, seed=2026):\n    \"\"\"The trial list: nominal, one-factor sweeps, and random combinations (seeded).\"\"\"\n    out = []\n\n    def add(sweep, series=False, **kw):\n        for c in CONTROLLERS:\n            out.append(Trial(sweep, c, series=series, **kw))\n\n    add(\"nominal\", series=True)\n    if quick:\n        add(\"size\", L=0.078, series=True)\n        add(\"table\", dz=0.0015)\n        add(\"friction\", mu=0.45)\n        return out\n    for L in (0.069, 0.072, 0.078, 0.081):\n        add(\"size\", L=L, series=(L == 0.078))\n    for dz in (-0.003, -0.0015, 0.0015, 0.003):\n        add(\"table\", dz=dz)\n    for mu in (0.3, 0.45, 0.6, 1.0):\n        add(\"friction\", mu=mu)\n    rng = np.random.default_rng(seed)\n    for _ in range(n_random):\n        L, dz, mu = rng.uniform(0.070, 0.080), rng.uniform(-0.002, 0.002), rng.uniform(0.4, 1.0)\n        add(\"random\", L=float(L), dz=float(dz), mu=float(mu))\n    return out\n", "doc": "The trial list: nominal, one-factor sweeps, and random combinations (seeded).", "marimo": false},
"labs/hybrid_servoing/sim_block_tilt.py:tilt_angle": {"file": "labs/hybrid_servoing/sim_block_tilt.py", "start": 144, "end": 146, "src": "def tilt_angle(R):\n    \"\"\"Rotation of the block about +y (its z axis tipping toward +x).\"\"\"\n    return math.atan2(R[0, 2], R[2, 2])\n", "doc": "Rotation of the block about +y (its z axis tipping toward +x).", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:_random_q": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 141, "end": 144, "src": "def _random_q(bt):\n    qO = RNG.standard_normal(4)\n    qO /= np.linalg.norm(qO)\n    return np.concatenate([RNG.uniform(-0.1, 0.1, 3), qO, RNG.uniform(-0.1, 0.1, 3)])\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:accuracy": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 255, "end": 261, "src": "def accuracy(kappa, scale):\n    \"\"\"Tolerance for a quantity computed from a system with condition number kappa.\n\n    Algorithm 1 returns some C whose crashing index is 1e8 (2021 counts such solutions as\n    'ill-conditioned' but solved); a null-space basis or a force solve then carries a relative\n    error of order eps * kappa, so the checks allow 1e-13 * kappa (about 500 eps * kappa).\"\"\"\n    return 1e-9 * scale + 1e-13 * kappa * scale\n", "doc": "Tolerance for a quantity computed from a system with condition number kappa.\n\nAlgorithm 1 returns some C whose crashing index is 1e8 (2021 counts such solutions as\n'ill-conditioned' but solved); a null-space basis or a force solve then carries a relative\nerror of order eps * kappa, so the checks allow 1e-13 * kappa (about 500 eps * kappa).", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:fd_jacobian": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 147, "end": 154, "src": "def fd_jacobian(fun, x, eps=1e-6):\n    f0 = fun(x)\n    Jn = np.zeros((f0.size, x.size))\n    for k in range(x.size):\n        dx = np.zeros_like(x)\n        dx[k] = eps\n        Jn[:, k] = (fun(x + dx) - fun(x - dx)) / (2 * eps)\n    return Jn\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:solved": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 264, "end": 271, "src": "@pytest.fixture(scope=\"module\")\ndef solved():\n    probs = (hfvc.random_problems(150, dim=2, seed=11) + hfvc.random_problems(150, dim=3, seed=12))\n    out = []\n    for i, p in enumerate(probs):\n        out.append((p, hfvc.solve_ochs(p), hfvc.solve_ochs(p, maximal=True),\n                    hfvc.solve_hs(p, 3, rng=i), hfvc.solve_hs(p, 10, rng=i)))\n    return out\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_E_maps_body_angular_velocity_to_quaternion_rate": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 175, "end": 182, "src": "def test_E_maps_body_angular_velocity_to_quaternion_rate():\n    for _ in range(5):\n        q = RNG.standard_normal(4)\n        q /= np.linalg.norm(q)\n        w = RNG.standard_normal(3)\n        h = 1e-6\n        qdot = (hfvc.quat_integrate(q, w, h) - hfvc.quat_integrate(q, w, -h)) / (2 * h)\n        assert np.allclose(hfvc.E_quat(q) @ w, qdot, atol=1e-8)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_N_is_the_rate_of_phi_along_a_motion": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 185, "end": 199, "src": "def test_N_is_the_rate_of_phi_along_a_motion():\n    \"\"\"N v = d/dt Phi(q(t)) when q moves with generalized velocity v (qdot = Omega v).\"\"\"\n    bt = hfvc.BlockTilt()\n    q = _random_q(bt)\n    N = hfvc.block_tilt_jac(q, bt) @ hfvc.block_tilt_omega(q)\n    v = RNG.standard_normal(9)\n    h = 1e-6\n\n    def move(q, s):\n        R = hfvc.quat_to_R(q[3:7])\n        return np.concatenate([q[:3] + s * R @ v[:3], hfvc.quat_integrate(q[3:7], v[3:6], s),\n                               q[7:] + s * v[6:]])\n\n    rate = (hfvc.block_tilt_phi(move(q, h), bt) - hfvc.block_tilt_phi(move(q, -h), bt)) / (2 * h)\n    assert np.allclose(N @ v, rate, atol=1e-7)\n", "doc": "N v = d/dt Phi(q(t)) when q moves with generalized velocity v (qdot = Omega v).", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_alg1_gradient_matches_finite_differences": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 435, "end": 444, "src": "def test_alg1_gradient_matches_finite_differences():\n    for form in hfvc.ALG1_FORMS:\n        n_c, n_av = 5, 3\n        A = RNG.standard_normal((n_c, n_c))\n        M = A @ A.T / n_c\n        K = RNG.standard_normal((n_c, n_av))\n        g = hfvc.alg1_grad(K, M, form)\n        gn = fd_jacobian(lambda x: np.array([hfvc.alg1_cost(x.reshape(n_c, n_av), M, form)]),\n                         K.ravel()).reshape(n_c, n_av)\n        assert np.allclose(g, gn, atol=1e-6)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_alg2_kkt_equals_minimum_norm_solution": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 447, "end": 454, "src": "def test_alg2_kkt_equals_minimum_norm_solution():\n    p = hfvc.block_tilt_problem(0.3)\n    vel = hfvc.alg1_velocity(p, 3, rng=0)\n    force = hfvc.alg2_force(p, vel)\n    ff_kkt, _ = hfvc.alg2_kkt(p, vel, force.eta_af)\n    x = np.concatenate([force.lam, force.eta])\n    _, _, _, i_free, _, _ = hfvc.alg2_newton_system(p, vel)\n    assert np.allclose(ff_kkt, x[i_free], atol=1e-9)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_algorithm1_rejects_underactuated_problems": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 331, "end": 340, "src": "def test_algorithm1_rejects_underactuated_problems():\n    \"\"\"eq. 14 (r_N + n_a >= n) fails when the robot cannot fix every object DOF; OCHS still\n    solves such problems when the goal allows it (2021 Sec. V-D).\"\"\"\n    probs = hfvc.random_problems(40, dim=3, seed=12, settings=[(\"ss\", 1, 1)])\n    under = [p for p in probs if hfvc.svd_rank(p.J) < p.n_u]\n    assert under\n    for p in under:\n        with pytest.raises(hfvc.Infeasible, match=\"eq. 14\"):\n            hfvc.alg1_velocity(p)\n        assert hfvc.solve_ochs(p).ok\n", "doc": "eq. 14 (r_N + n_a >= n) fails when the robot cannot fix every object DOF; OCHS still\nsolves such problems when the goal allows it (2021 Sec. V-D).", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_algorithm2_min_norm_forces_fail_where_the_qp_succeeds": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 395, "end": 410, "src": "def test_algorithm2_min_norm_forces_fail_where_the_qp_succeeds():\n    \"\"\"Algorithm 2 fixes the free forces at their minimum-norm value (2019 eq. 21-23). With three\n    or more contacts the forces are statically indeterminate, and the min-norm distribution can\n    leave a friction cone while another distribution satisfies every guard. The QP of 2021\n    eq. 30 searches every distribution; here it gets the same T as Algorithm 2.\"\"\"\n    fails = 0\n    for p in hfvc.random_problems(120, dim=2, seed=7):\n        s = hfvc.solve_hs(p, 3, rng=0)\n        if s.vel is None or s.ok:\n            continue\n        fails += 1\n        assert len(p.info[\"contacts\"]) >= 3, p.name\n        f = hfvc.ochs_force(p, s.vel)\n        assert hfvc.guard_violation(p, f.lam, f.f) < 1e-6\n        assert hfvc.newton_residual(p, f.lam, f.f) < 1e-7\n    assert fails >= 10\n", "doc": "Algorithm 2 fixes the free forces at their minimum-norm value (2019 eq. 21-23). With three\nor more contacts the forces are statically indeterminate, and the min-norm distribution can\nleave a friction cone while another distribution satisfies every guard. The QP of 2021\neq. 30 searches every distribution; here it gets the same T as Algorithm 2.", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_block_tilting_crashing_index_depends_on_units": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 240, "end": 247, "src": "def test_block_tilting_crashing_index_depends_on_units():\n    \"\"\"The crashing index mixes metres and radians: the hand's share of the free motion is\n    |r| / sqrt(1 + |r|^2), so a 75 mm cube gives 26.6 and a 1 m cube gives a smaller value.\"\"\"\n    small = hfvc.solve_ochs(hfvc.block_tilt_problem(0.2, hfvc.BlockTilt())).crash\n    big = hfvc.solve_ochs(hfvc.block_tilt_problem(0.2, hfvc.BlockTilt(L=1.0, n_min_hand=1.0,\n                                                                     n_min_table=0.0))).crash\n    assert small == pytest.approx(26.57, abs=0.01)\n    assert big < 5\n", "doc": "The crashing index mixes metres and radians: the hand's share of the free motion is\n|r| / sqrt(1 + |r|^2), so a 75 mm cube gives 26.6 and a 1 m cube gives a smaller value.", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_block_tilting_solution": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 202, "end": 237, "src": "@pytest.mark.parametrize(\"deg\", [0, 15, 30, 45])\ndef test_block_tilting_solution(deg):\n    \"\"\"2019 Sec. V-E: one velocity-controlled direction along the tilting arc, two force-controlled\n    directions, a force command with no y part that presses toward the rotation axis.\"\"\"\n    bt = hfvc.BlockTilt()\n    prob = hfvc.block_tilt_problem(math.radians(deg), bt)\n    assert hfvc.svd_rank(prob.J) == 8  # one free motion: rotation about the edge\n    R = prob.info[\"R\"]\n    r = R @ bt.p_hc  # hand relative to the rotation edge, world frame\n    arc = bt.omega_goal * np.cross([0, 1, 0], r)  # planned hand velocity, omega_goal (y x r)\n    ochs = hfvc.solve_ochs(prob)\n    hs = hfvc.solve_hs(prob, 3, rng=deg)  # the authors' settings: t = 10, 50 iterations\n    hs500 = hfvc.solve_hs(prob, 3, rng=deg, iters=500)\n    for sol in (ochs, hs, hs500):\n        assert sol.ok, sol.message\n        vel, force = sol.vel, sol.force\n        assert (vel.n_av, vel.n_af) == (1, 2)\n        assert np.allclose(vel.v_star[6:], arc, atol=1e-12)  # the unique solution is the plan\n        assert vel.w_av == pytest.approx(vel.C @ vel.v_star)\n        assert hfvc.guard_violation(prob, force.lam, force.f) < 1e-7\n        assert hfvc.newton_residual(prob, force.lam, force.f) < 1e-9\n    for sol in (ochs, hs500):\n        v_world, f_world = hfvc.world_commands(sol.vel, sol.force, 6)\n        # the velocity command moves the hand along the arc\n        assert np.allclose(v_world, arc, atol=1e-9)\n        # the force command has no y part and presses along -r (toward the rotation axis)\n        assert abs(f_world[1]) < 1e-8\n        assert np.linalg.norm(np.cross(f_world, r)) < 1e-6 * np.linalg.norm(f_world)\n        assert f_world @ r < 0\n    assert hs500.crash == pytest.approx(ochs.crash, rel=1e-9)\n    # With the authors' 50 iterations the direction stops short of the optimum: the top eigenvalue\n    # of M is 0.0057, so 50 steps of (I + 20 M) shrink the start error only by 1.113^50 = 211.\n    c, c_opt = hs.vel.C[0, 6:], ochs.vel.C[0, 6:]\n    angle = math.degrees(math.acos(min(1.0, abs(c @ c_opt) / np.linalg.norm(c))))\n    assert angle < 2.0\n    assert ochs.crash <= hs.crash < ochs.crash * 1.001\n", "doc": "2019 Sec. V-E: one velocity-controlled direction along the tilting arc, two force-controlled\ndirections, a force command with no y part that presses toward the rotation axis.", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_cone_directions_circumscribe_the_circle": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 457, "end": 462, "src": "def test_cone_directions_circumscribe_the_circle():\n    D = hfvc.cone_directions(8)\n    assert np.allclose(np.linalg.norm(D, axis=1), 1)\n    ang = np.linspace(0, 2 * np.pi, 721)\n    circle = np.stack([np.cos(ang), np.sin(ang)], axis=1)\n    assert np.all(circle @ D.T <= 1 + 1e-12)  # the unit circle lies inside the octagon\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_crashing_index_ignores_row_scaling_and_redundant_rows": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 126, "end": 133, "src": "def test_crashing_index_ignores_row_scaling_and_redundant_rows():\n    J = hfvc.fig1_problem(\"pivot\").J\n    C = hfvc.fig1_C(\"diag\")\n    ref = hfvc.crashing_index(J, C)\n    assert hfvc.crashing_index(np.vstack([J, 3 * J[:2]]), 1000 * C) == pytest.approx(ref)\n    assert hfvc.crashing_index(np.diag([1, 10, 0.1, 5.0])[: J.shape[0], : J.shape[0]] @ J, C) == pytest.approx(ref)\n    # the raw condition number is not invariant: artificial ill-conditioning\n    assert hfvc.cond_rows(np.vstack([J, 1000 * C])) > 10 * ref\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_drawer_crashing_index_formula": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 120, "end": 123, "src": "def test_drawer_crashing_index_formula():\n    for th in (0.0, 30.0, 60.0, 85.0):\n        c = math.sqrt((1 + math.sin(math.radians(th)) ** 2) / 2)\n        assert hfvc.drawer_crashing_index(th) == pytest.approx(math.sqrt((1 + c) / (1 - c)))\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_drawer_matches_deck_02": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 109, "end": 117, "src": "def test_drawer_matches_deck_02():\n    for th, cond in [(0, 1.0), (45, 2.414), (60, 3.732), (80, 11.43), (85, 22.90), (89, 114.6)]:\n        assert hfvc.drawer_system(th)[\"cond\"] == pytest.approx(cond, rel=1e-3)\n        assert hfvc.drawer_system(th)[\"cond\"] == pytest.approx(math.tan(math.radians(45 + th / 2)))\n    d = hfvc.drawer_system(85, 2.0)\n    assert d[\"speed_model\"] == pytest.approx(11.47, abs=0.01)\n    assert d[\"speed_true\"] == pytest.approx(8.21, abs=0.01)\n    assert hfvc.drawer_system(85, -2.0)[\"speed_true\"] == pytest.approx(19.11, abs=0.01)\n    assert not hfvc.drawer_system(88, -2.0)[\"feasible\"]\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_fig1_crashing_indexes_reproduced": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 79, "end": 89, "src": "def test_fig1_crashing_indexes_reproduced():\n    \"\"\"The six printed values 2.41, 3.87, inf, 7.10, 10.48, inf, to their two decimals.\n\n    Reconstruction (hfvc.py section 9): block + point finger sticking at the top centre;\n    top row slides on two frictionless-normal corner contacts, bottom row sticks on a pivot;\n    V to the right, V diagonal at 46.78 deg below horizontal, V down; block height 0.2904.\"\"\"\n    for row in hfvc.fig1_table():\n        if math.isinf(row[\"paper\"]):\n            assert math.isinf(row[\"ours\"])\n        else:\n            assert round(row[\"ours\"], 2) == pytest.approx(row[\"paper\"], abs=1e-9), row\n", "doc": "The six printed values 2.41, 3.87, inf, 7.10, 10.48, inf, to their two decimals.\n\nReconstruction (hfvc.py section 9): block + point finger sticking at the top centre;\ntop row slides on two frictionless-normal corner contacts, bottom row sticks on a pivot;\nV to the right, V diagonal at 46.78 deg below horizontal, V down; block height 0.2904.", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_fig1_fit_parameters": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 101, "end": 106, "src": "def test_fig1_fit_parameters():\n    fit = hfvc.fig1_fit()\n    assert fit[\"phi_deg\"] == pytest.approx(hfvc.FIG1_PHI_DEG, abs=0.01)\n    assert fit[\"h\"] == pytest.approx(hfvc.FIG1_H, abs=1e-3)\n    assert max(abs(r) for r in fit[\"residuals\"]) < 0.002\n    assert fit[\"phi_from_387\"] == pytest.approx(46.755, abs=0.01)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_fig1_top_row_is_geometry_free": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 92, "end": 98, "src": "def test_fig1_top_row_is_geometry_free():\n    for h in (0.05, 0.29, 1.0, 3.0):\n        for w in (0.1, 1.0):\n            J = hfvc.fig1_problem(\"ground\", h=h, w=w).J\n            assert hfvc.crashing_index(J, hfvc.fig1_C(\"right\")) == pytest.approx(1 + math.sqrt(2))\n            assert hfvc.crashing_index(J, hfvc.fig1_C(\"diag\", 45.0)) == pytest.approx(2 + math.sqrt(3))\n            assert math.isinf(hfvc.crashing_index(J, hfvc.fig1_C(\"down\")))\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_goal_inclusion_holds_for_every_returned_solution": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 281, "end": 292, "src": "def test_goal_inclusion_holds_for_every_returned_solution(solved):\n    n = 0\n    for p, *sols in solved:\n        for s in sols:\n            if s.vel is None:\n                continue\n            gi = hfvc.goal_inclusion(p.J, p.G, p.b_G, s.vel.C, s.vel.w_av)\n            assert gi.ok, (p.name, s.method)\n            kappa = hfvc.cond_rows(np.vstack([p.J, s.vel.C]))\n            assert gi.sampled_goal_error < accuracy(kappa, 1 + np.abs(p.b_G).max()), (p.name, s.method)\n            n += 1\n    assert n > 900\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_guard_conditions_hold_for_every_returned_solution": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 295, "end": 305, "src": "def test_guard_conditions_hold_for_every_returned_solution(solved):\n    for p, *sols in solved:\n        for s in sols:\n            if not s.ok:\n                continue\n            kappa = max(s.crash if np.isfinite(s.crash) else 1.0, np.linalg.cond(s.vel.T))\n            scale = 1 + np.linalg.norm(p.F) + np.linalg.norm(s.force.lam) + np.linalg.norm(s.force.f)\n            assert hfvc.guard_violation(p, s.force.lam, s.force.f) < 1e-6 + accuracy(kappa, scale), (p.name, s.method)\n            assert hfvc.newton_residual(p, s.force.lam, s.force.f) < accuracy(kappa, scale), (p.name, s.method)\n            f_u = s.force.f[:p.n_u]\n            assert np.allclose(f_u, 0, atol=1e-8)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_least_distance_detects_infeasibility": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 67, "end": 71, "src": "def test_least_distance_detects_infeasibility():\n    A = np.array([[1.0, 0.0], [-1.0, 0.0]])\n    b = np.array([-1.0, -1.0])  # x <= -1 and x >= 1\n    _, ok = hfvc.least_distance(A, b)\n    assert not ok\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_least_distance_matches_slsqp": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 49, "end": 64, "src": "def test_least_distance_matches_slsqp():\n    for _ in range(15):\n        n, mi, me = 4, 5, 1\n        A, E = RNG.standard_normal((mi, n)), RNG.standard_normal((me, n))\n        x_feas = RNG.standard_normal(n)\n        b = A @ x_feas + RNG.uniform(0.0, 1.0, mi) - 1.0 * (RNG.uniform(size=mi) < 0.5)\n        b = np.maximum(b, A @ x_feas)  # x_feas stays feasible\n        e = E @ x_feas\n        x, ok = hfvc.least_distance(A, b, E, e)\n        assert ok\n        ref = minimize(lambda z: z @ z, x_feas, jac=lambda z: 2 * z, method=\"SLSQP\",\n                       constraints=[dict(type=\"ineq\", fun=lambda z: b - A @ z, jac=lambda z: -A),\n                                    dict(type=\"eq\", fun=lambda z: E @ z - e, jac=lambda z: E)],\n                       options=dict(ftol=1e-14, maxiter=500))\n        assert np.all(A @ x <= b + 1e-8) and np.allclose(E @ x, e, atol=1e-9)\n        assert x @ x <= ref.fun + 1e-7\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_minimal_and_maximal_ochs_agree_when_dimensions_match": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 323, "end": 328, "src": "def test_minimal_and_maximal_ochs_agree_when_dimensions_match():\n    probs = hfvc.random_problems(60, dim=3, seed=5, goal=\"max\")\n    for p in probs:\n        o, m = hfvc.solve_ochs(p), hfvc.solve_ochs(p, maximal=True)\n        assert o.vel.n_av == m.vel.n_av\n        assert o.crash == pytest.approx(m.crash, rel=1e-9)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_no_random_goal_inclusive_C_beats_ochs": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 359, "end": 369, "src": "def test_no_random_goal_inclusive_C_beats_ochs(solved):\n    rng = np.random.default_rng(1)\n    k = 0\n    for p, o, *_ in solved[::3]:\n        if o.vel is None or o.vel.n_av == 0:\n            continue\n        for _ in range(20):\n            C = hfvc.random_valid_C(p, rng)\n            assert hfvc.crashing_index(p.J, C) >= o.crash * (1 - 1e-9), p.name\n            k += 1\n    assert k > 1500\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_nominal_hfvc_trial_succeeds": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 470, "end": 477, "src": "def test_nominal_hfvc_trial_succeeds():\n    pytest.importorskip(\"mujoco\")\n    import sim_block_tilt as sim\n\n    row = sim.run_trial(sim.Trial(\"nominal\", \"hfvc\"))\n    assert row[\"success\"] == 1, row[\"fail_reason\"]\n    assert row[\"peak_finger_N\"] < 12.0\n    assert abs(row[\"t_reach_s\"] - sim.THETA_GOAL / sim.OMEGA) < 0.1\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_null_and_row_bases_are_orthonormal_complements": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 28, "end": 37, "src": "def test_null_and_row_bases_are_orthonormal_complements():\n    for _ in range(20):\n        m, n = RNG.integers(1, 6), RNG.integers(2, 8)\n        r = RNG.integers(1, min(m, n) + 1)\n        A = RNG.standard_normal((m, r)) @ RNG.standard_normal((r, n))\n        Z, W = hfvc.null_rows(A), hfvc.row_rows(A)\n        assert Z.shape == (n - r, n) and W.shape == (r, n)\n        B = np.vstack([Z, W])\n        assert np.allclose(B @ B.T, np.eye(n), atol=1e-10)\n        assert np.allclose(A @ Z.T, 0, atol=1e-10)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_object_goals_rejected_only_when_no_valid_C_exists": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 413, "end": 427, "src": "def test_object_goals_rejected_only_when_no_valid_C_exists():\n    \"\"\"goal='object': OCHS rejects a problem at eq. 25 only when no command in the shared\n    search space S = span(B_c) can meet the goal (rank [J; C] < rank [J; G] for C = B_c^T).\"\"\"\n    rejected = 0\n    for i, p in enumerate(hfvc.random_problems(80, dim=3, seed=3, goal=\"object\")):\n        o = hfvc.solve_ochs(p)\n        if o.ok:\n            gi = hfvc.goal_inclusion(p.J, p.G, p.b_G, o.vel.C, o.vel.w_av)\n            assert gi.ok\n            continue\n        assert \"eq. 25\" in o.message, o.message\n        Bc = hfvc.alg1_basis(p, check=False)[\"Bc\"]\n        assert hfvc.svd_rank(np.vstack([p.J, Bc.T])) < hfvc.svd_rank(np.vstack([p.J, p.G]))\n        rejected += 1\n    assert rejected >= 1\n", "doc": "goal='object': OCHS rejects a problem at eq. 25 only when no command in the shared\nsearch space S = span(B_c) can meet the goal (rank [J; C] < rank [J; G] for C = B_c^T).", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_ochs_K_has_exactly_n_av_rows": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 372, "end": 376, "src": "def test_ochs_K_has_exactly_n_av_rows(solved):\n    \"\"\"span(U_bar) meets ROW(J) only at 0, so rows(K) <= n_av; eq. 25 holds with equality.\"\"\"\n    for p, o, *_ in solved:\n        if o.vel is not None and \"K\" in o.vel.info:\n            assert o.vel.info[\"K\"].shape[0] == o.vel.n_av\n", "doc": "span(U_bar) meets ROW(J) only at 0, so rows(K) <= n_av; eq. 25 holds with equality.", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_ochs_attains_the_eigenvalue_bound": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 343, "end": 356, "src": "def test_ochs_attains_the_eigenvalue_bound(solved):\n    \"\"\"crash(OCHS) = sqrt((1 + c) / (1 - c)) with c^2 = 1 - lambda_{n_av}(M), and the rows of the\n    OCHS C span the top n_av eigenvectors of the matrix M of 2019 Algorithm 1 (crash_bound).\"\"\"\n    k = 0\n    for p, o, *_ in solved:\n        if o.vel is None or o.vel.n_av == 0:\n            continue\n        bound, _, W = hfvc.crash_bound(p)\n        assert o.crash == pytest.approx(bound, rel=1e-6), p.name\n        P_ochs = o.vel.C.T @ o.vel.C\n        P_top = W.T @ np.linalg.solve(W @ W.T, W)\n        assert np.allclose(P_ochs, P_top, atol=1e-8), p.name\n        k += 1\n    assert k > 250\n", "doc": "crash(OCHS) = sqrt((1 + c) / (1 - c)) with c^2 = 1 - lambda_{n_av}(M), and the rows of the\nOCHS C span the top n_av eigenvectors of the matrix M of 2019 Algorithm 1 (crash_bound).", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_ochs_never_worse_than_algorithm_1": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 312, "end": 320, "src": "def test_ochs_never_worse_than_algorithm_1(solved):\n    compared = 0\n    for p, o, m, h3, h10 in solved:\n        for h in (h3, h10):\n            if o.vel is None or h.vel is None or o.vel.n_av == 0:\n                continue\n            assert o.crash <= h.crash * (1 + 1e-6) + 1e-9, (p.name, h.method, o.crash, h.crash)\n            compared += 1\n    assert compared > 300\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_ochs_solves_every_feasible_random_problem": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 308, "end": 309, "src": "def test_ochs_solves_every_feasible_random_problem(solved):\n    assert all(o.ok for _, o, *_ in solved)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_pairwise_term_is_unstable_at_step_10": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 379, "end": 392, "src": "def test_pairwise_term_is_unstable_at_step_10():\n    \"\"\"2019 Sec. IV-A uses t = 10. Under the authors' gradient the inner product s of two unit\n    columns maps to s (1 - 4 t) + O(s^3) when M = 0, so the pairwise term of eq. 15 contracts\n    only for t < 0.5.\"\"\"\n\n    def run(t):\n        K = np.array([[1.0, 0.1], [0.0, math.sqrt(0.99)]])\n        for _ in range(30):\n            K = K - t * hfvc.alg1_grad(K, np.zeros((2, 2)), \"code\")\n            K /= np.linalg.norm(K, axis=0)\n        return abs(K[:, 0] @ K[:, 1])\n\n    assert run(10.0) > 0.1 and run(1.0) > 0.1\n    assert run(0.4) < 1e-5 and run(0.2) < 1e-12\n", "doc": "2019 Sec. IV-A uses t = 10. Under the authors' gradient the inner product s of two unit\ncolumns maps to s (1 - 4 t) + O(s^3) when M = 0, so the pairwise term of eq. 15 contracts\nonly for t < 0.5.", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_phi_jacobian_matches_finite_differences": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 157, "end": 163, "src": "@pytest.mark.parametrize(\"trial\", range(6))\ndef test_phi_jacobian_matches_finite_differences(trial):\n    bt = hfvc.BlockTilt()\n    q = hfvc.block_tilt_state(0.3 * trial, bt) if trial < 3 else _random_q(bt)\n    Jq = hfvc.block_tilt_jac(q, bt)\n    Jn = fd_jacobian(lambda x: hfvc.block_tilt_phi(x, bt), q)\n    assert np.max(np.abs(Jq - Jn)) < 1e-8\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_random_goals_are_feasible": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 274, "end": 278, "src": "def test_random_goals_are_feasible(solved):\n    for p, *_ in solved:\n        _, res = hfvc.special_solution(np.vstack([p.J, p.G]),\n                                       np.concatenate([np.zeros(p.J.shape[0]), p.b_G]))\n        assert res < 1e-9\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_rank_of_numerically_zero_product_is_zero": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 40, "end": 46, "src": "def test_rank_of_numerically_zero_product_is_zero():\n    # the case that dropped a row of K in eq. 24 before ATOL existed\n    Z = hfvc.null_rows(RNG.standard_normal((3, 5)))\n    W = hfvc.row_rows(RNG.standard_normal((3, 5)))\n    P = Z @ W.T @ np.zeros((3, 3)) + 1e-17 * RNG.standard_normal((2, 3))\n    assert hfvc.svd_rank(P) == 0\n    assert hfvc.null_rows(P, 3).shape == (3, 3)\n", "doc": "", "marimo": false},
"labs/hybrid_servoing/test_hfvc.py:test_rotation_derivative_matches_finite_differences": {"file": "labs/hybrid_servoing/test_hfvc.py", "start": 166, "end": 172, "src": "def test_rotation_derivative_matches_finite_differences():\n    for _ in range(5):\n        q = RNG.standard_normal(4)\n        q /= np.linalg.norm(q)\n        p = RNG.standard_normal(3)\n        Jn = fd_jacobian(lambda x: hfvc.quat_to_R(x) @ p, q)\n        assert np.allclose(hfvc.dRp_dq(q, p), Jn, atol=1e-8)\n", "doc": "", "marimo": false},
"mjview.py:Unavailable": {"file": "mjview.py", "start": 90, "end": 114, "src": "class Unavailable:\n    \"\"\"Stand-in returned by show() when mujoco or mjviser is missing.\"\"\"\n\n    def __init__(self, reason: str, height: int = 480):\n        self.error = reason\n        self.url = None\n        self.port = None\n        self.iframe = _message_html(\"mjviser viewer unavailable: \" + reason, height)\n        self.lock = threading.Lock()\n        self.running = False\n\n    def update(self, data=None):\n        return self\n\n    def run(self, step_fn=None, seconds=5.0, speed=1.0, fps=30):\n        return None\n\n    def join(self, timeout=None):\n        return self\n\n    def stop(self):\n        return None\n\n    def _repr_html_(self):\n        return self.iframe\n", "doc": "Stand-in returned by show() when mujoco or mjviser is missing.", "marimo": false},
"mjview.py:View": {"file": "mjview.py", "start": 117, "end": 222, "src": "class View:\n    \"\"\"A running viser server that shows one MuJoCo model; made by show().\"\"\"\n\n    def __init__(self, model, data, port, height, host, contacts):\n        import mujoco\n        import viser\n        from mjviser.scene import ViserMujocoScene\n\n        self._mj = mujoco\n        self.model = model\n        self.data = data\n        self.height = int(height)\n        self.lock = threading.Lock()\n        self._thread: threading.Thread | None = None\n        self._halt = threading.Event()\n        port = int(port) if port else _free_port(host)\n        try:\n            self.server = viser.ViserServer(host=host, port=port, verbose=False)\n        except TypeError:  # viser releases without the verbose flag\n            self.server = viser.ViserServer(host=host, port=port)\n        self.port = self.server.get_port()\n        self.url = f\"http://localhost:{self.port}\"\n        self.dead = False\n        try:\n            # The scene rescales model.vis (contact and frame widths) in place; give it a copy.\n            self.scene = ViserMujocoScene(self.server, copy.copy(model), num_envs=1)\n            self.scene.camera_tracking_enabled = False\n            if contacts:\n                self.scene.show_contact_points = True\n                self.scene.show_contact_forces = True\n            self.update()\n        except BaseException:\n            self.dead = True\n            self.server.stop()\n            raise\n\n    @property\n    def iframe(self) -> str:\n        return (\n            f'<iframe src=\"{self.url}\" width=\"100%\" height=\"{self.height}\" '\n            'style=\"border:1px solid #999\" title=\"mjviser\"></iframe>'\n        )\n\n    def _repr_html_(self):\n        return self.iframe\n\n    @property\n    def running(self) -> bool:\n        return self._thread is not None and self._thread.is_alive()\n\n    def update(self, data=None):\n        \"\"\"Push the poses (and contacts) of data, default the data given to show().\"\"\"\n        if self.dead:\n            return self\n        with self.lock:\n            self.scene.update_from_mjdata(self.data if data is None else data)\n        return self\n\n    def run(self, step_fn=None, seconds=5.0, speed=1.0, fps=30):\n        \"\"\"Step in a background thread for `seconds` of simulation time; returns the thread.\"\"\"\n        if self.dead:\n            raise RuntimeError(\"mjview: this View was stopped\")\n        self._end_run()\n        step = step_fn or self._mj.mj_step\n        m, d, h = self.model, self.data, self.model.opt.timestep\n        t_end = d.time + float(seconds)\n        frame = 1.0 / max(1.0, float(fps))\n        halt = self._halt = threading.Event()\n\n        def loop():\n            wall0, sim0 = time.perf_counter(), d.time\n            while not halt.is_set() and d.time < t_end - 0.5 * h:\n                target = min(t_end, sim0 + (time.perf_counter() - wall0) * speed)\n                with self.lock:\n                    n = 0\n                    while d.time < target - 0.5 * h and n < 100000:\n                        step(m, d)\n                        n += 1\n                    self.scene.update_from_mjdata(d)\n                halt.wait(frame)\n\n        self._thread = threading.Thread(target=loop, name=f\"mjview:{self.port}\", daemon=True)\n        self._thread.start()\n        return self._thread\n\n    def join(self, timeout=None):\n        if self._thread is not None:\n            self._thread.join(timeout)\n        return self\n\n    def _end_run(self):\n        self._halt.set()\n        if self._thread is not None:\n            self._thread.join(5.0)\n        self._thread = None\n\n    def stop(self):\n        \"\"\"End the run() thread and stop the viser server.\"\"\"\n        if self.dead:\n            return\n        self._end_run()\n        self.dead = True\n        self.server.stop()\n        for k, v in list(_LIVE.items()):\n            if v is self:\n                del _LIVE[k]\n", "doc": "A running viser server that shows one MuJoCo model; made by show().", "marimo": false},
"mjview.py:_free_port": {"file": "mjview.py", "start": 76, "end": 79, "src": "def _free_port(host: str) -> int:\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n        s.bind((host, 0))\n        return s.getsockname()[1]\n", "doc": "", "marimo": false},
"mjview.py:_message_html": {"file": "mjview.py", "start": 82, "end": 87, "src": "def _message_html(text: str, height: int) -> str:\n    return (\n        f'<div style=\"height:{int(height)}px;display:flex;align-items:center;justify-content:center;'\n        'border:1px solid #999;font-family:Times New Roman,serif;color:#555;padding:0 1em\">'\n        f\"{html.escape(text)}</div>\"\n    )\n", "doc": "", "marimo": false},
"mjview.py:available": {"file": "mjview.py", "start": 62, "end": 73, "src": "def available() -> str | None:\n    \"\"\"None when mujoco and mjviser import; otherwise the reason they do not.\"\"\"\n    try:\n        import mujoco  # noqa: F401\n    except ImportError as e:\n        return f\"mujoco is not installed ({e})\"\n    try:\n        import mjviser.scene  # noqa: F401\n        import viser  # noqa: F401\n    except ImportError as e:\n        return f\"mjviser is not installed ({e}); pip install mjviser\"\n    return None\n", "doc": "None when mujoco and mjviser import; otherwise the reason they do not.", "marimo": false},
"mjview.py:show": {"file": "mjview.py", "start": 225, "end": 238, "src": "def show(model, data, port=None, height=480, host=\"127.0.0.1\", contacts=True, key=\"default\"):\n    \"\"\"A View of model/data served by viser, or an Unavailable stand-in (see the module doc).\"\"\"\n    why = available()\n    if why is not None:\n        return Unavailable(why, height)\n    old = _LIVE.pop(key, None)\n    if old is not None:\n        old.stop()\n    try:\n        view = View(model, data, port, height, host, contacts)\n    except Exception as e:  # noqa: BLE001 - a port in use, a model mjviser cannot draw\n        return Unavailable(f\"{type(e).__name__}: {e}\", height)\n    _LIVE[key] = view\n    return view\n", "doc": "A View of model/data served by viser, or an Unavailable stand-in (see the module doc).", "marimo": false},
"mjview.py:stop": {"file": "mjview.py", "start": 241, "end": 245, "src": "def stop(key=\"default\"):\n    \"\"\"Stop the View that show(..., key=key) started, if it is still running.\"\"\"\n    view = _LIVE.pop(key, None)\n    if view is not None:\n        view.stop()\n", "doc": "Stop the View that show(..., key=key) started, if it is still running.", "marimo": false},
"mjview.py:stop_all": {"file": "mjview.py", "start": 248, "end": 251, "src": "def stop_all():\n    \"\"\"Stop every View this module started.\"\"\"\n    for v in list(_LIVE.values()):\n        v.stop()\n", "doc": "Stop every View this module started.", "marimo": false}
};
